(window.GIM_TS=window.GIM_TS||{})["Eruvin.0"]={"from":0,"a":[["\u0003מבוי\u0004 (סימטא, רחוב צר) הסגור משלושה צדדים, מותר לטלטל בו בשבת על ידי הנחת קורה בגובה פתחו. במקרה \u0003שהוא גבוה למעלה מעשרים אמה — ימעט\u0004 גובה זה, באופן שיהא פחות מעשרים אמה. \u0003ר' יהודה אומר: אינו צריך\u0004 למעט, כיון שאף בגובה זה מתירה הקורה את הטלטול במבוי.","ואם היה פתח המבוי \u0003רחב\u0004 יותר \u0003מעשר אמות — ימעט. ואם יש לו\u0004 למבוי \u0003צורת הפתח,\u0004 כלומר, שיש בשני צידיו שני עמודים, ועליהם עמוד נוסף, והרי זה כדלת שיש לה שתי מזוזות ומשקוף על גביהן, \u0003אף על פי שהוא רחב מעשר אמות — אין צריך למעט,\u0004 שכן הפתח מכשיר את המבוי בטלטול בשבת, אפילו הוא רחב ביותר.","\u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם\u0006 במסכת סוכה\u0005]\u0006: \u0003סוכה שהיא גבוהה למעלה מעשרים אמה — פסולה, ור' יהודה מכשיר.\u0004 ההלכות דומות איפוא בעיקרן, אלא שהן שונות בסגנונן. ושואלים על כך: \u0003מאי שנא גבי\u0004 \u0005[\u0006ב\u0005מה שונה אצל]\u0006 \u0003סוכה דתני\u0004 \u0005[ששנה\u0006 בה במשנה לשון\u0005]\u0006 \u0003\"פסולה\" וגבי\u0004 \u0005[ואצל]\u0006 \u0003מבוי תני תקנתא\u0004 \u0005[שנה\u0006 לשון \u0005תקנה\u0006 שימעט\u0005]\u0006?","ומשיבים: \u0003סוכה,\u0004 כיון שמצוותה \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003תני\u0004 \u0005[שנה]\u0006 בה \u0003\"פסולה\",\u0004 שכן אם לא עשאה כראוי אינה מצווה. ואילו היתר \u0003מבוי,\u0004 שכל עיקרו הוא \u0003דרבנן\u0004 \u0005[מדברי חכמים],\u0006 \u0003תני תקנתא\u0004 \u0005[שנה תקנה],\u0006 שהרי היתר המבוי אינו אלא לתקנה, ואינו מצוה מן התורה.","\u0003ואיבעית אימא: דאורייתא נמי תני תקנתא\u0004 \u0005[ואם תרצה אמור\u0006 הסבר אחר: בדברים \u0005שמן התורה גם כן שונה\u0006 במשנה \u0005תקנה]\u0006 \u0003אלא,\u0004 בענין \u0003סוכה דנפישין מיליה\u0004 \u0005[שמרובים דבריו,\u0006 הלכותיו\u0005] —\u0006 \u0003פסיק ותני [\u0004\u0005פסק ושנה]\u0006 \u0003\"פסולה\",\u0004 שהרי לא די בהכשר סוכה שתהיה בגובה המתאים, אלא דרוש שיהא בה שטח מספיק ודפנות וסכך כהלכתם. ואילו \u0003מבוי דלא נפישי מיליה\u0004 \u0005[שאין מרובים דבריו,\u0006 הלכותיו\u0005] —\u0006 \u0003תני תקנתא\u0004 \u0005[שנה תקנה],\u0006 שאם ימעטו את גובה הקורה, יותר המבוי בטלטול.","\u0003אמר רב יהודה אמר רב: חכמים לא למדוה\u0004 להלכה זאת שפתח הגבוה למעלה מעשרים אמה אינו קרוי פתח, \u0003אלא מפתחו של היכל\u0004 שבמקדש. \u0003ור' יהודה לא למדה\u0004 לשיטתו, שאף הגבוה משיעור זה קרוי פתח, \u0003אלא מפתחו של אולם\u0004 שבמקדש.","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003פתחו של היכל גבהו עשרים אמה ורחבו עשר אמות, ושל אולם גבהו ארבעים אמה ורחבו עשרים אמות.\u0004","\u0003ושניהן\u0004 חכמים ור' יהודה \u0003מקרא אחד דרשו:\u0004 \"וסמך ידו על ראש קרבנו \u0003ושחטו פתח אהל מועד\u0004 וזרקו בני אהרן הכהנים את הדם על המזבח סביב\" (ויקרא ג, ב) \u0003דרבנן סברי\u0004 \u0005[שחכמים סברו]:\u0006 \u0003קדושת היכל לחוד, וקדושת אולם לחוד.\u0004 שיש הבדל בדרגות הקדושה בין היכל ואולם, ועיקרו של המקדש בהיכל הוא ולא באולם. \u0003וכי כתיב\u0004 \u0005[וכאשר נאמר]\u0006 \u0003\"פתח אהל מועד\" — אהיכל כתיב\u0004 \u0005[על\u0006 פתח \u0005ההיכל נאמר]\u0006 ומכאן נלמד שהמושג 'פתח' מתייחס על פי הכתוב לפתחו של היכל בלבד, שגובהו עשרים אמה, והגבוה מזה איננו יודעים אם קרוי פתח כלל.","\u0003ו\u0004אילו \u0003ר' יהודה סבר: היכל ואולם, קדושה אחת היא. וכי כתיב\u0004 \u0005[ומה שנאמר]\u0006 \u0003\"פתח אהל מועד\" אתרוייהו הוא דכתיב\u0004 \u0005[על שניהם הוא שנאמר],\u0006 והמושג 'פתח' יכול להתייחס גם לפתח גדול יותר.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור\u0006 הסבר אחר\u0005]:\u0006 \u0003לר' יהודה נמי\u0004 \u0005[גם כן]\u0006 \u0003קדושת אולם לחוד וקדושת היכל לחוד. והכא היינו טעמא\u0004 \u0005[וכאן זהו הטעם]\u0006 של \u0003ר' יהודה\u0004 — שמצירוף לשונם של כמה פסוקים יחד \u0003כתיב\u0004 \u0005[נאמר\u0006 מתקבל הביטוי\u0005]\u0006 \u0003\"אל פתח אולם הבית\",\u0004 נמצא שפתח האולם קרוי אף הוא במקרא 'פתח', ומשיעורו אנו למדים.","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 אומרים: \u0003אי הוה כתב\u0004 \u0005[אילו היה נאמר]\u0006 \u0003\"אל פתח אולם\" —\u0004 היה זה \u0003כדקאמרת\u0004 \u0005[כמו שאמרת],\u0006 \u0003השתא דכתיב\u0004 \u0005[עכשיו שנאמר]\u0006 \u0003\"אל פתח אולם הבית\"\u0004 הרי אנו מבינים: פתחו של \u0003הבית הפתוח לאולם,\u0004 והוא ההיכל, ומשיעור פתחו נלמד.","ומקשים על תחילתה של הראייה: \u0003והא כי כתיב האי\u0004 \u0005[והרי כאשר נאמר\u0006 ביטוי \u0005זה\u0006 \"פתח אוהל מועד\"\u0005]\u0006 \u0003במשכן כתיב\u0004 \u0005[נאמר]!\u0006 וכיצד למדים אנו דברים האמורים במקדש מדברים האמורים במשכן?","ומשיבים: \u0003אשכחן\u0004 \u0005[מוצאים אנו]\u0006 \u0003משכן דאיקרי\u0004 \u0005[שנקרא]\u0006 \u0003מקדש, ומקדש דאיקרי\u0004 \u0005[שנקרא]\u0006 \u0003משכן,\u0004 והלכותיהם נלמדות זו מזו. \u0003דאי לא תימא הכי\u0004 \u0005[שאם לא תאמר כך]\u0006 שמשכן ומקדש אחד הם לענין הלכה, \u0003הא\u0004 [הלכה \u0005זו]\u0006 ש\u0003אמר רב יהודה אמר שמואל: שלמים ששחטן קודם פתיחת דלתות ההיכל\u0004 שבמקדש — \u0003פסולין, שנאמר \"ושחטו פתח אהל מועד\"\u0004 ונלמד: \u0003בזמן שפתוחין\u0004 פתחי אוהל מועד, \u0003ולא בזמן שהן נעולים\u0004, \u0003והא כי כתיב ההיא\u0004 \u0005[והרי כאשר נאמר אותו\u0006 פסוק\u0005]\u0006 \u0003במשכן כתיב\u0004 \u0005[נאמר]\u0006 \u0003אלא,\u0004 על כרחנו עלינו לקבל כי להלכה \u0003אשכחן\u0004 \u0005[מוצאים אנו]\u0006 \u0003מקדש דאיקרי\u0004 \u0005[שנקרא]\u0006 \u0003משכן ומשכן דאיקרי\u0004 \u0005[שנקרא]\u0006 \u0003מקדש.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003מקדש דאיקרי\u0004 \u0005[שנקרא]\u0006 \u0003משכן\u0004 יש מקרא המוכיח כן, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 — \u0003\"ונתתי משכני בתוככם\"\u0004 (ויקרא כו, יא), והמדובר במה שיהא כשיישבו ישראל בארצם. \u0003אלא משכן דאיקרי\u0004 \u0005[שנקרא]\u0006 \u0003מקדש מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003אילימא מדכתיב\u0004 \u0005[אם תאמר מ\u0006מה \u0005שנאמר]\u0006 \u0003\"ונסעו הקהתים נשאי המקדש והקימו את המשכן עד באם\"\u0004 (במדבר י, כא)"],["\u0003ההוא\u0004 \u0005[אותו]\u0006 פסוק \u0003בארון כתיב\u0004 \u0005[נאמר]\u0006. ומשמעות 'מקדש' בפסוק זה הריהי הדברים המקודשים שבמשכן, כגון ארון הברית, שהרי בני קהת נשאו רק את כלי הקודש ולא את גוף המשכן. \u0003אלא מהכא\u0004 \u0005[מכאן]\u0006 \u0003\"ועשו לי מקדש ושכנתי בתוכם\"\u0004 (שמות כה, ח).","מקשים: \u0003בין לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים]\u0006 \u0003ובין ל\u0004שיטת \u0003ר' יהודה לילפו\u0004 \u0005[שילמדו]\u0006 \u0003מפתח שער החצר\u0004 שבמשכן, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ארך החצר מאה באמה ורחב חמשים בחמשים וקמה חמש אמות\"\u0004 (שמות כז, יח), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"וחמש עשרה אמה קלעים לכתף\u0004 עמודיהם שלשה ואדניהם שלשה\" (שמות כז, יד), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \"\u0003ולכתף השנית מזה ומזה לשער החצר קלעים חמש עשרה אמה\u0004 עמודיהם שלושה ואדניהם שלשה\" (שמות לח, טו). שאם היו הקלעים שלשים מתוך רוחב כללי של חמשים אמה הרי ששער החצר היה עשרים אמה רוחב, וגובה חמש אמות. ונאמר: \u0003מה להלן,\u0004 במשכן — \u0003חמש ברוחב עשרים\u0004 קרוי פתח, \u0003אף כאן,\u0004 לדיני עירובין, \u0003חמש ברוחב עשרים,\u0004 יהא הגודל הראוי עבור פתח!","ודוחים: מכאן אין להוכיח, כי שער זה \"\u0003פתח שער החצר\" איקרי\u0004 \u0005[נקרא]\u0006 אבל \u0003פתח סתמא\u0004 \u0005[סתם] —\u0006 \u0003לא איקרי\u0004 \u0005[נקרא],\u0006 ואין ללמוד ממנו לשאר מקומות שנאמר בהם פתח סתם.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003כי כתיב\u0004 \u0005[כאשר נאמר]:\u0006 \u0003\"קלעים חמש עשרה אמה לכתף\" — בגובהה הוא דכתיב\u0004 \u0005[שנאמר],\u0006 והיה גובה הקלעים לא חמש אלא חמש עשרה אמה ואילו רוחב החצר לא נתפרש בכתוב כל עיקר.","ותוהים: \u0003גובהה?!\u0004 כיצד אפשר לפרש כן, \u0003והא כתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003במפורש \"וקמה חמש אמות\"!\u0004 ודוחים כי שם הכוונה ש\u0003ההוא משפת מזבח ולמעלה,\u0004 שהמזבח היה גבוה עשר אמות, וקלעי החצר היו מוגבהים מעליו עוד חמש אמות.","ושואלים: וכי \u0003ר' יהודה מפתחו של אולם גמר\u0004 \u0005[למד]?\u0006 \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנתנו\u0005]\u0006 שהפתח \u0003הרחב מעשר אמות ימעט ולא פליג\u0004 \u0005[חלק]\u0006 \u0003ר' יהודה!\u0004 והרי פתח האולם היה רחב מעשר אמות!","\u0003אמר אביי: פליג\u0004 \u0005[חלק]\u0006 ר' יהודה \u0003בברייתא, דתניא\u0004 [\u0005שכן שנינו]:\u0006 מבוי \u0003הרחב מעשר אמות ימעט, ר' יהודה אומר: אינו צריך למעט.\u0004","ועדיין שואלים: \u0003וליפלוג במתניתין\u0004 \u0005[ושיחלוק במשנתנו]!\u0006 ומדוע לא הובא בה הדבר? ומתרצים: \u0003פליג\u0004 \u0005[חלק]\u0006 \u0003בגובהה, והוא הדין לרחבה,\u0004 ומה שאמר 'אינו צריך' — מתייחס גם לגובה וגם לרוחב.","ושואלים: \u0003ואכתי\u0004 \u0005[ועדיין]\u0006 האם אפשר לומר כי \u0003ר' יהודה מפתחו של אולם גמר\u0004 \u0005[למד]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מבוי שהוא גבוה מעשרים אמה — ימעט, ור' יהודה מכשיר עד ארבעים וחמשים אמה. ותני\u0004 \u0005[ושנה\u0006 בברייתא אחרת\u0005]\u0006 \u0003בר קפרא\u0004 בדברי ר' יהודה: \u0003עד מאה\u0004 אמה.","\u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דברי \u0003בר קפרא\u0004 אפשר לומר 'עד מאה' איננו מדויק אלא \u0003גוזמא,\u0004 ורצה לומר שר' יהודה מכשיר בגבוה הרבה מעשרים. \u0003אלא ל\u0004שיטת \u0003רב יהודה\u0004 בשם רב \u0003מאי\u0004 \u0005[מה]\u0006 ה\u0003גוזמא\u0004 שבדבר? ודאי למספר מדויק נתכוון, אכן \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דברי \u0003ר' יהודה ארבעים\u0004 אמה — דבר זה \u0003גמר\u0004 \u0005[למד]\u0006 \u0003מפתחו של אולם, אלא חמשים מנא ליה\u0004 \u0005[מנין לו]?\u0006 אלא עלינו לזנוח את דרך ההסבר הזאת ולומר שלא למדו ר' יהודה מפתחו של אולם אלא טעם אחר היה לו.","\u0003אמר רב חסדא: הא מתניתא אטעיתיה לרב\u0004 \u0005[ברייתא זו\u0006 היא ש\u0005הטעתה את רב]\u0006 ובשל זה הסביר כך את השיטות, \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003מבוי שהוא גבוה מעשרים אמה, יותר מפתחו של היכל — ימעט\u0004. \u0003הוא\u0004 רב \u0003סבר: מדרבנן\u0004 \u0005[מ\u0006כיון \u0005שחכמים]\u0006 \u0003מפתחו של היכל גמרי\u0004 \u0005[למדו],\u0006 הרי ש\u0003ר' יהודה — מפתחו של אולם גמר\u0004 \u0005[למד].\u0006 \u0003ולא היא,\u0004 אלא \u0003ר' יהודה מפתחא דמלכין גמר\u0004 \u0005[מפתח של מלכים למד]\u0006 שנוהגים לעשות פתחיהם רחבים וגבוהים ביותר.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003מפתחו של היכל גמירי\u0004 \u0005[למדו] —\u0006 \u0003ליבעו\u0004 \u0005[שיצטרכו]\u0006 להכשרת המבוי \u0003דלתות\u0004 כשם שהיו ב\u0003היכל, אלמה תנן\u0004 \u0005[\u0006ו\u0005מדוע שנינו]\u0006 \u0003הכשר מבוי, בית שמאי אומרים: לחי וקורה, ובית הלל אומרים: לחי או קורה!\u0004 שאף בית שמאי אינם סבורים שיש צורך בדלתות!","ומשיבים: \u0003דלתות היכל לצניעות בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא דעבידן\u0004 \u0005[שנעשו],\u0006 אבל אין להן שימוש ממשי, ופתח ההיכל כשלעצמו אינו צריך לדלתות והריהו פתח גמור גם בלעדיהן.","ושוב מקשים: \u0003אלא מעתה,\u0004 שלמדו חכמים מפתח ההיכל, \u0003לא תיהני ליה\u0004 \u0005[לא תועיל לו]\u0006 למבוי \u0003צורת הפתח\u0004 אם הוא רחב מאוד, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003היכל צורת הפתח הויא ליה\u0004 \u0005[היתה לו],\u0006 \u0003אפילו הכי\u0004 \u0005[כך]\u0006 \u0003עשר אמות\u0004 בלבד \u0003הוא דרויח\u0004 \u0005[שרחב].\u0006 \u0003אלמה תנן\u0004 \u0005[מדוע שנינו]:\u0006 \u0003אם יש לו\u0004 למבוי \u0003צורת הפתח, אף על פי שרחב מעשר אמות — אינו צריך למעט!\u0004","ומשיבים: \u0003מידי הוא טעמא\u0004 \u0005[\u0006הרי \u0005דבר זה\u0006 אינו \u0005טעם]\u0006 \u0003אלא ל\u0004שיטתו של \u0003רב,\u0004 שלמדים מפתח ההיכל, ו\u0003הא מתני ליה\u0004 \u0005[והרי היה שונה לו]\u0006 \u0003רב יהודה לחייא בר רב קמיה\u0004 \u0005[לפני]\u0006 \u0003רב\u0004 במשנתנו זו, שאם היתה לו צורת הפתח \u0003אינו צריך למעט. ואמר ליה\u0004 \u0005[לו]\u0006 \u0003רב: אתנייה\u0004 \u0005[למד אותו]\u0006 בגרסה אחרת \u0003\"צריך למעט\"\u0004 הרי שלשיטת רב אף צורת הפתח אינה מועילה ברחב מכדי פתח ההיכל ואין להקשות כלל לפי שיטתו.","ומקשים עוד: \u0003אלא מעתה\u0004"],["\u0003לא תיהני ליה\u0004 \u0005[תועיל לו]\u0006 \u0003אמלתרא\u0004 (קורה מיוחדת) להכשירו אם היתה גבוהה מעשרים אמה, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003היכל אמלתרא הויא ליה\u0004 \u0005[היתה לו]\u0006 \u0003ואפילו הכי\u0004 \u0005[כך]\u0006 \u0003עשרים אמה הוא\u0004 שהיה \u0003גבוה\u0004 ולא יותר, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו]\u0006 במשנה: \u0003חמש אמלתראות של\u0004 עץ \u0003מילה היו על גביו\u0004 של האולם\u0003, זו למעלה מזו, וזו למעלה מזו.\u0004","ודוחים: \u0003והאי מאי תיובתא\u0004 \u0005[וזו מה קושיה\u0006 היא\u0005]?\u0006 \u0003דילמא כי תניא\u0004 \u0005[שמא כאשר נשנתה]\u0006 \u0003ההיא\u0004 \u0005[אותה]\u0006 ברייתא \u0005של\u0006 \u0003אמלתראות, באולם תניא\u0004 \u0005[נשנתה],\u0006 וגובהו היה ארבעים אמה?","על כך משיבים: \u0003והאי מאי קושיא\u0004 \u0005[וזו מה קושיה\u0006 היא\u0005]?\u0006 \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003תבנית היכל כתבנית אולם?\u0004","ומה שהיה בפתחו של זה היה בפתחו של זה, \u0003אלמה\u0004 \u0005[\u0006ו\u0005מדוע]\u0006 \u0003אמר ר' אילעא אמר רב\u0004 עצמו: קורה ש\u0003רחבה ארבעה\u0004 טפחים, \u0003אף על פי שאינה בריאה\u0004 (חזקה), הרי זו מכשירה את המבוי. \u0003ואם יש לה אמלתרא — אפילו גבוהה יותר מעשרים אמה אינו צריך למעט.\u0004","\u0003אמר רב יוסף:\u0004 הלכה זו ב\u0003אמלתרא\u0004 לא מדברי רב היא אלא \u0003מתניתא\u0004 \u0005[ברייתא]\u0006 \u0003היא,\u0004 ובעצם \u0003מאן קתני לה?\u0004 \u0005[מי שנה אותה]\u0006 ואולי אין זו ברייתא מוסמכת, ואין רב צריך לקבל דברים האמורים בברייתא זו.","\u0003אמר אביי: והא\u0004 \u0005[והרי]\u0006 \u0003חמא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבה בר אבוה קתני לה\u0004 \u0005[שנה אותה]\u0006 \u0003ו\u0004אף אם \u0003תיהוי\u0004 \u0005[תהיה]\u0006 הלכה זו של \u0003אמלתרא מתניתא\u0004 \u0005[ברייתא]\u0006 \u0003ותיקשי\u0004 \u0005[ותיקשה]\u0006 \u0003לרב\u0004!","— \u0003אמר\u0004 \u0005[\u0006יכול \u0005לומר]\u0006 \u0003לך רב: דל אנא מהכא, מתנייתא מי לא קשיין אהדדי\u0004 \u0005[הוצא אותי\u0006 ואת שיטתי \u0005מכאן,\u0006 ואולם \u0005האם הברייתות\u0006 עצמן \u0005אינן קשות זו על זו]?\u0006 \u0003אלא מאי אית לך למימר\u0004 \u0005[מה יש לך לומר]\u0006 כתירוץ — שמחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 \u0003היא, לדידי נמי\u0004 \u0005[לי\u0006 לשיטתי \u0005גם כן]\u0006 מחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 \u0003היא.\u0004","ואילו \u0003רב נחמן בר יצחק אמר: בלא רב מתנייתא אהדדי לא קשיין\u0004 \u0005[הברייתות אינן קשות זו לזו],\u0006 כי \u0003לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים]\u0006 \u0003קורה טעמא מאי\u0004 \u0005[מה טעמה] —\u0006 \u0003משום היכרא\u0004 \u0005[היכר],\u0006 והאמלתרא אף היא מושכת תשומת לב, \u0003והאי דקתני\u0004 \u0005[וזו ששנינו]\u0006 לגבי גובה המבוי: \u0003\"יתר מפתחו של היכל\" — סימנא בעלמא\u0004 \u0005[סימן סתם]\u0006 הוא ואין למדים הלכה מצורת פתח ההיכל.","\u0003ורב נחמן בר יצחק, הניחא אי לא סבירא ליה הא דרבה, אלא אי סבירא ליה הא דרבה\u0004 \u0005[זה נוח אם אינו סבור,\u0006 שאין נראית לו שיטתו \u0005זו של רבה, אבל אם סבור הוא\u0006 כשיטתו \u0005זו של רבה]\u0006 ש\u0003אמר רבה: כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"למען ידעו דרתיכם כי בסכות הושבתי\u0004 את בני ישראל בהוציאי אותם מארץ מצרים אני ה' אלהיכם\" (ויקרא כג, מג) ומכאן למד רבה כי \u0003עד עשרים אמה אדם יודע ש\u0004הוא \u0003דר בסכה,\u0004 ואם הסוכה גבוהה \u0003למעלה מעשרים אמה — אין אדם יודע, משום דלא שלטא ביה עינא\u0004 \u0005[שאין העין שולטת בו],\u0006 שכן אין אדם נוהג להגביה ראשו להסתכל בגובה כזה, ונמצא שהוא רואה רק את הדפנות, אבל אינו שם לב לעיקרה של הסוכה — לסכך.","\u0003אלמא גבי\u0004 \u0005[מכאן\u0006 ש\u0005אצל]\u0006 \u0003סוכה נמי בהיכרא פליגי, איפלוגי בתרתי\u0004 \u0005[ב\u0006ענין \u0005היכר הם גם כן חולקים, ולחלוק בשתים]\u0006 \u0003למה לי?\u0004 שגם ר' יהודה, המתיר למעלה מעשרים אמה, סבור כי העין שולטת אף בגובה רב, ואין צורך בשתי מחלוקות גם בסוכה וגם במבוי, שהרי אותו טעם בשתיהן, ולכאורה אפשר לפסוק שטעם מבוי שונה הוא, ועיקרו כדברי רב.","ומשיבים: \u0003צריכא\u0004 \u0005[צריך]\u0006 להשמיענו את שתי המחלוקות, \u0003דאי אשמעינן\u0004 \u0005[שאילו היה משמיענו]\u0006 רק \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003סוכה —\u0004 הייתי אומר \u0003בהא קאמר\u0004 \u0005[בזו אמר]\u0006 \u0003ר' יהודה\u0004 שסוכה גבוהה כשרה\u0005,\u0006 \u0003כיון\u0004 ש\u0003לישיבה עבידא\u0004 \u0005[\u0006היא \u0005עשויה] —\u0006 \u0003שלטא ביה עינא\u0004 \u0005[שולטת בה העין],\u0006 שתוך ישיבה ממושכת בסוכה ודאי יבחין גם בסכך הסוכה. \u0003אבל מבוי,\u0004 ש\u0003להילוך עביד\u0004 \u0005[נעשה] —\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003מודה להו לרבנן\u0004 \u0005[להם לחכמים]\u0006 שאין עינו של המהלך מבחינה בדברים גבוהים כל כך. \u0003ואי אשמעינן בהא — בהא קאמרי רבנן, אבל בהך — אימא מודו ליה לר' יהודה, צריכא\u0004 \u0005[ואם היה משמיענו\u0006 רק \u0005בזה\u0006 במבוי, הייתי אומר: \u0005בזה\u0006 בלבד \u0005אמרו חכמים, אבל בזו\u0006 בסוכה, \u0005אמור\u0006 ש\u0005מודים לו לר' יהודה\u0006 מהטעם שהסברנו, על כן \u0005צריך]\u0006 להשמיענו את שתי המחלוקות.","ושואלים לעיקרו של דבר: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003אמלתרא? רב חמא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבה בר אבוה אמר: קיני\u0004 (עיטורים וקישוטים החקוקים בעץ ועשויים כקיני עופות). \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל \u0003אמר, אמרי במערבא: פסקי דארזא\u0004 \u0005[אומרים בארץ ישראל\u0006 שאלה הם \u0005כלונסאות של ארז].\u0006","ומבררים: \u0003מאן דאמר פסקי דארזא\u0004 \u0005[מי שאומר\u0006 שאמלתראות הן \u0005כלונסאות של ארז],\u0006 \u0003כל שכן\u0004 שמתיר \u0003קיני\u0004 \u0005[חקיקה],\u0006 שכן קורה המגולפת בתבניות מעוררת שימת לב, ויש בה היכר אפילו בגובה רב. אולם, \u0003מאן דאמר קיני, אבל פסקי דארזא — לא\u0004 \u0005[מי שאומר\u0006 שאמלתרא היא \u0005חקיקה, אבל כלונסאות של ארז\u0006 — \u0005לא].\u0006","ולגופה של שיטה זו מבררים: \u0003ומאן דאמר פסקי דארזא\u0004 \u0005[ומי שאומר כלונסאות של ארז]\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעמו]\u0006 — \u0003משום דנפיש משכיה,\u0004 \u0005[שמרובה אורכה],\u0006 ולכן שמים לב אליהם. אולם, \u0003והא\u0004 \u0005והרי\u0006 \u0003סוכה דנפיש משכיה, וקאמרי רבנן\u0004 \u0005[שמרובה אורכה, ואמרו חכמים]\u0006 ש\u0003לא\u0004 יגביה למעלה מעשרים אמה!","\u0003אלא\u0004 טעם הדבר הוא: \u0003כיון\u0004 שהארז \u0003דקא חשיב — אית ליה קלא\u0004 \u0005[שחשוב —\u0006 \u0005יש לו קול\u0006 ופרסום\u0005],\u0006 ואנשים העוברים במבוי מתבוננים בקורה חשובה כגון זו, אף כשהיא גבוהה.","נתעוררה שאלה: אם היתה \u0003מקצת קורה\u0004 של מבוי \u0003בתוך עשרים\u0004 אמה לקרקע, \u0003ומקצת קורה למעלה מעשרים,\u0004 וכן \u0003מקצת סכך\u0004 של סוכה \u0003בתוך עשרים\u0004 אמה\u0003, ומקצת סכך למעלה מעשרים\u0004 האם כשר או פסול? \u0003אמר רבה: במבוי — כשר, בסוכה — פסול.\u0004","ושואלים: \u0003מאי שנא\u0004 \u0005[מה שונה]\u0006 ש\u0003במבוי כשר —\u0004 משום \u0003דאמרינן קלוש\u0004 \u0005[שאומרים אנו: חתוך]\u0006 את עובי הקורה שלמעלה מעשרים. כלומר, נחשוב להלכה כאילו לא היה קיים חלק זה, אולם אם כן הרי \u0003סוכה נמי לימא קלוש\u0004 \u0005[גם כן אמור: חתוך]\u0006 את הסכך שמעל לעשרים.","ומשיבים: \u0003אי קלשת הויא לה\u0004 \u0005[אם תחתוך תהיה זו]\u0006 \u0003חמתה מרובה מצילתה\u0004 של סוכה. שהרי אם תסיר את חלק הסכך שמעל לעשרים, ישאר בה רק מעט סכך, ותיפסל הסוכה מן הטעם שאין סככה מספיק כדי להצל.","ודוחים: \u0003הכא נמי, אי קלשת — הויא לה\u0004 \u0005[כאן גם כן\u0006 בקורה, \u0005אם תחתוך —\u0006 \u0005תהיה זו]\u0006 \u0003קורה\u0004 רופפת וחלשה \u0003הניטלת\u0004 (נופלת) \u0003ברוח\u0004 הנושבת. וקורה כעין זו אינה מתירה. \u0003אלא על כרחך,\u0004 שאנו מחשיבים את החלק הנותר כאילו היה חזק, ו\u0003נעשו כשפודין של מתכת,\u0004 שאינם ניטלים ברוח אפילו הם דקים. ואם עלינו לקבל הנחות מעין אלו, \u0003הכא נמי\u0004 \u0005[כאן גם כן] —\u0006 בסוכה, \u0003על כרחך נעשית\u0004 כאילו \u0003צילתה מרובה מחמתה!\u0004","על כן מסבירים את שיטת רבה באופן אחר. \u0003אמר רבא מפרזקיא: סוכה\u0004 ש\u0003ליחיד היא,\u0004 ושמא יינטל לגמרי מקצת הסכך שלמטה מעשרים ויישאר רק זה שלמעלה מעשרים, שאינו מכשיר את הסוכה — \u0003לא מדכר\u0004 \u0005[אינו נזכר],\u0006 \u0003מבוי\u0004 שהוא של \u0003רבים — מדכרי אהדדי\u0004 \u0005[מזכירים הם זה לזה].\u0006","\u0003רבינא אמר\u0004 טעם אחר: \u0003סוכה\u0004 כיון שמצוותה \u0003דאורייתא\u0004 \u0005[מן התורה] —\u0006 \u0003אחמירו\u0004 \u0005[החמירו]\u0006 \u0003בה רבנן\u0004 \u0005[חכמים],\u0006 \u0003מבוי\u0004 כיון שעיקרו \u0003דרבנן\u0004 \u0005[מדברי חכמים] —\u0006 \u0003לא אחמירו ביה רבנן\u0004 \u0005[החמירו בו חכמים].\u0006","\u0003רב אדא בר מתנה מתני להא שמעתא דרבה איפכא\u0004 \u0005[היה שונה את ההלכה הזו של רבה להיפך],\u0006 ש\u0003אמר רבה: במבוי — פסול, בסוכה — כשירה!\u0004 וכל הנימוקים שנאמרו בענין זה יש איפוא להופכם.","ששואלים: \u0003מאי שנא\u0004 \u0005[מה שונה]\u0006 \u0003סוכה\u0004 שהיא \u0003כשירה — דאמרינן קלוש\u0004 \u0005[שאנו אומרים: חתוך],\u0006 \u0003במבוי נמי\u0004 \u0005[גם כן] —\u0006 \u0003לימא קלוש\u0004 \u0005[נאמר חתוך]!\u0006","ומשיבים: \u0003אי קלשת, הוי לה\u0004 \u0005[אם אתה חותך, הרי זו]\u0006 נעשית \u0003קורה הניטלת ברוח.\u0004 ודוחים: \u0003הכא נמי — אי קלשת הויא לה\u0004 \u0005[כאן\u0006 בסוכה \u0005גם כן אם אתה חותך הרי היא\u0006 נעשית\u0005] —\u0006 \u0003חמתה מרובה מצילתה! אלא על כרחך,\u0004 בסוכה, \u0003נעשית\u0004 כאילו \u0003צילתה מרובה מחמתה, הכא נמי\u0004 \u0005[כאן\u0006 במבוי \u0005גם כן]\u0006 \u0003על כרחך נעשו\u0004 שיירי הקורה \u0003כשפודין של מתכת!\u0004","\u0003אמר רבא מפרזקיא: סוכה\u0004 ש\u0003ליחיד היא — רמי אנפשיה ומדכר\u0004 \u0005מטיל\u0006 את החובה \u0005על עצמו ונזכר\u0006 לבדוק\u0005]\u0006, \u0003מבוי\u0004 ש\u0003לרבים היא — סמכי אהדדי, ולא מדכרי\u0004 \u0005[סומכים זה על זה, ואינם מזכירים],\u0006 \u0003דאמרי אינשי — קדרא דבי שותפי, לא חמימא ולא קרירא\u0004 \u0005[ש\u0006כן \u0005אומרים אנשים\u0006 פתגם זה: \u0005קדירה של שותפים, אינה חמה ואינה צוננת],\u0006 שבכל דבר השייך לשניים, סומך אדם על חבירו, שהוא יעשה, ולכן אף אחד אינו עושה.","\u0003רבינא אמר: סוכה\u0004 שעיקרה \u0003דאורייתא\u0004 \u0005[מן התורה] —\u0006 \u0003לא בעי\u0004 \u0005[אינה צריכה]\u0006 \u0003חיזוק\u0004 מדברי חכמים, והקלו בה. \u0003מבוי\u0004 שהוא \u0003דרבנן\u0004 \u0005[מדברי חכמים] —\u0006 \u0003בעי\u0004 \u0005[צריך]\u0006 \u0003חיזוק.\u0004","מכיון שנאמרו בדבר שתי נוסחאות סותרות, שואלים: \u0003מאי הוי עלה?\u0004 \u0005[מה היה עליה]\u0006 על בעיה זו, אם מקצת הסכך והקורה עולים על שיעור הגובה, הלכה למעשה? \u0003רבה בר רב עולא אמר: זה וזה\u0004 במבוי ובסוכה — \u0003פסול. רבא אמר: זה וזה כשר.\u0004"],["\u0003חלל סוכה תנן\u0004 \u0005[שנינו]\u0006 \u0003חלל מבוי תנן\u0004 \u0005[שנינו]\u0006 שעשרים אמות שדובר בכך הרי הן שיעור הגובה של החלל מתחת לסכך או לקורה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרבא, תניא דמסייע\u0004 \u0005[שנויה\u0006 ברייתא \u0005המסייעת]\u0006 \u0003לך: מבוי שהוא גבוה מעשרים אמה יותר מפתחו של היכל — ימעט. ו\u0004הרי \u0003היכל גופו חללו עשרים,\u0004 וקורת הגג שלו למעלה מעשרים, ומכאן ראיה לכך שעשרים אמה שאמרו בסוכה ובמבוי הכוונה לחלל.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב שימי בר רב אשי לרב פפא\u0004 מן התוספתא: \u0003כיצד היה עושה — מניח קורה משפת עשרים ולמטה,\u0004 משמע שקורה למעלה מעשרים פסולה!","ענה לו: \u0003אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]:\u0006 משפת עשרים \u0003\"ולמעלה\".\u0004 ותמה רב שימי: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"למטה\u0004 מעשרים\" \u0003קתני!\u0004 \u0005[שנינו]\u0006 וכיצד יכול אתה להפוך גירסה זו?","והסביר לו שאין משנים ממש את נוסח הברייתא אלא מפרשים אותה, \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה משמיע לנו]:\u0006 ש\u0003למטה כלמעלה,\u0004 ודומים שני הדינים זה לזה. והכוונה: \u0003מה למעלה\u0004 בגובה מקסימלי של הקורה \u0003חללה עשרים\u0004 אמה, \u0003אף למטה\u0004 הגובה המינימלי של הקורה צריך שיהא \u0003חללה עשרה\u0004 טפחים. ואם הניח את הקורה בתוך עשרה טפחים, אינה מכשירה את המבוי.","\u0003אמר אביי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב נחמן: אמת סוכה ואמת מבוי,\u0004 כלומר: האמות שהוזכרו בדיני סוכה ובדיני מבוי, הרי הן נמדדות \u0003באמה\u0004 קטנה \u0003בת חמשה\u0004 טפחים. ו\u0003אמת כלאים — באמה\u0004 גדולה \u0003בת ששה\u0004 טפחים. ויש להבין כי לכאורה הכוונה היתה להחמיר בשני המקרים.","ומפרטים: \u0003אמת מבוי — באמה בת חמשה, למאי הילכתא\u0004 \u0005[לאיזו הלכה]\u0006 מתייחס הדבר? \u0003ל\u0004ענין \u0003גובהו\u0004 של מבוי \u0003ולפירצת מבוי\u0004 שפוסלת את המבוי, אם היתה ברוחב של יותר מעשר אמות.","וששאלתם: \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 גם ענין של \u0003משך מבוי\u0004 (אורכו המינימלי של מבוי) שמותר להכשירו על ידי לחי וקורה\u0003,\u0004 שהוא \u0003בארבע אמות.\u0004 ואם אנו מודדים מבוי באמות קטנות, הרי נגיע על ידי כך \u0003לקולא!\u0004","ודוחים: לענין זה סבורים אנו \u0003כמאן\u0004 \u0005[כמי]\u0006 ש\u0003אמר\u0004 שמשך מבוי \u0003בארבעה טפחים\u0004 בלבד, ואמות שהוזכרו במבוי רק לענין גובהו ורוחב פירצה שבו הוזכרו, והריהן רק להחמיר.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר, כי משך מבוי אמנם \u0003בארבע אמות,\u0004 ואנו משערים אותו לחומרה באמות גדולות בנות ששה טפחים, ומה שאמר שאמת מבוי היא אמה בת חמשה — \u0003רוב אמות קאמר,\u0004 ולא כולן.","ועוד דנים בדבר, רב נחמן אמר ש\u0003אמת סוכה\u0004 מחמירים בה ומודדים \u0003באמה\u0004 קטנה \u0003בת חמשה,\u0004 ושואלים: \u0003למאי הילכתא\u0004 \u0005[לאיזו הלכה]\u0006 מתייחס הדבר? \u0003לגובהה ולדופן עקומה,\u0004 שאם היה גג קבוע מבדיל בין הסכך ודופן הסוכה, אם לא היה רוחבו של גג זה רב מארבע אמות אומרים אנו \"דופן עקומה\" — כאילו התקפלה דופן הסוכה ומגיעה עד קצה הסכך, וכשרה.","\u0003ו\u0004אולם \u0003הא איכא\u0004 \u0005[והרי יש]\u0006 דין של \u0003משך סוכה בארבע אמות,\u0004 ואם נמדוד באמות הקטנות הרי זה \u0003לקולא!\u0004 ד\u0003תניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003רבי אומר: אומר אני, כל סוכה שאין בה ארבע אמות על ארבע אמות — פסולה,\u0004 ואם נמדוד באמות קטנות הרי זה להקל!","ומתרצים שיש להבין כי רב נחמן סבור \u0003כרבנן דאמרי\u0004 \u0005[כחכמים האומרים]:\u0006 סוכה \u0003אפילו אינה מחזקת אלא ראשו ורובו ושולחנו\u0004 של הדר בה — כשרה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לעולם\u0004 אף לשיטת \u0003רבי היא, ו\u0004רב נחמן \u0003רוב אמות קאמר\u0004 \u0005[אמר],\u0006 אף על פי שיש מקצת אמות בסוכה שאנו מחשבים באמה בת ששה ולהחמיר.","אמרנו כי \u0003\"אמת כלאים באמה בת ששה\", למאי הילכתא\u0004 \u0005[לאיזו הלכה]\u0006 מתייחס הדבר? — \u0003ל\u0004ענין \u0003קרחת הכרם ולמחול הכרם.\u0004","שכן שנינו במסכת כלאים: \u0003קרחת הכרם, בית שמאי אומרים\u0004 ששיעורה \u0003עשרים וארבע אמות. ובית הלל אומרים: שש עשרה אמות. ומחול הכרם, בית שמאי אומרים: שש עשרה אמות, ובית הלל אומרים: שתים עשרה.\u0004","ומבואר במשנה: \u0003איזו היא קרחת הכרם — כרם שחרב אמצעיתו\u0004 מגפנים, אם \u0003אין שם\u0004 בחלל הפנוי \u0003שש עשרה אמות — לא יביא זרע לשם\u0004 משום האיסור האמור בתורה לזרוע זרעים בכרם (דברים כב, ט). \u0003היו שם שש עשרה אמה — נותן לו\u0004 לכרם \u0003כדי עבודתו,\u0004 כלומר: ארבע אמות בצידן של הגפנים הנחוצות לשם עיבודן, \u0003וזורע את המותר.\u0004","\u0003ואיזהו מחול הכרם\u0004 — השטח הפנוי ש\u0003בין כרם לגדר. אין שם שתים עשרה אמה — לא יביא זרע לשם. היו שם שתים עשרה אמה — נותן לו לכרם כדי עבודתו, וזורע את השאר\u0004.","ומקשים: \u0003והא איכא\u0004 \u0005[והרי יש\u0006 דין\u0005]\u0006 גפנים ה\u0003רצופים בארבע אמות דלקולא\u0004 \u0005[שלהקל]\u0006 אם יחשבו את השיעור באמות גדולות. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כרם הנטוע\u0004 בשורות צפופות \u0003על פחות מארבע אמות, ר' שמעון אומר:\u0004 כיון שהוא צפוף כל כך — \u0003אינו כרם,\u0004 ואם זרע שם זרעים אינו חייב. \u0003וחכמים אומרים: כרם\u0004 הוא, \u0003ורואין את\u0004 הגפנים \u0003האמצעיים כאילו אינם\u0004 והזורע מתחייב. ולשיטת ר' שמעון אם ישערו בארבע אמות גדולות הרי זה להקל.","ומתרצים: רב נחמן שאמר דבר זה נוקט \u0003כרבנן דאמרי\u0004 \u0005[כ\u0006שיטת \u0005חכמים האומרים]\u0006 שכרם רצוף \u0003הוי\u0004 \u0005[הרי הוא]\u0006 \u0003כרם. ואיבעית אימא\u0004 \u0005[ואם תרצה\u0006 לפרש באופן אחר \u0005אמור\u0006 כך\u0005]:\u0006 \u0003לעולם\u0004 אמר אף כ\u0003ר' שמעון, ו\u0004על \u0003רוב אמות\u0004 שבדיני כלאים \u0003אמר,\u0004 ולא על כולן. עד כאן שיטת אביי בשם רב נחמן.","\u0003ו\u0004אילו \u0003רבא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב נחמן אמר: כל אמות\u0004 ששיערו בהם חכמים תמיד \u0003באמה בת ששה\u0004 טפחים, \u0003אלא הללו שוחקות,\u0004 כלומר מרווחות וארוכות מעט יותר. \u0003והללו\u0004 שאמרו להחמיר \u0003עצבות\u0004 כלומר מצומצמות, מדוייקות לשיעור ששה טפחים בדיוק.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 מברייתא\u0005]:\u0006 \u0003כל אמות שאמרו חכמים באמה בת ששה\u0004 טפחים, \u0003ובלבד\u0004"],["\u0003שלא יהו מכוונות\u0004 (שוות בדיוק). \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רבא\u0004 כוונת הברייתא \u0003כי היכי דליהויין\u0004 \u0005[כדי שיהיו]\u0006 \u0003הללו\u0004 אמות כלאים \u0003שוחקות\u0004 ו\u0003הללו\u0004 אמות סוכה \u0003עצבות. אלא לאביי קשיא\u0004 \u0005[קשה]!\u0006","ומשיבים: \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך אביי, אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]\u0006 כך בנוסח הברייתא: \u0003אמת כלאים באמה בת ששה,\u0004 ולא שאר האמות.","ומקשים: \u0003והא מדקתני סיפא\u0004 \u0005[והרי מ\u0006מה \u0005ששנינו\u0006 ב\u0005סוף]\u0006 ברייתא זו: \u0003רבן שמעון בן גמליאל אומר: כל אמות שאמרו חכמים בכלאים באמה בת ששה, ובלבד שלא יהו מצומצמות,\u0004 הרי \u0003מכלל\u0004 הדברים נלמד ש\u0003תנא קמא כל אמות קאמר\u0004 \u0005[אמר],\u0006 ולא בכלאים בלבד!","ומשיבים: \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך אביי: ולאו מי איכא\u0004 \u0005[והאם אין]\u0006 \u0003רבן שמעון בן גמליאל דקאי כוותי\u0004 \u0005[שעומד כשיטתי],\u0006 \u0003אנא דאמרי\u0004 \u0005[אני שאני אומר]\u0006 דברי הרי הם \u0003כ\u0004שיטת \u0003רבן שמעון בן גמליאל.\u0004","ומעירים: \u0003ל\u0004שיטת \u0003אביי ודאי\u0004 מחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 \u0003היא\u0004 בדבר אמות גדולות וקטנות. אולם \u0003ל\u0004שיטת \u0003רבא מי לימא\u0004 \u0005[האם יש לומר]\u0006 שמחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 \u0003היא?\u0004","ומשיבים: שאין הדבר הכרחי לשיטה זו, \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך רבא: רבן שמעון בן גמליאל\u0004 לא בא לחלוק על עיקרי דברי התנא הראשון אלא \u0003הא אתא לאשמועינן:\u0004 \u0005[\u0006דבר \u0005זה בא להשמיענו]:\u0006 \u0003אמת כלאים לא יצמצם,\u0004 שאמה זו יש להקפיד בה שתהא שוחקת.","ומקשים: אם רק זאת בלבד רצה לומר, \u0003ולימא\u0004 \u0005[ושיאמר]:\u0006 \u0003\"אמת כלאים לא יצמצם\",\u0004 ודבריו \u0003באמה בת ששה למעוטי מאי?\u0004 \u0005[למעט את מה\u0006 בא\u0005],\u0006 \u0003לאו למעוטיה\u0004 \u0005[האם לא למעט]\u0006 \u0003אמת סוכה ואמת מבוי\u0004 ששיעורן בחמשת טפחים בלבד?","ודוחים: \u0003לא,\u0004 בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003אמה יסוד\u0004 של המזבח \u0003ואמה סובב\u0004 של המזבח, שהכל מסכימים שהן נמדדות באמות קטנות בנות חמשה טפחים,","\u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואלה מדות המזבח באמות אמה אמה וטפח וחיק האמה ואמה רחב וגבולה אל שפתה סביב זרת האחד וזה גב המזבח\"\u0004 (יחזקאל מג, יג) ופירשו חכמים: \u0003\"חיק האמה\" — זה יסוד\u0004 המזבח, \u0003\"ואמה רחב\" — זה סובב\u0004 שבמזבח, \u0003\"וגבולה אל שפתה סביב\" — אלו הקרנות, \"וזה גב המזבח\"\u0004 — מדבר ב\u0003מזבח הזהב\u0004 שאף הוא נמדד באמות קטנות.","כיון שדובר בשיעורין שונים מביאים מה ש\u0003אמר ר' חייא בר אשי אמר רב: שיעורין\u0004 של מצוות התורה, ודיני \u0003חציצין\u0004 \u0005[חציצות]\u0006 הפוסלים בטבילה ודיני \u0003מחיצין\u0004 \u0005[מחיצות]\u0006 והלכותיהן, כולם \u0003הלכה למשה מסיני.\u0004","ושואלים: וכי \u0003שיעורין\u0004 הלכה למשה מסיני בלבד הם?! הלא \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003הוא! דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ארץ חטה ושערה\u0004 וגפן ותאנה ורמון ארץ זית שמן ודבש\" (דברים ח, ח), \u0003ואמר רב חנן: כל הפסוק הזה לשיעורין נאמר:\u0004","\u0003חטה\u0004 — ללמדנו שיעור \u0003לכדתנן\u0004 \u0005[לכמו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003הנכנס לבית המנוגע\u0004 בצרעת (עיין ויקרא פרק יד) \u0003וכליו\u0004 (בגדיו) מונחים \u0003על כתפיו, וסנדליו וטבעותיו בידיו\u0004 — \u0003הוא והם\u0004 (הבגדים) \u0003טמאין מיד.\u0004 אולם אם \u0003היה לבוש כליו, וסנדליו ברגליו, וטבעותיו באצבעותיו — הוא טמא מיד, והן\u0004 הבגדים, הסנדלים והטבעות \u0003טהורין עד שישהה\u0004 בבית \u0003בכדי\u0004 זמן \u0003אכילת פרס\u0004 (חצי ככר). ופרס זה שיערו ב\u0003פת חטין\u0004 שזמן אכילתה קצר \u0003ולא פת שעורין.\u0004 ומחשבים את זמן האכילה כשהאוכל \u0003מיסב ואוכל בליפתן\u0004. נמצא שיש שיעור בתורה הקשור בחטה דוקא.","\u0003שעורה\u0004 — אף היא בסיס לשיעורים, \u0003דתנן\u0004 \u0005[שכן שנינו]:\u0006 \u0003עצם\u0004 מן המת שגודלה \u0003כשעורה - מטמא במגע ובמשא,\u0004 אבל \u0003אינו מטמא באהל,\u0004 שאם היתה העצם בתוך בית, אין כל חלל הבית נטמא.","\u0003גפן —\u0004 הוא השיעור \u0003כדי רביעית יין לנזיר,\u0004 שהנזיר האסור בשתיית יין, לוקה אם שותה אותו."],["\u0003תאנה —\u0004 לענין שיעור \u0003כגרוגרת\u0004 (תאנה יבשה) \u0003להוצאת שבת,\u0004 שכל מאכלי אדם, חייבים על הוצאתם בשבת אם היה גודלם כגרוגרת.","\u0003רמון —\u0004 אף הוא ללמדנו שיעור, \u0003כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]:\u0006 \u0003כל כלי בעלי בתים\u0004 העשויים עץ, \u0003שיעורן\u0004 להיטהר מטומאתם על ידי שבירה (שכן, כלי טמא נטהר מטומאתו בשבירה) אם יש בהם נקב \u0003כרימונים\u0004.","ומה שנאמר \"\u0003ארץ זית שמן ודבש\"\u0004 דורשים: \u0003ארץ שכל שיעוריה כזיתים.\u0004 ותוהים: \u0003כל שיעוריה סלקא דעתך\u0004 \u0005[עולה על דעתך]?!\u0006 \u0003והאיכא הני דאמרן\u0004 \u0005[והרי יש אלו שאמרנו]\u0006 שאין שיעורם כזית! \u0003אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003ארץ שרוב שיעוריה כזיתים,\u0004 שרוב השיעורים שנאמרו, כגון במאכלות אסורים וטומאת אהל המת ומגע נבילה, הם בכזית.","\u0003דבש,\u0004 כלומר, תמר שממנו מוציאים דבש תמרים \u0003—\u0004 אף הוא שיעור. שבאכילה ביום הכיפורים אין מתחייבים אלא בשיעור \u0003ככותבת\u0004 (תמרה) \u0003הגסה\u0004 (הגדולה). ואם כן, מכל האמור כאן אפשר להסיק, ששיעורי תורה אינם רק הלכה למשה מסיני אלא כתובים בתורה במפורש.","ודוחים: \u0003ותסברא\u0004 \u0005[וכי סבור אתה]\u0006 כך, וכי \u0003שיעורין מיכתב כתיבי\u0004 \u0005[כתובים\u0006 במפורש בתורה\u0005]\u0006 לענין מה מתייחס כל אחד מן השיעורים? \u0003אלא הלכתא נינהו, ואסמכינהו רבנן אקראי\u0004 \u0005[הלכות הן\u0006 למשה מסיני, \u0005והסמיכון חכמים על המקראות].\u0006","אף לגבי \u0003חציצין,\u0004 כלומר חציצות בטבילה, שואלים: הרי אף אלה \u0003דאורייתא נינהו\u0004 \u0005[מן התורה הן]\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ורחץ במים את כל בשרו\"\u0004 (ויקרא טו, טז) ולמדו חכמים מכאן \u0003שלא יהא דבר חוצץ בין בשרו למים, 'במים'\u0004 הידועים הכוונה דווקא \u0003במי מקוה,\u0004 ולא בכל מים. ומן הכתוב \u0003\"כל בשרו\" למדים\u0004 שיהיו אלה \u0003מים שכל גופו עולה בהן,\u0004 כלומר שיכול לטבול בהן כולו בבת אחת \u0003וכמה הן,\u0004 ומה שיעורם של מים אלה — \u0003אמה על אמה ברום שלש אמות. ושיערו חכמים\u0004 את נפחו של מקוה בגודל זה וקבעו \u0003מי מקוה\u0004 שיעורם \u0003ארבעים סאה.\u0004 וכיון שנדרש הדבר מן הכתוב מה צורך להלכה למשה מסיני?","ומשיבים: \u0003כי איצטריך הילכתא\u0004 \u0005[כאשר הוצרכה הלכה]\u0006 זו, הרי היא \u0003ל\u0004ענין \u0003שערו,\u0004 שאף הוא צריך להיות ראוי שיחדרו בו המים ללא חציצה. \u0003וכ\u0004דברי \u0003רבה בר רב הונא\u0004 ש\u0003אמר רבה בר רב הונא: נימא\u0004 (שערה) \u0003אחת קשורה — חוצצת\u0004 בפני המים והטובל כך לא עלתה לו הטבילה. \u0003שלש — אינן חוצצות,\u0004 ששלש שערות יחד אינן נקשרות במהודק עד כדי שלא יכנסו המים ביניהן. \u0003שתים — איני יודע,\u0004 ודבר זה הוא שנלמד מן ההלכה.","ומקשים: \u0003שערו נמי דאורייתא\u0004 \u0005[גם כן מן התורה]\u0006 \u0003הוא, דתניא\u0004 \u0005[שכן שנינו\u0006 בברייתא\u0005]\u0006 על הכתוב \u0003\"ורחץ את כל בשרו\",\u0004 'את' משמעו לרבות ולהוסיף \u0003את הטפל לבשרו — וזהו שער!\u0004","ומשיבים: \u0003כי אתאי הילכתא\u0004 \u0005[כאשר באה ההלכה]\u0006 הרי זה ללמדנו \u0003ל\u0004ענין \u0003רובו ולמיעוטו ולמקפיד ולשאין מקפיד וכ\u0004דברי \u0003ר' יצחק.\u0004","ש\u0003אמר ר' יצחק:\u0004 על פי \u0003דבר תורה\u0004 רק אם \u0003רובו\u0004 של הגוף מכוסה בדבר החוצץ בפני המים \u0003ומקפיד עליו\u0004 ומעונין להסיר אותה חציצה \u0003חוצץ\u0004 — הריהו נחשב כחציצה לטבילה במקוה, \u0003ושאינו מקפיד עליו — אינו חוצץ, וגזרו על רובו\u0004 אף \u0003שאינו מקפיד משום רובו המקפיד,\u0004 וכן \u0003על מיעוטו\u0004 שהיה מכוסה בדבר ש\u0003מקפיד\u0004 עליו \u0003משום רובו המקפיד.\u0004","ושואלים לענין זה: \u0003וליגזור נמי\u0004 \u0005[ושנגזור גם כן]\u0006 \u0003על מיעוטו שאינו מקפיד משום מיעוטו המקפיד, אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003משום רובו שאינו מקפיד!\u0004","ומשיבים: אין לעשות כן, שכן \u0003היא גופה\u0004 \u0005[עצמה]\u0006 \u0003גזירה, ואנן ניקום\u0004 \u0005[ואנו נעמוד]\u0006 \u0003ונגזור גזירה לגזירה?!\u0004 ומכל מקום חילוקי דינים אלה אינם כתובים ואינם רמוזים בתורה, ולמדנום כהלכה למשה מסיני.","בדומה לזה שואלים: מדוע אמרנו שדין \u0003מחיצות\u0004 הוא הלכה למשה מסיני, הלא \u0003דאורייתא נינהו\u0004 \u0005[מן התורה הם]\u0006 שהרי את העקרון היסודי שגובה מחיצה היוצרת רשות לעצמה הוא עשרה טפחים למדנו מן המקרא,","\u0003דאמר מר \u0005[החכם]:\u0006: ארון\u0004 הקודש שהיה במשכן גובהו \u0003תשעה\u0004 טפחים, שכן נאמר שהיה גובהו אמה וחצי. וכיון שבאמה ששה טפחים, הרי גובהו תשעה. \u0003וכפורת\u0004 שעליו \u0003טפח, הרי כאן עשרה.\u0004 וכיון שמקובל בידינו שלא ירדה שכינה אל רשות העולם הזה, ומזה שנאמר שהיתה שכינה מתגלה מעל הכפורת, נלמד שגובה עשרה טפחים יוצר רשות לעצמה!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 ללמוד הדבר מהלכה אלא לשיטת \u0003ר' יהודה\u0004 ש\u0003אמר: אמת בנין באמה בת ששה\u0004 טפחים. כלומר, כל אמות שנאמרו בבנין המקדש והמשכן הרי הן אמות גדולות בנות ששה טפחים. ואילו \u0003אמת כלים באמה בת חמשה\u0004 טפחים. אם כן, הארון שאף הוא מן הכלים שבמקדש, שמדת גובהו אמה וחצי, הריהו עם הכפורת בגובה שמונה טפחים ומחצה.","ושואלים: \u0003ול\u0004דעת \u0003ר' מאיר\u0004 ש\u0003אמר כל האמות היו בבינונית\u0004 (אמה רגילה בת ששה טפחים), \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006? שהרי לכאורה לשיטתו הכל מפורש בכתוב!","ועונים: אמנם ההלכה לענין מחיצה הגבוהה עשרה נלמדת מהכתוב, אך \u0003ל\u0004דעת \u0003ר' מאיר כי אתאי הילכתא\u0004 \u0005[כאשר באה ההלכה]\u0006 הרי זה לדינים אחרים שבמחיצות, כגון: \u0003גוד,\u0004 שאנו מחשיבים מחיצות ידועות כאילו נמשכו ועלו עד למעלה, או למשוך ולהוריד את המחיצה למטה. \u0003וללבוד,\u0004 שאנו מחשיבים דברים הסמוכים זה לזה בפחות משלשה טפחים כאילו היו צמודים. \u0003ולדופן עקומה\u0004 בסוכה, שאנו מחשיבים את חלק הגג המקיף את סכך הסוכה אם אינו רחב ארבע אמות, כאילו היה חלק מדופן הסוכה ונתעקם. ודברים אלה ודאי שלא נתפרשו בכתוב.","\u0003היה\u0004 המבוי \u0003גבוה\u0004 יותר \u0003מעשרים אמה, ובא למעטו, כמה ממעט?\u0004 ותוהים על השאלה: \u0003כמה ממעט?!\u0004 מה השאלה? \u0003כמה\u0004 ש\u0003צריך ליה\u0004 \u0005[לו] —\u0006 עד שיהא בגובה של עשרים!","\u0003אלא\u0004 כך יש לשאול: \u0003רחבו בכמה?\u0004 ודאי שיש צורך לדאוג שיהא חלל המבוי פחות מעשרים אמה, אולם מה צריך להיות רוחבו של הקטע שהגביהוהו, כדי שיתיר את השימוש בכל המבוי? \u0003רב יוסף אמר: טפח, אביי אמר: ארבעה\u0004 טפחים.","ומציעים: \u0003לימא בהא קא מיפלגי\u0004 \u0005[האם לומר\u0006 כי \u0005ב\u0006דבר \u0005זה נחלקו]\u0006 \u0003דמאן דאמר\u0004 \u0005[שמי שאומר]\u0006 \u0003טפח קסבר\u0004 \u0005[סבור]:\u0006 \u0003מותר להשתמש תחת הקורה\u0004 שבמבוי, שלדעתו מועילה הקורה כמחיצה, ומן הקצה החיצון של המחיצה (הפונה אל הרחוב) ולפנים נעשה כמבוי נעול ומותר לטלטל שם."],["\u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003ארבעה\u0004 טפחים \u0003קסבר\u0004 \u0005[סבור]:\u0006 שרק מן הקצה הפנימי של הקורה בלבד נעשה כמבוי נעול ומותר בשימוש, ואם כן, אסור \u0003להשתמש תחת הקורה!\u0004","ודוחים: \u0003לא, דכולי עלמא קסברי\u0004 \u0005[שהכל סבורים]\u0006 \u0003מותר להשתמש תחת הקורה. ובהא קא מיפלגי\u0004 \u0005[ובזה נחלקו],\u0006 \u0003מר\u0004 \u0005[חכם זה,\u0006 רב יוסף\u0005]\u0006 \u0003סבר: קורה\u0004 מועילה למבוי \u0003משום היכר\u0004 להבדילו מרשות הרבים, ולכן בטפח בלבד די, שהרי גם בטפח יש משום היכר מספיק. \u0003ומר\u0004 \u0005[וחכם זה,\u0006 אביי\u0005]\u0006 \u0003סבר: קורה משום מחיצה\u0004 ואין מחיצה מועילה לשטח בפחות מארבעה טפחים.","\u0003ואיבעית אימא, דכולי עלמא\u0004 \u0005[ואם תרצה אמור: שהכל\u0006 סבורים\u0005]:\u0006 \u0003קורה משום היכר. והכא\u0004 \u0005[וכאן] —\u0006 \u0003בהיכר של מטה ובהיכר של מעלה קמיפלגי; דמר\u0004 \u0005[שחכם זה,\u0006 רב יוסף\u0005]\u0006 \u0003סבר: אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003היכר של מטה\u0004 דינו \u0003כהיכר של מעלה,\u0004 ודי בטפח אחד. \u0003ומר\u0004 \u0005[וחכם זה,\u0006 אביי\u0005]\u0006 \u0003סבר: לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \u0003היכר של מטה כהיכר של מעלה,\u0004 אלא למטה צריך להיות בולט יותר ודינו בארבעה טפחים.","\u0003ואיבעית אימא דכולי עלמא אמרינן\u0004 \u0005[ואם תרצה אמור שלדעת הכל אומרים אנו]:\u0006 \u0003היכר של מטה כהיכר של מעלה,\u0004 ובעצם מספיק אפילו בטפח, \u0003והכא\u0004 \u0005[וכאן]\u0006 \u0003בגזירה שמא יפחות\u0004 ויתמעט ההיכר הזה על ידי דריכת רגלי האנשים ההולכים במבוי \u0003קמיפלגי\u0004 \u0005[נחלקו],\u0006 שרב יוסף אינו חושש שמא יפחת, ואביי שאינו מסתפק בטפח אחד חושש שמא ההיכר, כלומר הגבהת הקרקע בטפח אחד, יפחת על ידי דריסת הרגלים ואז גם טפח לא יהיה, ואנשים לא יבחינו וישתמשו במבוי שלא כדין.","\u0003היה\u0004 המבוי \u0003פחות מעשרה טפחים\u0004 בגובהו \u0003וחקק\u0004 (חפר) \u0003בו להשלימו לעשרה, כמה חוקק?\u0004 ותוהים: \u0003כמה חוקק?! כמה שצריך ליה\u0004 \u0005[לו]\u0006 עד שישלים את גובהו לעשרה. \u0003אלא\u0004 יש להבין שהשאלה היא \u0003משכו בכמה.\u0004 כלומר, מה צריך להיות אורכה המינימלי של החפירה לאורך המבוי. \u0003רב יוסף אמר: בארבעה\u0004 טפחים, \u0003אביי אמר: בארבע אמות.\u0004","ומציעים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 שבשיטת \u0003ר' אמי ור' אסי קמיפלגי\u0004 \u0005[נחלקו],\u0006 \u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שדנו חכמים בשאלה: \u0003מבוי שנפרץ\u0004 הכותל \u0003מצידו\u0004 בחלק \u0003כלפי ראשו\u0004 בקצה המבוי הנוטה לרשות הרבים, מה תקנה יש לו? \u0003איתמר משמיה\u0004 \u0005[נאמר משמו]\u0006 של \u0003ר' אמי ור' אסי: אם יש שם פס ארבעה\u0004 טפחים לסתום חלק מן הכותל הפרוץ — \u0003מתיר בפרצה\u0004 שאורכה \u0003עד עשר\u0004 אמות.","\u0003ואם לאו\u0004 שאין שם פס כזה, אם היה החלל \u0003פחות משלשה\u0004 טפחים \u0003— מתיר\u0004 תיקון המבוי (בלחי או בקורה) לטלטל בו מדין לבוד. \u0003שלושה — אינו מתיר.\u0004 ונאמר כי \u0003רב יוסף אית ליה\u0004 \u0005[יש לו,\u0006 הוא מקבל \u0003]\u0004 את דברי \u0003ר' אמי,\u0004 ואילו לשיטת \u0003אביי לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 את שיטת \u0003ר' אמי.\u0004","\u0003ודוחים: אמר\u0004 \u0005[\u0006יכול \u0005לומר]\u0006 \u0003לך אביי:\u0004 שאין להשוות: \u0003התם\u0004 \u0005[שם]\u0006 בדברי ר' אמי \u0003סוף מבוי\u0004 כלומר, אותו מבוי היה מתחילתו כראוי, והתקלקל לאחר זמן. \u0003הכא\u0004 \u0005[כאן\u0006 מדובר\u0005]\u0006 \u0003תחלת מבוי,\u0004 כשמלכתחילה לא היו בו התנאים העושים אותו מבוי, ובמקרה זה: \u0003אי איכא\u0004 \u0005[אם יש]\u0006 \u0003ארבע אמות\u0004 באורכו — \u0003אין\u0004 \u0005[כן]\u0006 הרי זה מבוי. \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 \u0005—\u0006 \u0003לא\u0004 נחשב מבוי.","\u0003אמר אביי: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה\u0006, את דעתי זו\u0005]\u0006 שצריך לכל הפחות אורך של ארבע אמות — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין מבוי ניתר בלחי וקורה\u0004 כדינו \u0003עד שיהו בתים וחצרות\u0004 גם יחד \u0003פתוחים לתוכו\u0004 שרק כגון זה קרוי מבוי.","\u0003ואי\u0004 \u0005[ואם]\u0006 כל אורך המבוי \u0005אינו אלא\u0006 \u0003ארבעה\u0004 טפחים \u0003היכי משכחת ליה\u0004 \u0005[כיצד מוצא אתה אותה]\u0006 מציאות שמבוי קצר כזה יהיו חצרות פתוחות לו, והרי אין פתח בפחות מארבעה!","\u0003וכי תימא דפתח \u0004\u0005[ואם תאמר שפותח] \u0006\u0003לה בדופן האמצעי\u0004 את פתחי החצרות, שאמנם אורך המבוי קטן ביותר אבל רוחבו גדול, וברוחבו מצויים שני פתחים לשתי חצרות, \u0003ו\u0004אולם \u0003האמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב נחמן: נקיטינן\u0004 \u0005[מוחזקים אנו]\u0006 בהלכה זו, \u0003איזהו מבוי שניתר בלחי וקורה — כל שארכו יתר על רחבו, ובתים וחצרות פתוחים לתוכו.\u0004 ואם אורך המבוי ארבעה טפחים, הרי רחבו צריך להיות פחות אפילו מארבעה.","\u0003ו\u0004מתרץ \u0003רב יוסף:\u0004 כגון \u0003דפתח ליה\u0004 \u0005[שעשה פתחים בו]\u0006 \u0003בקרן זוית,\u0004 ואז יתכן שיהיו שני פתחים שכל אחד מהם רחבו לפחות ארבעה טפחים, אף שאורך המבוי עצמו אינו יתר על ארבעה טפחים.","ועוד \u0003אמר אביי: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה\u0006 את הלכתי זו\u0005] —\u0006 ש\u0003אמר רמי בר חמא אמר רב הונא: לחי הבולט מדופנו של מבוי\u0004 אל חלל המבוי, אם היה ארכו של הלחי \u0003פחות מארבע אמות — נידון\u0004 עדיין \u0003משום לחי\u0004 ומותר לטלטל שם, \u0003ואינו צריך לחי אחר להתירו.\u0004 אבל אם היה בולט \u0003ארבע אמות — נידון\u0004 חלק זה \u0003משום מבוי\u0004 כאילו היה מבוי נוסף בתוך מבוי \u0003וצריך לחי אחר להתירו\u0004 הרי שבפחות מארבע אמות אין תורת מבוי עליו, והרי זו ראיה לשיטת אביי.","ושואלים: \u0003ורב יוסף\u0004 מה הוא אומר בענין זה? ומשיבים שהוא מחלק בין המקרים: \u0003לאפוקי\u0004 \u0005[כדי להוציאו]\u0006 \u0003מתורת לחי — עד דאיכא\u0004 \u0005[שיש]\u0006 בו \u0003ארבע אמות.\u0004 ובפחות מארבע אמות עדיין דינו כלחי, אולם \u0003למיהוי\u0004 \u0005[להיות]\u0006 \u0003מבוי אפילו בארבעה טפחים נמי הוי\u0004 \u0005[גם כן הרי הוא]\u0006 \u0003מבוי.\u0004","\u0003גופא [ול\u0004\u0005גוף הענין],\u0006 כיון שהוזכרה ההלכה בדרך אגב, דנים \u0003ומבררים אותה עכשיו לגופה. אמר רמי בר חמא אמר רב הונא: לחי הבולט מדופנו של מבוי\u0004"],["\u0003פחות מארבע אמות\u0004 הרי זה \u0003נידון משום לחי, ואין צריך לחי אחר להתירו.\u0004 ואם היה בולט \u0003ארבע אמות — נידון\u0004 כבר \u0003משום מבוי, וצריך לחי אחר להתירו.\u0004","ושואלים: \u0003אותו לחי\u0004 שמוסיפים כדי להתיר את הלחי הראשון, \u0003היכן מעמידו\u0004 כדי שיתיר? \u0003אי דמוקי ליה בהדיה\u0004 \u0005[אם שמעמיד אותו עמו],\u0006 כלומר בתוספת לחי ראשון\u0005,\u0006 \u0003אוספי הוא דקא מוסיף עליה\u0004 \u0005[הריהו\u0006 רק \u0005מוסיף עליו]\u0006 ואינו ניכר שיש כאן לחי יתר.","\u0003אמר רב פפא: דמוקי ליה לאידך גיסא\u0004 \u0005[ששם אותו,\u0006 את הלחי היתר\u0005, בצד אחר]\u0006 ליד הכותל השני. \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע אמר: אפילו תימא דמוקי לה בהדיה\u0004 \u0005[תאמר שמעמיד אותו עמו]\u0006 \u0003אלא דמטפי ביה, או דמבצר ביה\u0004 \u0005[שמוסיף בו\u0006 בעובי, ברוחב או בגובה, \u0005או שממעט בו]\u0006 וניכר שהוא לחי בפני עצמו,","\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: לא אמרן\u0004 \u0005[אמרנו]\u0006 הלכה זו דמבוי שיש בו לחי שארכו ארבע אמות, \u0003אלא\u0004 שהיה רוחב ה\u0003מבוי שמונה\u0004 אמות. \u0003אבל במבוי\u0004 שיש ברוחבו רק \u0003שבע\u0004 אמות — \u0003ניתר\u0004 המבוי בטלטול לא מתורת לחי אלא משום שלחי זה סותם את פתח המבוי, ובפתחו יש \u0003עומד מרובה על הפרוץ,\u0004 שהרי המבוי סגור עתה מארבע רוחות, וקצהו הפתוח לרשות הרבים אינו אלא פתח, כיון שרובו סגור, ורק מיעוטו פתוח.","ונלמד זאת ב\u0003קל וחומר מחצר: ומה חצר שאינה ניתרת\u0004 בטלטול על ידי \u0003לחי וקורה,\u0004 אלא צריכה מחיצות ממש, \u0003ניתרת\u0004 גם אם היו מחיצותיה רק \u0003עומד מרובה על הפרוץ, מבוי\u0004 שהקלו בו חכמים \u0003שניתר בלחי וקורה — אינו דין שניתר בעומד מרובה על הפרוץ?\u0004","ודוחים: \u0003מה לחצר\u0004 שאתה לומד ממנה, \u0003שכן פרצתה בעשר,\u0004 שכל עוד לא נפרצה גדר החצר ביותר מעשר אמות, עדיין נחשבת החצר גדורה כל צרכה. \u0003תאמר במבוי שפרצתו\u0004 הפוסלת אותו \u0003בארבעה\u0004 טפחים בלבד!","ועונים: \u0003קסבר\u0004 \u0005[סבור]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: מבוי נמי\u0004 \u0005[גם כן],\u0006 \u0003פרצתו בעשר.\u0004 ומקשים: והלא \u0003למאן קאמרינן\u0004 \u0005[ל\u0006שיטת \u0005מי אמרנו]\u0006 דבר זה? — \u0003ל\u0004שיטת \u0003רב הונא\u0004, ואולם, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב הונא\u0004 עצמו \u0003פרצתו בארבע סבירא ליה\u0004 \u0005[סבור]?!\u0006","ומשיבים: כי \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע\u0004 לא בא להסביר את שיטת רב הונא, אלא \u0003טעמא דנפשיה קאמר\u0004 \u0005[הטעם של עצמו אמר],\u0006 ושיטתו שלו היא, ואינו מקבל את דברי רב הונא בדין פירצת מבוי.","\u0003רב אשי אמר\u0004 יתר על דברי רב הונא בנו של רב יהושע: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 \u0003במבוי\u0004 שרוחבו \u0003שמונה\u0004 אמות בדיוק גם כן אינו \u0003צריך לחי,\u0004 ונסיק זאת בדרך \u0003מה נפשך\u0004 כלומר: בכל אופן שנרצה להעמיד את הדברים, נצטרך להגיע למסקנה זו כי: \u0003אי\u0004 \u0005[אם]\u0006 ה\u0003עומד נפיש\u0004 \u0005[מרובה]\u0006 הרי \u0003ניתר\u0004 המבוי משום \u0003עומד מרובה על הפרוץ, ואי\u0004 \u0005[ואם]\u0006 תאמר ש\u0003פרוץ נפיש\u0004 \u0005[מרובה]\u0006 הרי הוא \u0003נידון משום לחי\u0004 שנמצא שרוחבו פחות מארבע אמות.","\u0003מאי אמרת\u0004 \u0005[מה אומר אתה]\u0006 שיכול להיות עוד מקרה אחד \u0003דשוו תרוייהו כי הדדי\u0004 \u0005[ששווים שניהם,\u0006 החלק העומד והחלק הפרוץ, \u0005זה לזה]\u0006 ואין אנו בטוחים אם פרוץ מרובה או עומד מרובה. \u0003הוה ליה\u0004 \u0005[הרי זה]\u0006 \u0003ספק דבריהן\u0004 של חכמים. וכלל בידינו ש\u0003ספק דבריהן\u0004 של חכמים \u0003להקל\u0004 שלא כספק מן התורה, שספקו להחמיר.","\u0003אמר רב חנין בר רבא אמר רב: מבוי שנפרץ\u0004"],["\u0003מצידו\u0004 שיעור רוחב חלל הפירצה שיהא אסור לטלטל במבוי — \u0003בעשר,\u0004 ואם נפרץ מ\u0003ראשו\u0004 בפתח המבוי הפונה לרשות הרבים — \u0003בארבעה\u0004 טפחים.","ושואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 אם \u0003מצידו בעשר, דאמר\u0004 \u0005[ש\u0006כן \u0005אומר אתה]\u0006 \u0003פתחא\u0004 \u0005[פתח]\u0006 \u0003הוא — מראשו נמי נימא\u0004 \u0005[גם כן נאמר]\u0006 \u0003פתחא\u0004 \u0005[פתח]\u0006 \u0003הוא\u0004, ויהא כשר עד עשר אמות!","\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: כגון שנפרץ\u0004 אותו מבוי \u0003בקרן זוית,\u0004 ומכיון \u0003דפתחא\u0004 \u0005[שפתח]\u0006 \u0003בקרן זוית לא עבדי אינשי\u0004 \u0005[אין אנשים עושים],\u0006 אין לראות פירצה זו כעין פתח. ואם היתה הפירצה יתירה מארבעה טפחים צריך לסתום אותה.","\u0003ורב הונא אמר:\u0004 אין לחלק בין נפרץ מצידו לנפרץ מראשו, אלא \u0003אחד זה ואחד זה בארבעה\u0004 טפחים. \u0003וכן אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא לרב חנן בר רבא\u0004: \u0003לא תפלוג עלאי\u0004 \u0005[אל תחלוק עלי]\u0006 שהרי \u0003רב איקלע\u0004 \u0005[הזדמן]\u0006 \u0003ל\u0004מקום ששמו \u0003דמחריא ועבד עובדא כוותי\u0004 \u0005[ועשה מעשה כמותי,\u0006 כשיטתי\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 אין להביא ראיה מאותו מעשה כי שם \u0003רב בקעה מצא וגדר בה גדר.\u0004 כלומר שבני אותו מקום לא היו בני תורה וכדי לזרזם ולהפרישם מאיסור, החמיר רב עליהם והוסיף להם סייג, אבל אין זו הלכה כללית.","\u0003אמר רב נחמן בר יצחק: כוותיה דרב הונא מסתברא\u0004 \u0005[כשיטתו של רב הונא מסתבר]\u0006 \u0003דאיתמר\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 שנחלקו: \u0003מבוי עקום\u0004 הפונה לרשות הרבים בשני ראשיו — \u0003רב אמר: תורתו כמפולש\u0004 ויש לעשות בו תקנה הראויה למבוי כזה, על ידי שיעמיד צורת הפתח משני ראשיו, או שיעשה צורת פתח במקום עקמומיתו, לחי וקורה מכל צד. \u0003ושמואל אמר: תורתו כסתום\u0004 ועושים בני כל צד לפיתחם לחי או קורה בלבד ודיו.","ומבררים: \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים]\u0006 כיצד בדיוק הוא המקרה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003ביותר מעשר\u0004 שהיה רוחב המבוי במקום עקמימותו יותר מעשר אמות? \u0003בהא לימא\u0004 \u0005[בזו יאמר]\u0006 \u0003שמואל\u0004 ש\u0003תורתו כסתום\u0004 הלא פתח גמור והמבוי כפתוח ומפולש לכל צד?","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003בעשר\u0004 אמות או אפילו פחות, ובכל זאת \u0003אמר רב תורתו כמפולש, אלמא\u0004 \u0005[מכאן]\u0006 כי \u0003פירצת מבוי\u0004 אוסרת \u0003מצידו בארבעה\u0004 טפחים בלבד!","\u0003ורב חנן בר רבא\u0004 אומר כי אין להשוות את המקרים, כי \u0003שאני התם דקא בקעי\u0004 \u0005[שונה שם\u0006 במבוי עקום \u0005ש\u0006כן \u0005עוברים]\u0006 \u0003בה רבים\u0004 דרך אותה עקמימות. ומאחר שלמעשה המבוי מפולש לרבים, מקפידים בו אף בפירצה קטנה.","ומקשים: האם \u0003מכלל הדברים נלמד שרב הונא סבר: אף על גב\u0004 \u0005[אף על פי]\u0006 \u0003דלא בקעי\u0004 \u0005[שאין בוקעים]\u0006 \u0003בה רבים\u0004 צריכים מחיצה כזו, \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 מדברי \u0003ר' אמי ור' אסי\u0004 שהבאנו לעיל, שדי בפס ארבעה טפחים כדי לסתום פירצה עד עשר אמות?","ומשיבים: \u0003התם דאיכא גידודי\u0004 \u0005[שם שיש שרידי גדר\u0006 מכל צד\u0005]\u0006 המקשים על המעבר, ולכן פירצה זו נחשבת כפתח שאינו מבטל את המחיצות, \u0003הכא — דליכא גידודי\u0004 \u0005[כאן —\u0006 \u0005שאין שרידי גדר].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בבריתא\u0005]:\u0006 \u0003כיצד מערבין\u0004 את \u0003דרך רשות הרבים\u0004 שתיחשב כרשותם של היחידים, ויהא מותר לטלטל בה? \u0003עושה צורת הפתח\u0004 לדרך \u0003מכאן,\u0004 מצד זה שלה, \u0003ולחי וקורה מכאן. חנניה אומר:\u0004 לא כך הדבר; אלא מחלוקת תנאים קדומה היא, ש\u0003בית שמאי אומרים: עושה דלת מכאן ודלת מכאן וכשהוא יוצא ונכנס — נועל,\u0004 שאין די בדלת סימלית, ונחוץ שתהא הדלת ממש סגורה. \u0003ובית הלל אומרים: עושה דלת מכאן, ולחי וקורה מכאן.\u0004","ושואלים: ומעיקרו של דבר, \u0003רשות הרבים מי מיערבא\u0004 \u0005[האם\u0006 ניתנת להיות \u0005מעורבת]\u0006 וניתרת על ידי עירוב?! והרי שנינו בברייתא: \u0003יתר על כן אמר ר' יהודה\u0004"],["\u0003מי שהיו לו שני בתים משני צידי רשות הרבים\u0004 ורוצה לטלטל בין הבתים שלו דרך רשות הרבים, מבית לבית, \u0003עושה לחי מכאן ולחי מכאן\u0004 מצידי הבתים. \u0003או קורה מכאן וקורה מכאן, ונושא ונותן באמצע.\u0004 שעל ידי כך עשה אף את השטח שבאמצע כרשות היחיד. \u0003אמרו לו: אין מערבין רשות הרבים בכך,\u0004 נמצא שאין דרך לערב רשות הרבים גמורה.","\u0003וכי תימא\u0004 \u0005[וכי תאמר]\u0006 \u0003בכך הוא דלא מיערבא\u0004 \u0005[שאינה מעורבת],\u0006 שתקנה זו בלבד, של לחי או קורה, היא שאינה מספקת, \u0003הא\u0004 \u0005[הרי,\u0006 ואולם\u0005]\u0006 \u0003בדלתות\u0004 יכולה להיות \u0003מיערבא\u0004 \u0005[מעורבת],\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבה בר בר חנה אמר ר' יוחנן: ירושלים, אילמלא דלתותיה ננעלות בלילה חייבין עליה משום רשות הרבים!\u0004 נמצא שלא די במציאותה של דלת כדי להתיר לטלטל ברשות הרבים ויש צורך שתהא הדלת נעולה ממש.","\u0003ו\u0004כן \u0003אמר עולא: הני אבולי דמחוזא\u0004 \u0005[אותם מבואות ש\u0006בעיר \u0005מחוזא]\u0006 שהיו רשות הרבים גמורה והיו שעריהם פתוחים זה כנגד זה \u0003אילמלא דלתותיהן ננעלות — חייבין עליהן משום רשות הרבים.\u0004 הרי שבלא נעילת דלת ממש, אי אפשר לערב ברשות הרבים על ידי מחיצה סימלית כלחי וקורה. ואם כן כיצד נחלקו חכמים בברייתא כיצד מערבים את רשות הרבים?","אלא, \u0003אמר רב יהודה:\u0004 יש לתקן את לשון הברייתא, ו\u0003הכי קאמר\u0004 \u0005[וכך אמר]\u0006: \u0003כיצד מערבין מבואות המפולשין לרשות הרבים,\u0004 שהם עצמם אינם רשות הרבים אבל הם פתוחים בשני קצותיהם לרשות הרבים \u0003— עושה צורת הפתח מכאן ולחי וקורה מכאן.\u0004","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בפסק ההלכה בנושא זה. \u0003רב אמר: הילכתא כתנא קמא\u0004 \u0005[הלכה כתנא הראשון]\u0006 ודי בצורת הפתח בצד אחד ולחי וקורה בצד השני, להתיר דרך רשות הרבים. \u0003ושמואל אמר: הלכה כחנניה\u0004 לשיטת בית הלל, ודרושה גם דלת בצד אחד.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדים\u0005]\u0006 \u0003לחנניה אליבא\u0004 \u0005[לפי שיטת]\u0006 \u0003בית הלל צריך לנעול או אין צריך לנעול\u0004 את הדלת הזאת? \u0003תא שמע\u0004 \u0005[בא ושמע]\u0006 מביאים ראיה ממה ש\u0003אמר רב יהודה אמר שמואל\u0004 שהוא, כפי שראינו, פסק כשיטה זו: \u0003אינו צריך לנעול. וכן אמר רב מתנה אמר שמואל: אינו צריך לנעול. איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 \u0003אמר רב מתנה: בדידי הוה עובדא\u0004 \u0005[בי עצמי היה מעשה]\u0006 בבעיה כעין זו, \u0003ואמר לי שמואל: אין צריך לנעול.\u0004","\u0003בעו מיניה\u0004 \u0005[שאלו ממנו]\u0006 \u0003מרב ענן\u0004 בענין זה: \u0003צריך לנעול או אין צריך לנעול? אמר להו\u0004 \u0005[להם]:\u0006 \u0003תא חזי הני אבולי דנהרדעא דטימן עד פלגייהו בעפרא, ועייל ונפיק\u0004 \u0005[בא וראה אותם מבואות של נהרדעא שסתומים עד חציים בעפר, והיה נכנס ויוצא]\u0006 בהם \u0003מר שמואל, ולא אמר להו\u0004 \u0005[להם]\u0006 \u0003ולא מידי\u0004 \u0005[דבר].\u0006 הרי שאין צורך בהגפת דלתות.","\u0003אמר רב כהנא: הנך\u0004 \u0005[אלה\u0006 דלתות שבנהרדעא\u0005]\u0006 \u0003מגופות הואי\u0004 \u0005[מוגפות היו]\u0006 בחלקן, וכיון שכך, לא היה צורך לנעלן, אבל בדרך כלל דלתות צריכות להיות נעולות.","ומספרים, \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב נחמן אמר: פניוה לעפרייהו\u0004 \u0005[פנו את עפרן]\u0006 כדי שאפשר יהיה לנעול. ושואלים: \u0003לימא קסבר\u0004 \u0005[האם נאמר שסבר]\u0006 \u0003רב נחמן: צריך לנעול?\u0004 ועונים: \u0003לא\u0004, אין זו ראיה, כי מ\u0003כיון\u0004 ש\u0003ראויות לנעול, אף על פי שאין ננעלות\u0004 ממש — די בהן כדי להתיר. ואין להקפיד אלא שתהיינה ראויות לנעילה.","מסופר: \u0003ההוא\u0004 \u0005[אותו]\u0006 \u0003מבוי עקום דהוה\u0004 \u0005[שהיה]\u0006 \u0003בנהרדעא, רמי עליה חומריה דרב וחומריה דשמואל ואצרכוהו\u0004 \u0005[הוטל עליו חומרתו של רב וחומרתו של שמואל, והצריכוהו]\u0006 \u0003דלתות.\u0004 ומבארים: \u0003חומריה דרב\u0004 \u0005[חומרתו של רב],\u0006 ש\u0003אמר\u0004 מבוי עקום \u0003תורתו כמפולש.\u0004 ותוהים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב הלכה כתנא קמא,\u0004 ולפי שיטה זו אפילו מבוי המפולש ממש דיו בצורת הפתח?!","ועונים: שעשו זאת \u0003כשמואל\u0004 — ש\u0003אמר: הלכה כחנניה.\u0004 אולם אם כשמואל — \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל\u0004 שמבוי עקום \u0003תורתו כסתום!\u0004 ועונים: שזאת עשו \u0003כרב\u0004 ש\u0003אמר תורתו כמפולש.\u0004 והחמירו כשתי השיטות גם יחד.","ושואלים: \u0003ומי עבדינן כתרי חומרי\u0004 \u0005[והאם עושים אנו כשתי חומרות]?\u0006 \u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003לעולם הלכה כבית הלל והרוצה לעשות כדברי בית שמאי — עושה, כדברי בית הלל — עושה.\u0004 אם רצה לעשות גם \u0003מקולי\u0004 \u0005[כהקלות]\u0006 שיטת \u0003בית שמאי ו\u0004גם \u0003מקולי בית הלל\u0004 — הרי זה \u0003רשע.\u0004 אם רצה לעשות גם \u0003מחומרי בית שמאי ו\u0004גם \u0003מחומרי בית הלל — עליו הכתוב אומר: \"הכסיל בחשך הולך\"\u0004 (קהלת ב, יד). \u0003אלא, אי כבית שמאי כקוליהון וכחומריהון, אי כבית הלל כקוליהון וכחומריהון\u0004 \u0005[או כבית שמאי כהקלותיהם והחמרותיהם, או כבית הלל כהקלותיהם והחמרותיהם].\u0006","ומתחילה מבררים את עצם לשונה של ברייתא זו; \u0003הא גופא קשיא\u0004 \u0005[זו עצמה קשה]:\u0006 \u0003אמרת\u0004 \u0005[אמרת]\u0006 מתחילה: \u0003לעולם הלכה כבית הלל, והדר אמרת\u0004 \u0005[וחזרת ואמרת]:\u0006 \u0003הרוצה לעשות כדברי בית שמאי עושה!?\u0004","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]\u0006 \u0003כאן,\u0004 שנאמר שיכול לעשות כפי שירצה — \u0003קודם בת קול\u0004 שיצאה ואמרה שהלכה כבית הלל. \u0003כאן\u0004 שאמרו שהלכה כדברי בית הלל — \u0003לאחר בת קול.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר: \u0003הא והא\u0004 \u0005[זה וזה]\u0006 — \u0003לאחר בת קול\u0004"],["\u0003ו\u0004כשיטת \u0003ר' יהושע היא דלא משגח\u0004 \u0005[שאינו משגיח]\u0006 \u0003בבת קול\u0004 ולפי שיטה זו עדיין לא הוכרעה מחלוקת בית שמאי ובית הלל.","\u0003ואיבעית אימא הכי קאמר\u0004 \u0005[ואם תרצה כך נאמר]\u0006 בברייתא זו: \u0003כל היכא דמשכחת תרי תנאי ותרי אמוראי דפליגי אהדדי\u0004 \u0005[\u0006ב\u0005כל מקום שאתה מוצא שני תנאים ושני אמוראים החולקים זה על זה]\u0006 \u0003כעין מחלוקת בית שמאי ובית הלל\u0004 — \u0003לא ליעבד כי קוליה דמר וכי קוליה דמר, ולא כחומריה דמר וכי חומריה דמר. אלא, או כי קוליה דמר וכחומריה עביד, או כקוליה דמר וכחומריה עביד\u0004 \u0005[לא יעשה כהקלתו של חכם זה וכהקלתו של חכם זה, ולא כהחמרתו של חכם זה וכהחמרתו של חכם זה. אלא, או כהקלותיו של חכם זה וכהחמרתו יעשה, או כהקלתו של חכם זה וכהחמרתו יעשה].\u0006","דברים אלה שאמרנו באו ליישב את לשונה של הברייתא. \u0003מכל מקום\u0004, בכל אופן, קשה ממה שעשו באותו מבוי שהחמירו עליו גם כשיטת רב וגם כשיטת שמואל!","\u0003אמר רב נחמן בר יצחק: כוליה כרב עבדוה\u0004 \u0005[כולו כ\u0006שיטת \u0005רב עשו]\u0006 ומה שלא סמכו במבוי זה על צורת הפתח בלבד הרי \u0003אמר רב הונא אמר\u0004 בשם \u0003רב: הלכה ואין מורין כן.\u0004 שאף שסבור רב שצורת הפתח מתירה במבוי מפולש, מכל מקום אין מורים לרבים לעשות כן, אלא מחמירים כשיטת חנניה.","ושואלים: \u0003ול\u0004שיטת \u0003רב אדא בר אהבה אמר\u0004 בשם \u0003רב\u0004 ש\u0003אמר\u0004 שבאותו נושא: \u0003הלכה ומורין כן, מאי איכא למימר?\u0004 \u0005[מה יש לומר]\u0006 ומדוע החמירו כשתי השיטות?","\u0003אמר רב שיזבי: כי לא עבדינן כחומרי דבי תרי — היכא דסתרי אהדדי\u0004 \u0005[כאשר אין אנו עושים כחומרות של שנים\u0006 \u0003—\u0004 הרי זה \u0005במקום ש\u0006הן \u0005סותרות זו את זו].\u0006 שבמקום שטעמי השיטות סותרים זה את זה, אם יחמיר בשתיהן נמצא סותר את עצמו.","\u0003כגון\u0004 ענין זה של הלכה ב\u0003שדרה וגולגולת. דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006: \u0003השדרה והגולגולת\u0004 של המת ש\u0003חסרו\u0004 (שנפל חלק מהן) שוב אינם מטמאות טומאת אוהל כמת שלם, אלא רק כעצמות בלבד. הלכה עקרונית זו מקובלת היתה, אולם נחלקו — \u0003כמה חסרון\u0004 יהיה \u0003בשדרה\u0004 ותחשב חסרה לענין זה? \u0003בית שמאי אומרים\u0004: אם היו חסרות בה \u0003שתי חוליות, ובית הלל אומרים: חוליא אחת\u0004. וכן נחלקו בחסרון \u0003בגולגולת, בית שמאי אומרים\u0004: חסרונה, \u0003כמלא\u0004 נקב שעושה \u0003מקדח, ובית הלל אומרים: כדי שינטל מן החי וימות\u0004, ושיעורו גדול יותר.","\u0003ואמר רב יהודה אמר שמואל: וכן\u0004 נחלקו בית שמאי ובית הלל \u0003לענין טריפה;\u0004 שבית שמאי אומרים שבהמה נעשית טריפה אם חסרו בה שתי חוליות, ובית הלל אומרים שהיא טריפה אפילו בחסרון חוליה אחת. ואינו יכול להחמיר בדיני טריפה כשיטת בית הלל, ובדיני טומאת המת כשיטת בית שמאי, כיון ששתי המחלוקות תלויות זו בזו, ואינו יכול לנהוג כשתי דעות סותרות.","\u0003אבל היכא דלא סתרי אהדדי — עבדינן\u0004 \u0005[במקום שאינם סותרים זה את זה —\u0006 \u0005אנו עושים]\u0006 כשתי חומרות. ואף במבוי העקום כיון שהחמירו כשתי שיטות נפרדות (לענין מבוי מפולש ולעיקר דינו של מבוי סתום) מותר הדבר.","ושואלים: האם \u0003היכא דסתרי אהדדי לא עבדינן?!\u0004 \u0005[ובמקום שסותרים זה את זה אין אנו עושים]?\u0006 \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב משרשיא: מעשה בר' עקיבא שליקט אתרוג באחד בשבט, ונהג בו שני עישורין;\u0004 משום שנוסף למעשר הראשון (הניתן ללויים) שהוא קבוע בכל שנה, מפרישים בשנה אחת מעשר שני שאותו מעלים לירושלים, ובשנה אחרת מעשר עני הניתן לעניים. וכיון שלא קבע ר' עקיבא לאיזו שנה בשמיטה שייכים פירות אלה, הפריש עבורם גם מעשר שני וגם מעשר עני. \u0003אחד כדברי בית שמאי\u0004 שאומרים שראש השנה לאילנות באחד בשבט, וכיון שיום זה שייך לשנה החדשה יש לעשר בה כתורת אותה שנה. \u0003ואחד כדברי בית הלל\u0004 שראש השנה לאילנות בחמשה עשר בשבט, ויש לעשרו כפי הראוי בשנה שעברה. ואם כן החמיר על עצמו שתי חומרות הסותרות זו את זו?!","ומשיבים: \u0003ר' עקיבא\u0004 נהג כן לא משום שרצה להחמיר כשתי השיטות, אלא \u0003גמריה איסתפיק ליה\u0004 \u0005[תלמודו הסתפק לו]\u0006 \u0003ולא ידע אי\u0004 \u0005[אם]\u0006 \u0003בית הלל בחד\u0004 \u0005[באחד]\u0006 \u0003בשבט אמור\u0004 \u0005[אמרו],\u0006 \u0003אי בחמיסר בשבט אמור\u0004 \u0005[או בחמישה עשר בשבט אמרו],\u0006 \u0003ועבד הכא לחומרא והכא לחומרא\u0004 \u0005[ועשה כאן לחומרה וכאן לחומרה].\u0006","על הבעיה בתיקון מבואות המפולשים \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב יוסף קמיה\u0004 \u0005[לפני]\u0006 \u0003רב הונא, ויתיב וקאמר\u0004 \u0005[וישב ואמר],\u0006 \u0003אמר רב יהודה אמר רב: מחלוקת\u0004 של תנא קמא וחנניה כשיש \u0003בסרטיא\u0004 \u0005[רחוב,\u0006 רשות הרבים העשויה להילוך בני אדם\u0005],\u0006 \u0003מכאן וסרטיא מכאן\u0004 לצד המבוי, או \u0003פלטיא\u0004 \u0005[רחוב השוק]\u0006 \u0003מכאן ופלטיא מכאן.\u0004","\u0003אבל\u0004 אם היתה \u0003סרטיא מכאן ובקעה\u0004 שהיא כרמלית, ואסורה רק מדברי חכמים \u0003מכאן, או בקעה מכאן ובקעה מכאן — עושה צורת הפתח מכאן, ולחי וקורה מכאן.\u0004 והרי זה מועיל לתיקון המבוי אף לשיטת חנניה.","ומתחילה תוהים על עיקר הענין: \u0003השתא\u0004 \u0005[עכשיו]\u0006 הרי אמרת שאם היתה \u0003סרטיא מכאן ובקעה מכאן,\u0004 דיו ב\u0003צורת הפתח מכאן ולחי וקורה מכאן,\u0004 אם היתה \u0003בקעה מכאן ובקעה מכאן מיבעיא?!\u0004 \u0005[נצרכה\u0006 לומר שמועיל?!\u0005]\u0006","ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך נתכוון\u0005]:\u0006 אם היתה \u0003סרטיא מכאן ובקעה מכאן — נעשה כבקעה מכאן ובקעה מכאן.\u0004","והיה רב יוסף \u0003מסיים בה\u0004 בהלכה זו \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב יהודה\u0004 עצמו ש\u0003אם היה מבוי כלה לרחבה\u0004 שלאחורי הבתים, אף שהיא פרוצה לרשות הרבים, \u0003אין צריך\u0004 לתקן בצד זה של המבוי \u0003כלום,\u0004 שהריהו כסגור.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: הא\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 של \u0003רב יהודה\u0004 כשיטת רבו \u0003שמואל היא\u0004 ולא מדברי רבו האחר, רב."],["\u0003דאי\u0004 \u0005[שאם]\u0006 תאמר שאמר זאת משם \u0003רב — קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003רב אדרב בתרתי\u0004 \u0005[על\u0006 דברי \u0005רב\u0006 עצמו \u0005בשתיים]\u0006 אם משום שיש כאן מבוי המפולש לרשות הרבים משני צדיו, וכן ממה ש\u0003אמר רב ירמיה בר אבא אמר רב: מבוי שנפרץ במלואו\u0004 כלומר, בכל ארכו של הכותל האמצעי \u0003לחצר\u0004, \u0003ו\u0004כן \u0003נפרצה חצר כנגדו\u0004 בצידה האחר אל רשות הרבים — \u0003חצר מותרת\u0004 בטלטול \u0003ומבוי אסור,\u0004 שהרי מבוי זה מפולש עתה משני צדדיו לרשות הרבים. \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 נאמר כך? שאם כפי שאמרנו, \u0003ליהוי\u0004 \u0005[שיהיה]\u0006 \u0003כמבוי שכלה לרחבה!\u0004 והרי אמרנו מדברי רב יהודה שמבוי כזה אינו צריך תיקון?!","\u0003אמר ליה: אנא לא ידענא\u0004 \u0005[אמר לו: אני איני יודע],\u0006 \u0003עובדא הוה בדורא דרעותא\u0004 \u0005[מעשה היה בכפר של רועים]\u0006 \u0003מבוי שכלה לרחבה הוה, ואתא לקמיה דרב יהודה ולא אצרכיה ולא מידי\u0004 \u0005[ובא\u0006 הדבר \u0005לפני רב יהודה ולא הצריכו דבר].\u0006 \u0003ואי קשיא\u0004 \u0005[ואם קשה]\u0006 לומר שאמר \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב — תיהוי משמיה\u0004 \u0005[שיהיה\u0006 שאמר \u0005משמו]\u0006 של \u0003שמואל, ולא קשיא מידי\u0004 \u0005[ולא קשה דבר],\u0006 שהרי רב יוסף לא שמע מפי רב יהודה מקור לדבריו בדברי רבותיו שלו, אלא פסק הלכה סתם, ויתכן מאד שפסק כדעת שמואל.","ומעירים כי \u0003השתא\u0004 \u0005[עכשיו]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ששת לרב שמואל בר אבא, ואמרי ליה\u0004 \u0005[ויש אומרים]\u0006 שאמר \u0003לרב יוסף בר אבא: אסברא\u0004 \u0005[אסביר]\u0006 \u0003לך\u0004 את דברי רב בענין מבוי שנפרץ לחצר, שיש בכך חילוקי דינים שונים; \u0003כאן,\u0004 שמתיר רב לטלטל במבוי ואינו חושש לפריצתו אל החצר — \u0003שעירבו\u0004 בני החצר עם בני המבוי והריהם כרשות אחת. \u0003כאן — שלא עירבו\u0004 בני החצר עם בני המבוי, ומעתה מתברר שיש במבוי דיירים חדשים (בני החצר) שלא עירבו והרי הם אוסרים על המבוי כולו. ואם כן הרי אפשר לומר שדברי רב יהודה בענין מבוי הכלה לרחבה היו על פי שיטת רב.","\u0003דרב אדרב נמי לא קשיא\u0004 \u0005[\u0006דברי \u0005רב על\u0006 דברי \u0005רב גם כן אינם קשים]\u0006 כי \u0003כאן\u0004 כשהתיר רב יהודה במבוי הכלה לרחבה — \u0003שעירבו בני חצר עם בני מבוי, כאן — שלא עירבו.\u0004"],["\u0003ולמאי דסליק אדעתין מעיקרא\u0004 \u0005[ול\u0006פי \u0005מה שעלה על דעתנו מתחילה)\u0006 ש\u0003בין שעירבו ובין שלא עירבו פליגי\u0004 \u0005[נחלקו]\u0006 רב ושמואל בדין מבוי שנפרץ לרחבה, יש להסביר \u0003ב\u0004מקרה ש\u0003עירבו במאי פליגי\u0004 \u0005[במה נחלקו]\u0006 ו\u0003בשלא עירבו במאי פליגי\u0004 \u0005[במה נחלקו],\u0006 כלומר באיזו בעיה עקרונית נחלקו בנושאים אלה?","ומסבירים: \u0003בשלא עירבו פליגי\u0004 \u0005[נחלקו]\u0006 \u0003ב\u0004דין מבוי ה\u0003נראה מבחוץ\u0004 סגור, כגון שמבחוץ יש מבוי או חצר רחבים מפתחו, ונראים כסוגרים עליו, \u0003ושוה מבפנים\u0004, שמצידו הפנימי אין רואים אותו שהוא סגור. אם מבוי כעין זה נחשב כסגור. שלדעת האומר שדינו כסגור, מותר לטלטל במבוי זה שכלה לרחבה.","ו\u0003ב\u0004מקרה ש\u0003עירבו קמיפלגי\u0004 \u0005[חולקים]\u0006 \u0003ב\u0004דברי \u0003רב יוסף\u0004. ש\u0003אמר רב יוסף: לא שנו\u0004 היתר זה במבוי שנפרץ בסופו וכלה לרחבה \u0003אלא שכלה לאמצע רחבה, וכשמביטים מצד הרחבה ניכר שהמבוי סגור. אבל כלה לצידי רחבה\u0004, שאז, שהמבוי והרחבה נראים כהמשך אחד — \u0003אסור\u0004. ונחלקו אם יש לקבל עקרון זה.","ומוסיף ו\u0003אמר רבה: הא דאמרת\u0004 \u0005[זה שאומר אתה]:\u0006 \u0003\"לאמצע רחבה מותר\", לא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא\u0004 כשנפרץ המבוי לרחבה, והרחבה לרשות הרבים, ואותן הפרצות הן \u0003זה שלא כנגד זה. אבל\u0004 אם נפרצו \u0003זה כנגד זה — אסור\u0004.","והוסיף ו\u0003אמר רב משרשיא: הא דאמרת\u0004 \u0005[זה שאומר אתה]:\u0006 \u0003\"זה שלא כנגד זה מותר\", לא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא\u0004 כשהיתה זו \u0003רחבה\u0004 של \u0003רבים\u0004. \u0003אבל\u0004 אם היתה ה\u0003רחבה\u0004 של \u0003יחיד, זימנין דמימלך עלה ובני לה\u0004 \u0005[פעמים שנמלך עליה ובונה בה]\u0006 \u0003בתים, והוי ליה\u0004 \u0005[והריהי נעשית]\u0006 \u0003כמבוי שכלה לה לצידי רחבה — ואסור\u0004. שהרי יתכן שעל ידי הבתים שייבנו תיסגר הרחבה מצד אחד, והמבוי יהא אז כלה לצדי רחבה, ולא לאמצעה. ומשום כך אף שהרחבה אינה בנויה עדיין, יש לעשות לה תיקון אחר, שלא יבואו הדברים לידי תקלה.","והוא מוסיף: \u0003ומנא תימרא דשני לן\u0004 \u0005[ומנין תאמר ששונה לנו]\u0006 מבחינת ההלכה \u0003בין רחבה\u0004 השייכת ל\u0003רבים לרחבה\u0004 השייכת ל\u0003יחיד\u0004 — ש\u0003אמר רבין בר רב אדא, אמר ר' יצחק: מעשה במבוי אחר שצידו אחד כלה לים, וצידו אחד כלה לאשפה,\u0004 ונמצא המבוי סגור משני צדדיו. \u0003ובא מעשה לפני רבי\u0004 לשאול אם אין די במחיצות אלה וצריך תיקון נוסף, או די בהם ואינו זקוק לתיקון, \u0003ולא אמר בה לא היתר ולא איסור\u0004.","ומבארים: \u0003איסור לא אמר בה — דהא קיימי\u0004 \u0005[שהרי עומדות]\u0006 \u0003מחיצות,\u0004 והמבוי סגור משני צדדים. ואף \u0003היתר לא אמר בה\u0004 — כי \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא תינטל אשפה\u0004 ממקומה ונמצא צד זה של המבוי פתוח, \u0003ו\u0004כן שמא \u0003יעלה הים שרטון,\u0004 וחולות השרטון יחצצו בין פתח המבוי לים ושוב לא יהא הים מחיצה למבוי.","וממשיכים לבאר את דברי רב משרשיא בדרך שאלה, \u0003ו\u0004לכאורה: \u0003מי חיישינן\u0004 \u0005[והאם חוששים אנו]\u0006 \u0003שמא תינטל אשפה? והתנן\u0004 \u0005[והרי שנינו]\u0006 במפורש במשנה: \u0003אשפה\u0004 שהיתה \u0003ברשות הרבים גבוה עשרה טפחים,\u0004 ולפיכך דינה של האשפה כרשות היחיד, והיה \u0003חלון על גבה\u0004 של האשפה, כלומר: חלון בבית הסמוך לה — \u0003זורקין לה בשבת\u0004 מן החלון. שהרי מותר לטלטל מרשות היחיד (הבית) לרשות היחיד (האשפה), ואין חוששים שמא יטול אדם את האשפה, ותתמעט האשפה מגובהה ולא תהיה עוד רשות היחיד, ויאסר עליו לזרוק. ויש כאן סתירה לכאורה, שבמקרים מסוימים חוששים אנו שמא תינטל אשפה ובמקרים אחרים אין חוששים לכך.","אלא יש להסיק מכאן: \u0003אלמא שני\u0004 \u0005[מכאן\u0006 ש\u0005שונה]\u0006 בין \u0003אשפה\u0004 של \u0003רבים לאשפה\u0004 של \u0003יחיד\u0004, שלגבי \u0003אשפה של יחיד אין לסמוך על היותה קבועה כיון שעשויה היא פעם להיפנות.\u0004","ואם כן נאמר, \u0003הכא נמי שני\u0004 \u0005[כאן גם כן שונה]\u0006 \u0003בין רחבה\u0004 של \u0003רבים\u0004 שאינה עשויה להיבנות, \u0003לרחבה\u0004 של \u0003יחיד\u0004 שיעלה בדעתו לשנות בה ולהוסיף בבנינה.","הביאו את המעשה ברבי, שלא רצה לפסוק במבוי שהיו בו אשפה וים משני צדדיו, ושואלים: \u0003ורבנן מאי\u0004 \u0005[וחכמים\u0006 בדורו של רבי \u0005מה\u0006 דעתם\u0005]\u0006 בהלכה זו? ממה שאמרו שרבי לא פסק בהלכה זו נראה שחכמי דורו לא סברו כמותו.","\u0003אמר רב יוסף בר אבדימי, תנא\u0004 \u0005[שנה\u0006 \u0003בתוספתא\u0004\u0005]:\u0006 \u0003וחכמים אוסרין. אמר רב נחמן: הלכה כדברי חכמים\u0004 אלה. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 לשון אחרת: \u0003אמר רב יוסף בר אבדימי תנא\u0004 \u0005[שנה]:\u0006 \u0003וחכמים מתירין, אמר רב נחמן: אין הלכה כדברי חכמים\u0004 אלה.","מסופר: \u0003מרימר פסיק לה לסורא באוזלי\u0004 \u0005[היה מפסיק את\u0006 ראשי מבואות \u0005סורא\u0006 המפולשים לים \u0005ברשתות]\u0006 שתשמשנה כמחיצה. \u0003אמר: חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא יעלה הים שרטון,\u0004 ולכן אין לסמוך על גדותיו שתשמשנה כמחיצות.","מסופר: \u0003ההוא\u0004 \u0005[אותו]\u0006 \u0003מבוי עקום דהוה\u0004 \u0005[שהיה]\u0006 \u0003בסורא, כרוך בודיא אותיבו ביה בעקמומיתיה\u0004 \u0005[כרכו מחצלת\u0006 ו\u0005שמו בו בעקמימותו]\u0006 שתשמש כעין לחי לתקנתו שמותר יהיה לטלטל בו. \u0003אמר רב חסדא: הא\u0004 \u0005[זה]\u0006 לא נעשה \u0003לא\u0004 כשיטת \u0003רב ולא כשמואל. לרב\u0004 ש\u0003אמר\u0004: מבוי עקום \u0003תורתו כמפולש\u0004, הרי מבוי כעין זה — \u0003צורת הפתח בעי\u0004 \u0005[צריך].\u0006 ואף \u0003לשמואל\u0004 ש\u0003אמר\u0004 שמבוי כזה \u0003תורתו כסתום — הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים כאשר העמיד \u0003לחי מעליא\u0004 \u0005[מעולה],\u0006 ועל ידי כך התיר את המבוי בלחי. \u0003אבל האי\u0004 \u0005[זה,\u0006 המחצלת\u0005],\u0006 \u0003כיון דנשיב ביה זיקא ושדי ליה\u0004 \u0005[שנושבת בה רוח וזורקת אותה]\u0006 — \u0003לא כלום הוא\u0004 ואינה מועילה.","ומעירים: \u0003ואי נעיץ ביה סיכתא וחבריה — חבריה\u0004 \u0005[ואם נעץ\u0006 במחצלת \u0005יתד וחיברה\u0006 לכותל \u0005—\u0006 \u0005חיברה]\u0006 והרי היא כלחי, \u0003ומועילה.\u0004","\u0003גופא\u0004 \u0005[ולגוף\u0006 הדברים\u0005]\u0006 \u0003חוזרים ומבררים: אמר רב ירמיה בר אבא\u0004 בשם \u0003רב: מבוי שנפרץ במלואו לחצר, ונפרצה חצר כנגדו\u0004 לרשות הרבים — \u0003חצר מותרת\u0004 בטלטול, \u0003ומבוי אסור.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה בר עולא לרב ביבי בר אביי: רבי\u0004, וכי \u0003לא משנתנו היא זו? \"חצר קטנה, שנפרצה לגדולה\u0004 — ה\u0003גדולה מותרת\u0004 בטלטול \u0003וקטנה אסורה, מפני שהיא כפתחה של גדולה\".\u0004 שכן, כשנפרץ כל אורך כותל החצר הקטנה עדיין נשארו משני צדדיה בחצר הגדולה שיירי הכתלים. ופירצת החצר הקטנה אם אינה רחבה מעשר אצבעות נראית כפתח בלבד, ואילו מבחינתה של החצר הקטנה אין לה מחיצה כלל. ודבר זה דומה ממש לדין המבוי שנפרץ במלואו לרחבה.","\u0003אמר ליה: אי מהתם הוה אמינא\u0004: \u0005[אמר לו: אם משם\u0006 בלבד \u0005הייתי אומר]\u0006 שיש לחלק במקרים; \u0003הני מילי — היכא דלא קא דרסי\u0004 \u0005[דברים אלה\u0006 אמורים \u0005במקום שאין דורסים]\u0006 \u0003בה רבים,\u0004 ואין הרבים עוברים בחצר הגדולה בשל פרצתה, ודינה כיחידה לעצמה. \u0003אבל היכא דקא דרסי\u0004 \u0005[במקום שדורסים]\u0006 \u0003בה רבים — אימא\u0004 \u0005[אומר]\u0006 \u0003אפילו חצר נמי\u0004 \u0005[גם כן]\u0006 אסורה משום דריסת הרגל של העוברים והשבים.","ומקשים: \u0003והא נמי תנינא\u0004 \u0005[והרי זו גם כן שנינו]\u0006 שאין דריסת הרגל מעכבת, ששנינו: \u0003חצר\u0004 שהיתה מוקפת מחיצות כדינה ש\u0003הרבים נכנסין לה\u0004 בכניסה \u0003זו ויוצאין לה בזו,\u0004 הרי דינה כ\u0003רשות הרבים\u0004 לענין \u0003טומאה,\u0004 וספק טומאה טהור בה, אולם עדיין \u0003רשות היחיד\u0004 היא \u0003ל\u0004ענין \u0003שבת\u0004, הרי שלענין שבת ניתנת תשומת הלב לדין המחיצות בלבד, והעובדה שהרבים עוברים שם אינה פוגמת בה מלהיות רשות היחיד.","ודוחים: \u0003אי מהתם הוה אמינא: הני מילי\u0004 \u0005[אם משם הייתי אומר: דברים אלה]\u0006 אמורים כשהיו הפרצות \u0003זה שלא כנגד זה\u0004."],["\u0003אבל זה כנגד זה, אימא\u0004 \u0005[אמור]\u0006 \u0003לא,\u0004 ואף לענין שבת אינה כרשות היחיד, על כן השמיע לנו שאף אם נפרצה החצר בפרצות שהן זו כנגד זו — בכל זאת היא מותרת.","ומקשים: \u0003ולרבה\u0004 ש\u0003אמר\u0004 שאם היה מבוי שכלה לרחבה והיו הפרצות \u0003זה כנגד זה אסור, הא\u0004 \u0005[\u0006דבר \u0005זה]\u0006 של \u0003רב במאי מוקי לה\u0004 \u0005[במה מעמיד\u0006 הוא \u0005אותו],\u0006 בודאי במקרה שהיו הפרצות \u0003זה שלא כנגד זה\u0004, ואם כן \u0003תרתי\u0004 \u0005[שתיים]\u0006 \u0003למה לי,\u0004 הלא עיקרה של הלכה זו כבר נאמר בתוספתא, ולשם מה צריך רב לומר הלכה נוספת באותו ענין עצמו?","ומסבירים שאף כאן יש חידוש: \u0003אי מהתם הוה אמינא: הני מילי\u0004 \u0005[אם משם,\u0006 מהתוספתא בלבד, \u0005הייתי אומר: דברים אלה]\u0006 שהחצר רשות היחיד לשבת הם לענין \u0003לזרוק.\u0004 שהזורק לחצר זאת מרשות הרבים מתחייב, שדינה מן התורה כרשות היחיד. \u0003אבל לטלטל\u0004 בה כברשות היחיד ממש — \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003לא.\u0004 ואסרו חכמים לטלטל בה, משום שרבים מצויים בה. ולכן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 רב שאין לחשוש לדבר, ומותרת החצר בטלטול, אף מדברי סופרים.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 \u0003מבוי העשוי כנדל\u0004, כלומר מבוי ארוך הפתוח לרשות הרבים, ובשני צידיו מבואות קטנים שאף הם פתוחים לרשות הרבים, מה דינו? \u0003אמר אביי: עושה צורת הפתח\u0004 למבוי ה\u0003גדול, והנך כולהו\u0004 \u0005[ואלה כולם]\u0006 המבואות הקטנים \u0003מישתרו\u0004 \u0005[מותרים]\u0006 \u0003בלחי וקורה\u0004.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: כמאן\u0004 \u0005[כמי]\u0006 אומר אתה הלכה זו, כשיטת \u0003שמואל,\u0004 ש\u0003אמר\u0004 שמבוי עקום \u0003תורתו כסתום.\u0004 ולכן גם מבוי זה העשוי כנדל, כל אחד ממבואותיו הקטנים בהתחברו אל המבוי הגדול הריהו כמבוי עקום. ואולם אם כך, שנוהגים כשמואל, \u0003למה ליה\u0004 \u0005[לו]\u0006 \u0003צורת הפתח?\u0004 הלא לדעת שמואל מותר מבוי כזה בלחי או קורה בלבד. \u0003ועוד, הא ההוא\u0004 \u0005[הרי אותו]\u0006 \u0003מבוי עקום דהוה\u0004 \u0005[שהיה]\u0006 \u0003בנהרדעא וחשו\u0004 \u0005[וחששו]\u0006 \u0003לה ל\u0004דברי \u0003רב.\u0004 ומשמע שיש לנהוג הלכה למעשה כרב ולא כשמואל!","\u0003אלא אמר רבא\u0004, כך יש לתקנו: \u0003עושה צורת הפתח לכולהו להאי גיסא\u0004 \u0005[לכולם\u0006 \u0003למבואות הקטנים\u0004 \u0005בצד זה]\u0006 צד אחד שלהם, \u0003ואידך גיסא מישתרו\u0004 \u0005[והצד האחר מותרים]\u0006 \u0003בלחי וקורה.\u0004","\u0003אמר רב כהנא בר תחליפא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב כהנא בר מניומי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב כהנא בר מלכיו משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב כהנא רביה\u0004 \u0005[רבו]\u0006 של \u0003רב, ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 \u0003רב כהנא בר מלכיו היינו\u0004 \u0005[זהו]\u0006 \u0003רב כהנא רביה דרב\u0004. וכך נמסרה הלכה: \u0003מבוי\u0004 הפונה לרשות הרבים \u0003שצידו אחד ארוך וצידו אחד קצר,\u0004 אם היה הבדל האורך שבין צד אחד לשני \u0003פחות מארבע אמות — מניח את הקורה באלכסון\u0004, על קצותיהם של שני כותלי המבוי. היה \u0003ארבע אמות\u0004 או יותר — \u0003אינו מניח את הקורה אלא כנגד\u0004 הצד \u0003הקצר\u0004, כלומר: מקצה הצד הקצר בקו ישר למקום המקביל בקיר הארוך, ואינו משתמש בחלק המבוי שמעבר לקורה. \u0003רבא אמר: אחד זה ואחד זה — אינו מניח את הקורה אלא כנגד הקצר.\u0004","והוסיף רבא: \u0003ואימא טעמא דידי, ואימא טעמא דידהו\u0004 \u0005[ואומר\u0006 את \u0005הטעם שלי ואומר\u0006 את \u0005הטעם שלהם\u0006 לשיטות השונות\u0005].\u0006 \u0003אימא טעמא דידי\u0004 \u0005[אומר\u0006 את \u0005הטעם שלי]:\u0006 \u0003קורה טעמא מאי\u0004 \u0005[מה טעמה]\u0006 — \u0003משום היכר,\u0004 שתיקנו חכמים שידעו בני המבוי שזה סוף התחום שמותר לטלטל בו, \u0003ובאלכסון לא הוי\u0004 \u0005[אינו]\u0006 \u0003היכר.\u0004 ואלה שיראו אנשים \u0003מטלטלים בחלק של הצד הארוך יחשבו שמותר בכלל לטלטל ברשות הרבים.\u0004","אף \u0003אימא טעמא דידהו\u0004 \u0005[אומר\u0006 את \u0005הטעם שלהם],\u0006 הם סבורים ש\u0003קורה משום מאי\u0004 \u0005[מה]\u0006 — \u0003משום מחיצה,\u0004 שהקורה נחשבת כיורדת ונמשכת עד למטה ויוצרת כעין כותל רביעי למבוי. ואם מחיצה היא \u0003באלכסון נמי הוי\u0004 \u0005[גם כן הריהי]\u0006 \u0003מחיצה.\u0004","\u0003אמר רב כהנא: הואיל ושמעתתא דכהני היא, אימא בה מילתא\u0004 \u0005[והלכה של \"כהנים\" היא, אומר בה דבר]\u0006 אף אני, ואוסיף להלכה זו שנמסרה על ידי חכמים ששמם רב כהנא. \u0003הא דאמרת\u0004 \u0005[זה שאומר אתה]\u0006 \u0003מניח הקורה באלכסון, לא אמרן\u0004 \u0005[לא אמרנו]\u0006 \u0003אלא שאין באלכסונו\u0004 זה \u0003יותר מעשר\u0004 אמות, \u0003אבל יש באלכסונו יותר מעשר\u0004, אף שרוחב המבוי עצמו פחות מעשר, \u0003דברי הכל אינו מניח אלא כנגד\u0004 הצד \u0003הקצר.\u0004 מפני שפתח הרחב מעשר אמות אינו ניתר על ידי קורה, והרי כאן כל השטח שמתחת הקורה הוא בחינת פתח.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003מהו להשתמש\u0004 ולטלטל בשטח המקביל אל \u0003תחת הקורה\u0004 בכל מבוי הניתר על ידי קורה? ונחלקו הדעות: \u0003רב ור' חייא ור' יוחנן אמרו: מותר להשתמש תחת הקורה. שמואל ור' שמעון בר רבי ור' שמעון בן לקיש אמרו: אסור להשתמש תחת הקורה\u0004.","ומציעים: \u0003לימא בהא קמיפלגי\u0004 \u0005[האם לומר ב\u0006דבר \u0005זה נחלקו],\u0006 \u0003דמר\u0004 \u0005[שחכם זה,\u0006 המתירים\u0005]\u0006 \u0003סבר: קורה משום היכר, ומר\u0004 \u0005[וחכם זה,\u0006 האוסרים\u0005]\u0006 \u0003סבר: קורה משום מחיצה.\u0004","ודוחים שאין זה הכרחי, \u0003לא, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003קורה משום היכר,\u0004 ואולם \u0003הכא בהא קמיפלגי\u0004 \u0005[כאן בזה נחלקו]:\u0006 \u0003דמר\u0004 \u0005[שחכם זה,\u0006 האוסרים\u0005]\u0006 \u0003סבר: היכרא\u0004 \u0005[ההיכר]\u0006 הוא בשביל אלה הנמצאים \u0003מלגיו\u0004 \u0005[בפנים],\u0006 ולכן אין להשתמש מחוץ לקצה הפנימי של הקורה. \u0003ומר סבר: היכרא מלבר\u0004 \u0005[וחכם זה\u0006 המתירים \u0005סבר: ההיכר מבחוץ]\u0006 לנמצאים ברשות הרבים, ולכן מותר לטלטל עד גבולה החיצוני של הקורה.","\u0003ואיבעית אימא: דכולי עלמא\u0004 \u0005[ואם תרצה אמור שהכל\u0006 סבורים שקורה מתירה\u0005]\u0006 \u0003משום מחיצה, והכא בהא קמיפלגי\u0004 \u0005[וכאן בזה נחלקו]\u0006 \u0003דמר\u0004 \u0005[שחכם זה,\u0006 האוסרים\u0005]\u0006 \u0003סבר: חודו הפנימי\u0004 של הקורה נחשב כ\u0003יורד וסותם,\u0004 ומה שמתחת לקורה אינו בתחום הסגור. \u0003ומר סבר\u0004 \u0005[וחכם זה\u0006 המתירים\u0005]:\u0006 \u0003חודו החיצון יורד וסותם,\u0004 ולכן מותר לטלטל גם תחת הקורה. ונמצא שאין לצרף מחלוקת זו בנוגע לדין שימוש תחת הקורה עם המחלוקת בדבר מהותה של הקורה.","ו\u0003אמר רב חסדא: הכל מודים ב\u0004מקום של \u0003בין לחיים\u0004, כלומר, כנגד הלחי ששמים להתיר את המבוי, \u0003שאסור\u0004, שהלחי דינו כמחיצה ואין משתמשים אלא עד צידו הפנימי ולא הלאה מכן.","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רמי בר חמא מרב חסדא\u0004: מה יהא הדין אם \u0003נעץ שתי יתדות בשני כותלי מבוי,\u0004 ורוחב היתידות הוא \u0003מבחוץ והניח קורה על גביהן\u0004 של היתדות, במקום על כותלי המבוי, והיא צמודה לפתח המבוי מבחוץ, \u0003מהו?\u0004 האם קורה זו מתירה או לא?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא: \u0003לדברי המתיר — אסור\u0004, שהמתיר בשימוש תחת הקורה סבור שצידה החיצון הוא החשוב, וצד חיצון זה הלא מצוי מחוץ למבוי ואינו יכול להתיר. ואילו \u0003לדברי האוסר\u0004 שימוש מתחת לקורה — \u0003מותר\u0004 לטלטל במבוי זה, שהרי קצהו הפנימי צמוד לפתח המבוי.","ואילו \u0003רבא אמר: לדברי האוסר, נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור\u0004 כי \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003קורה\u0004 המתירה שתהיה \u0003על גבי מבוי,\u0004 וכאן \u0003ליכא\u0004 \u0005[אין],\u0006 ואין קורה הסמוכה למבוי מתירה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב אדא בר מתנה לרבא\u0004 מן הברייתא: \u0003היתה קורתו\u0004"],["\u0003משוכה או תלויה,\u0004 אם היתה \u0003פחות משלשה\u0004 טפחים מן הכתלים — \u0003אין צריך להביא קורה אחרת,\u0004 שהיא נחשבת כצמודה להם מדין לבוד. \u0003שלשה\u0004 טפחים — \u0003צריך להביא קורה אחרת\u0004 להתיר את המבוי. ואילו \u0003רבן שמעון בן גמליאל\u0004 הסבור בכל מקום כי דין לבוד הוא עד ארבעה טפחים, \u0003אומר: פחות מארבעה — אין צריך להביא קורה אחרת, ארבעה — צריך להביא קורה אחרת\u0004.","ומדייקים: \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מה שאמרו — קורה \u0003משוכה\u0004 כוונתו שהיתה רחוקה מכתלי המבוי ומונחת \u0003מבחוץ, ותלויה\u0004 משמעה שהיתה הקורה מרוחקת מן הכתלים ו\u0003מבפנים!\u0004","ודוחים: \u0003לא, אידי ואידי\u0004 \u0005[זה וזה]\u0006 \u0003מבפנים\u0004. אלא: קורה \u0003משוכה\u0004 משמעה: שהיתה מרוחקת \u0003מרוח אחת\u0004 מן הכותל. וקורה \u0003תלויה\u0004 — שלא היתה כלל על כתלי המבוי ומרוחקת מהם \u0003משתי רוחות\u0004.","כי \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003מרוח\u0004 (מצד) \u0003אחת — אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003לבוד\u0004, וכאילו מושכים את הקורה אל הכותל, אולם \u0003משתי רוחות\u0004 — \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \u0003לבוד,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין הבדל בדבר זה.","\u0003רב אשי אמר\u0004: כאן מדובר בקורה \u0003משוכה והיא תלויה\u0004, \u0003והיכי דמי\u0004 \u0005[כיצד]\u0006? \u0003כגון שנעץ שתי יתידות עקומות על שני כותלי מבוי\u0004 מלמעלה, \u0003שאין בגובהן שלשה, ואין בעקמומיתן שלשה. מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003או \"לבוד\" אמרינן\u0004 \u0005[אנו אומרים],\u0006 שאנו מחשיבים את הקורה כאילו התארכה מן הצד. \u0003או \"חבוט\" אמרינן\u0004 \u0005[אנו אומרים],\u0006 שאנו מחשיבים את הקורה כאילו הורדה (נחבטה) למטה? ואולם גם \u0003לבוד\u0004 וגם \u0003חבוט\u0004 יחד \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים].\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 התנא שאף במקרה זה אומרים אנו שכל הסמוך לחבירו בפחות משלשה טפחים הריהו כצמוד אליו, בין מן הצד בין מלמטה, ואף לשני צדדים כאחת.","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' זכאי קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' יוחנן: בין לחיים ותחת הקורה — נידון ככרמלית\u0004, ואסור לטלטל בו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003פוק תני לברא\u0004 \u0005[צא\u0006 ו\u0005שנה בחוץ],\u0006 כלומר דברי ברייתא זו אינם כהלכה, ואין להכניסם ללימוד סדיר בבית המדרש.","\u0003אמר אביי: מסתברא מילתיה\u0004 \u0005[מסתבר דברו]\u0006 של \u0003ר' יוחנן תחת הקורה\u0004, שרק תחת הקורה דינו כרשות היחיד, \u0003אבל בין לחיין — אסור\u0004 כדברי ר' זכאי. \u0003ורבא אמר\u0004: כל דברי ר' זכאי דחויים, ו\u0003בין לחיים נמי\u0004 \u0005[גם כן]\u0006 \u0003מותר.\u0004","\u0003אמר רבא: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה,\u0006 את הלכתי זו\u0005]\u0006 — \u0003דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 משמו של \u0003ר' יוחנן: מקום\u0004 המיוחד לעצמו \u0003שאין בו\u0004 בשטחו \u0003ארבעה על ארבעה\u0004 טפחים המצוי בין רשות הרבים ורשות היחיד, אינו שייך אף לאחת מרשויות השבת והוא מקום פטור, ולכן \u0003מותר לבני רשות הרבים\u0004 וגם \u0003לבני רשות היחיד לכתף עליו\u0004 משאותיהם, \u0003ובלבד שלא יחליפו\u0004 ביניהם את החפצים. נמצא שמקום ששטחו פחות מארבעה טפחים, אינו נדון ככרמלית אלא כמקום פטור ומותר לטלטל בו, ולכן בין הלחיים דינו כמקום פטור.","\u0003ואביי\u0004 אומר שאין להוכיח מדבר זה, כי \u0003התם\u0004 \u0005[שם,\u0006 בדברי רב דימי\u0005]\u0006 מדובר \u0003בגבוה שלשה\u0004\u0005,\u0006 טפחים, ונבדל בכך מן הרשויות האחרות ולכן הוא כרשות לעצמה ודינו כמקום פטור.","\u0003אמר אביי מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה,\u0006 את הלכתי זו\u0005]\u0006 שבין לחיין דינו ככרמלית — \u0003שאמר רב חמא בר גוריא אמר רב: תוך הפתח\u0004, כלומר אותו מקום שבין מזוזות הפתח המשמשות כלחי, \u0003צריך לחי אחר להתירו,\u0004 ואין די במזוזות אלה להכשיר את המקום. הרי שבלי לחי אחר אסור בין הלחיין בטלטול.","\u0003וכי תימא: דאית ביה\u0004 \u0005[ואם תאמר שיש בו]\u0006 ברוחב הפתח \u0003ארבעה על ארבעה, והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב חנין בר רבא אמר רב: תוך הפתח, אף על פי שאין בו ארבעה על ארבעה — צריך לחי אחר להתירו.\u0004 משמע שאין להשתמש בבין הלחיים.","\u0003ורבא\u0004 עונה על כך שיש להבחין בין המקרים — \u0003התם\u0004 \u0005[שם]\u0006 מדובר שהיה אותו פתח \u0003פתוח לכרמלית,\u0004 ומשום כך נדון המקום שבין המזוזות אף הוא ככרמלית וצריך תיקון נוסף של לחי אחר.","ושואלים: \u0003אבל\u0004 אם הפתח פתוח \u0003לרשות הרבים מאי\u0004 \u0005[מה]\u0006 יהא דינו \u0005—\u0006 \u0003שרי\u0004 \u0005[מותר]?\u0006 ואם כן דין כרמלית חמור מדין רשות הרבים. והלא כרמלית היא גזירת חכמים בלבד, ורק משום שהיא דומה לרשות הרבים. והרי זה כעין \u0003יציבא בארעא וגיורא בשמי שמיא\u0004 \u0005[האזרח\u0006 מוטל \u0005בארץ והגר בשמי השמים]\u0006 מצב דברים הפוך מן הראוי!","ומעירים: בכל זאת כך הוא כי יש לומר \u0003מצא מין את מינו וניעור.\u0004 כלומר, כיון שמקום הפתח אינו מקום מסויים, ואין דינו כרשות גמורה ומסויימת, בטל הוא לגבי הכרמלית שאף היא רשות בדומה לו, והריהם נעשים כיחידה אחת, אף על פי שעל ידי כך אסורים בטלטול. ואולם רשות הרבים כיון שדינה שונה לחלוטין אין מקום הפתח בטל אליה ולכן אף מקום שבין הלחיים נחשב כחלק מן המבוי, ומותר בטלטול.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע לרבא: ואת לא תסברא\u0004 \u0005[ואתה אינך סבור]\u0006 ש\u0003בין לחיין אסור\u0004? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבה בר בר חנה אמר ר' יוחנן: מבוי שרצפו\u0004 (מילא אותו) \u0003בלחיין\u0004 הסמוכים זה לזה \u0003פחות פחות מארבעה\u0004 טפחים — \u0003באנו למחלוקת\u0004 של \u0003רבן שמעון בן גמליאל ורבנן\u0004 \u0005[וחכמים]\u0006 בענין שיעורו של לבוד;","לדעת \u0003רבן שמעון בן גמליאל\u0004 ש\u0003אמר\u0004: \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 בשיעור זה \u0003לבוד\u0004, הרי כל הלחיין הללו נחשבים כלחי אחד, ולכן \u0003משתמש עד חודו הפנימי של לחי הפנימי\u0004 ולא יותר. ואילו \u0003לרבנן, דאמרי: לא אמרינן\u0004 \u0005[לחכמים שאומרים: אין אנו אומרים]\u0006 \u0003לבוד\u0004 אלא בפחות משלשה טפחים, הרי הוא \u0003משתמש עד חודו\u0004 בחלקו \u0003הפנימי של\u0004 הלחי ה\u0003חיצון. אבל\u0004 מדבריהם נלמד שבכל אופן \u0003בין לחיין — דכולי עלמא\u0004 \u0005[שלדעת הכל]\u0006 \u0003אסור\u0004 להשתמש!","ואומרים: \u0003ורבא\u0004 עונה על כך כי \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 מדובר שהיה פתח זה \u0003פתוח לכרמלית\u0004.","ומקשים: \u0003אבל לרשות הרבים מאי\u0004 \u0005[מה\u0006 דינו\u0005] —\u0006 \u0003שרי\u0004 \u0005[\u0006האם \u0005מותר]?\u0006 אם כן נמצא \u0003יציבא בארעא וגיורא בשמי שמיא\u0004 \u0005[האזרח\u0006 מוטל \u0005בארץ והגר בשמי שמים]\u0006 ודוחים: \u0003אין\u0004 \u0005[כן\u0006 הוא\u0005],\u0006 ואין לתמוה, כי \u0003מצא מין את מינו וניעור\u0004."],["\u0003רב אשי אמר:\u0004 לדברי ר' יוחנן, בין לחיים כשר ולדבריו מחלוקת רבן שמעון בן גמליאל וחכמים היא \u0003כגון שרצפו בלחיים\u0004 המצויים ב\u0003פחות פחות מארבעה\u0004 טפחים זו מזו ו\u0003במשך\u0004 כלומר באורך \u0003ארבע אמות\u0004.","\u0003לרבן שמעון בן גמליאל\u0004 ש\u0003אמר\u0004 שבפחות מארבעה טפחים \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 דין \u0003לבוד, הוה ליה\u0004 \u0005[הריהו]\u0006 \u0003מבוי\u0004 לעצמו. שהרי כל זה נחשב כלחי אחד, \u0003וצריך לחי אחר להתירו\u0004. \u0003ו\u0004אילו \u0003לרבנן דאמרי: לא אמרינן\u0004 \u0005[לחכמים שאומרים: אין אנו אומרים]\u0006 בכגון זה \u0003לבוד — לא צריך לחי אחר להתירו\u0004.","ומקשים: \u0003ול\u0004שיטת \u0003רבן שמעון בן גמליאל\u0004 לשם מה דרוש לחי נוסף כדי להכשירו, \u0003להוי\u0004 \u0005[שיהיה]\u0006 \u0003כ\u0004אילו היה הלחי \u0003נראה מבחוץ ושוה מבפנים\u0004 שמותר בטלטול, שהרי מבחוץ רואים שלחי הוא זה ואינו חלק מן הבנין!","ועונים: \u0003מידי\u0004 \u0005[\u0006והרי \u0005הדבר]\u0006 \u0003הוא טעמא\u0004 \u0005[הטעם]\u0006 \u0003אלא לר' יוחנן הא כי אתא\u0004 \u0005[הרי כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל \u0003אמר\u0004 בשם \u0003ר' יוחנן\u0004: לחי ה\u0003נראה מבחוץ\u0004 כבולט \u0003ושוה מבפנים — אינו נידון משום לחי.\u0004","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שבבעיה \u0003זו דנו חכמים: נראה מבפנים\u0004 שהוא לחי, שהוא בולט מעובי הכותל \u0003ושוה מבחוץ — נידון משום לחי\u0004 לדעת הכל. אולם אם היה \u0003נראה מבחוץ\u0004 שהוא לחי \u0003ושוה מבפנים\u0004 נחלקו בכך \u0003ר' חייא ור' שמעון ברבי\u0004 (בנו של רבי יהודה הנשיא), \u0003חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: נידון משום לחי, וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר: אינו נידון משום לחי\u0004.","וכיון שלא נמסר מי מן החכמים אמר דבר אחד ומיהו בעל הדעה האחרת, רוצים לברר: \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 כי \u0003ר' חייא הוא\u0004 ש\u0003אמר \"נידון משום לחי\", דתני\u0004 \u0005[ש\u0006כן \u0005שנה]\u0006 \u0003ר' חייא: כותל שצידו אחד כנוס מחבירו, בין שנראה\u0004 השוני \u0003מבחוץ ושוה מבפנים, ובין שנראה\u0004 השוני \u0003מבפנים ושוה מבחוץ — נידון משום לחי,\u0004 ואם כן מצאנו שר' חייא הוא בעל דעה זו, ו\u0003תסתיים\u0004 \u0005[תוגדר]\u0006 בעייתנו בדבר זהותו של המתיר.","ומקשים: וכי ראיה היא זו? \u0003וכי ר' יוחנן\u0004 האומר שאינו נדון כלחי \u0003מי לא שמיע ליה הא\u0004 \u0005[האם לא שמע\u0006 זאת, את ההלכה \u0005הזו]?!\u0006 שהרי היתה התוספתא ידועה לרבים, \u0003אלא\u0004 ודאי \u0003שמיע ליה\u0004 \u0005[שמע אותה]\u0006 \u0003ולא סבר לה\u0004 \u0005[אותה],\u0006 אם כן אולי \u0003ר' חייא נמי\u0004 \u0005[גם כן]\u0006 \u0003לא סבר לה\u0004 \u0005[אותה],\u0006 ואף שהיא במשנתו של ר' חייא שמא הוא עצמו לא סבר כן!","את הקושיה הזו דוחים: \u0003האי מאי?!\u0004 \u0005[זה מהו]\u0006 כלומר; מה טיבה של קושיה זו?! \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ר' יוחנן לא סבר לה\u0004 \u0005[אותה] —\u0006 \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003לא תני לה\u0004 \u0005[שנה אותה]\u0006 ודעתו שאף שהיא מצויה כבר לפניו בתוספתא — אינה מחייבת להלכה, \u0003אלא ר' חייא — אי איתא דלא סבר לה, למה ליה למיתנא\u0004 \u0005[אם יש\u0006 אמת בכך \u0005שלא סבר אותה, למה לו לשנותה]?\u0006 ואם סבר שאינה כהלכה לא היה לו להכניסה בקובץ שהוא עצמו ערך. ואם שנאה, פירושו של דבר שאכן כך סבר.","\u0003אמר רבה בר רב הונא: נראה מבחוץ ושוה מבפנים — נידון משום לחי, אמר רבה: ומותבינן אשמעתין\u0004 \u0005[ומקשים אנו\u0006 עצמנו \u0005על ההלכה שלנו]\u0006 שאמרו חכמים: \u0003חצר קטנה שנפרצה לגדולה — גדולה מותרת וקטנה אסורה, מפני שהיא כפתחה של גדולה.\u0004 והרי בחצר הקטנה נפרץ צד אחד של הגדר בכל אורכה ואין ניכרת עוד כל מחיצה לחצר זו, ואילו מבחוץ מצד החצר הגדולה, כיון שנשארו שרידי הכותל בחצר הגדולה ניכר שיש כאן מחיצה. אולם \u0003ואם איתא\u0004 \u0005[ואם יש,\u0006 אם נקבל\u0005]\u0006 את ההנחה שנראה מבחוץ נחשב כמחיצה, אם כן \u0003קטנה נמי תשתרי\u0004 \u0005[גם כן תותר]\u0006 על ידי היות המחיצה שלה \u0003נראה מבחוץ\u0004 אף על פי ש\u0003שוה מבפנים.\u0004","\u0003אמר ר' זירא\u0004 שכאן מדובר במקרה מיוחד — \u0003בנכנסין כותלי קטנה לגדולה\u0004 כלומר; מחיצות החצר הקטנה לא היו בקו אחד עם כל מחיצתה של הגדולה, אלא החצר הקטנה נכנסת לתוך הגדולה ואף כשמסתכלים מצד החצר הגדולה רואים שאין שרידי מחיצת החצר הגדולה המשך אחד לפירצת החצר הקטנה.","ומקשים עוד: \u0003ולימא\u0004 \u0005[ושיאמר]\u0006 \u0003לבוד ותשתרי\u0004 \u0005[ותותר],\u0006 שמשום דין לבוד נחשוב כאילו נמתח כותל כלשהו בין הכתלים הבולטים מן החצר הקטנה אל מחיצות החצר הגדולה ויותרו משום לחי הנראה מבחוץ!","\u0003וכי תימא דמפלגי טובא\u0004 \u0005[ואם תאמר שהם מופלגים,\u0006 רחוקים \u0005ביותר]\u0006 שיש מרחק גדול בין מחיצות החצר ובין ראשי מחיצות החצר הקטנה יותר מכדי שאפשר לומר לבוד? \u0003והא תני\u0004 \u0005[והרי שנה]\u0006 \u0003רב אדא בי אבימי קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' חנינא:\u0004 חצר \u0003קטנה\u0004 שאמרו, אפילו \u0003בעשר\u0004 אמות. \u0003גדולה,\u0004 משמעה אף \u0003באחת עשרה\u0004 אמות! אם כן דין זה קיים גם כאשר ההבדל שבין החצרות הוא אמה אחת שהיא ששה טפחים בלבד, ואם נחלקים לשני צדי פירצת החצר הקטנה נמצא שיש רק שלשה טפחים עד למחיצה הגדולה, ובכגון זה ודאי קיים דין לבוד.","\u0003אמר רבינא\u0004 שיש לומר \u0003ב\u0004מקרה זה: שהיו \u0003מופלגין\u0004 כותלי הקטנה \u0003מכותל זה בשנים\u0004 (שני טפחים) \u0003ומכותל זה בארבעה\u0004 טפחים ולכך אין כאן דין לבוד, ומקשים: ועדיין","\u0003ולימא\u0004 \u0005[ושיאמר]\u0006 \u0003לבוד מרוח אחת\u0004 (מצד אחד), \u0003ותשתרי\u0004 \u0005[ושתותר]\u0006 החצר. שאם מצד אחד המרחק פחות משלשה טפחים, נאמר בצד זה לבוד, ותעשה כעין לחי מבחוץ מצד אחד ותתיר את החצר."],["\u0003רבי היא\u0004 ש\u0003אמר: בעינן\u0004: \u0005[צריכים אנו]\u0006 כדי להתיר בטלטול את החצר שנפרצה \u0003שני פסין\u0004 משני צידי הפירצה. \u0003דתניא\u0004 \u0005[שכן שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חצר\u0004 שנפרצה לרשות הרבים, ואין ברוחב הפירצה עשר אמות, \u0003ניתרת\u0004 אם נשאר \u0003פס אחד\u0004 מאורך הכותל, \u0003רבי אומר: בשני פסין\u0004.","את כל ההסבר הזה דוחים: \u0003האי מאי\u0004 \u0005[\u0006תירוץ \u0005זה מהו]?\u0006 \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]:\u0006 \u0003נראה מבחוץ ושוה מבפנים — אינו נידון משום לחי,\u0004 ותאמר כי \u0003רבי סבר לה\u0004 \u0005[אותה\u0006 שיטה\u0005]\u0006 \u0003כר' יוסי\u0004 שהשיעור המינימלי של לחי או של פס בחצר צריך להיות לפחות שלושה טפחים, \u0003ודר' זירא ודרבינא ליתא\u0004 \u0005[אינם]\u0006 כלומר, אין אנו מקבלים את הסבריהם בפירוש המשנה — \u0003משום הכי\u0004 \u0005[כך]:\u0006 יש טעם לחדש ולומר כי החצר ה\u0003קטנה בעשר\u0004 אמות, \u0003גדולה באחת עשרה, משום דרבי סבר לה כר' יוסי\u0004 ולדעת ר' יוסי אין לחי מתירה בפחות משלושה טפחים, ולכן צריכים שני הפסים יחד להיות בני ששה טפחים, שהם אמה אחת, והיא ההפרש המינימלי בין החצרות.","\u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]:\u0006 ש\u0003נראה מבחוץ ושוה מבפנים — נידון משום לחי, ו\u0004שיטת \u0003ר' זירא ורבינא איתא\u0004 \u0005[ישנה,\u0006 קיימת בהלכה\u0005]\u0006 \u0003ורבי לא סבר לה\u0004 \u0005[אותה\u0006 שיטה\u0005]\u0006 \u0003כר' יוסי\u0004, אם כן \u0003גדולה באחת עשרה למה לי\u0004 להשמיענו שהיה זה שיעורה?","הלא \u0003ממה נפשך\u0004 \u0005[איך שתרצה לומר]:\u0006 \u0003אי למשרייה לגדולה קאתי\u0004 \u0005[אם\u0006 לחדש \u0005ולהתיר\u0006 את החצר \u0005הגדולה בא]\u0006 הלא \u0003בעשר ושני טפחים סגיא\u0004 \u0005[מספיק].\u0006 שאם החצר הגדולה בת עשר אמות ושני טפחים, די בטפחים אלה להחשב כפסים המתירים את החצר. \u0003ואי למיסרה לקטנה קאתי\u0004 \u0005[ואם\u0006 לחדש לגבי רבי ו\u0005לאסור\u0006 את החצר \u0005הקטנה בא]\u0006 \u0003לאשמועינן דמפלגי טובא\u0004 \u0005[שישמיע לנו\u0006 אפילו כשהם \u0005מופלגים הרבה]\u0006 ולאו דווקא הפרש של אמה אחת. ובוודאי אין מקום לפירוש זה.","\u0003אלא לאו שמע מינה\u0004 \u0005[האם לא נלמד מכאן]\u0006 כי \u0003נראה מבחוץ ושוה מבפנים — אינו נידון משום לחי?\u0004 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן].\u0006","\u0003אמר רב יוסף: לא שמיע לי הא שמעתתא\u0004 \u0005[לא שמעתי הלכה זו].\u0006 רב יוסף חלה ונשכח ממנו תלמודו ולא זכר הלכה זו שלחי הנראה מבחוץ נחשב כלחי.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 תלמידו: אף \u0003את אמרת ניהלן, ואהא אמרת ניהלן\u0004 \u0005[אתה אמרת לנו\u0006 הלכה זו, \u0005ועל\u0006 דבר \u0005זה אמרת לנו]\u0006 ש\u0003אמר רמי בר אבא אמר רב הונא: לחי המושך עם דפנו של מבוי,\u0004 שהלחי ממשיך באורך את כותל המבוי הלאה, ושוה מבפנים ונראה מבחוץ, שאין עוביו כעובי כותל המבוי, אם היה אותו לחי \u0003פחות מארבע אמות — נידון משום לחי, ומשתמש\u0004 במבוי \u0003עם חודו הפנימי\u0004, של הלחי. היה הלחי עצמו מושך \u0003ארבע אמות — נידון משום מבוי, ואסור להשתמש בכולו\u0004 בכל המבוי, שהרי אין לו לחי.","\u0003ואת אמרת לן עלה\u0004 \u0005[ואתה אמרת לנו על כך]:\u0006 \u0003שמע מינה תלת\u0004 \u0005[למד ממנה\u0006 מאימרה זו \u0005שלש\u0006 הלכות בדיני עירובין] \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003בין לחיין אסור\u0004 להשתמש, שכן משתמש רק עד חודו הפנימי. \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 כי \u0003משך\u0004 (אורכו) של \u0003מבוי בארבע\u0004 אמות, \u0003ושמע מינה: נראה מבחוץ ושוה מבפנים — נידון משום לחי.\u0004","ומסכמים: \u0003והלכתא\u0004 \u0005[הלכה]\u0006 למעשה: \u0003נראה מבחוץ ושוה מבפנים — נידון משום לחי\u0004. ותוהים: \u0003תיובתא והלכתא\u0004 \u0005[קושיה ו\u0006גם \u0005הלכה]\u0006 שהרי קודם דחינו סברה זו בקושיה, וכיצד אפשר לפסוק הלכה כשיטה זו?","ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003משום דתני\u0004 \u0005[ששנה]\u0006 \u0003ר' חייא כוותיה\u0004 \u0005[כמותו].\u0006 ואף שדייקנו מדברי תנאים שונים והגענו למסקנות אחרות, מכל מקום סומכים אנו על דבריו המפורשים של ר' חייא.","במשנה למדנו כי פתח \u0003הרחב מעשר\u0004 אמות \u0003ימעט. אמר אביי: תנא\u0004 \u0005[שנה\u0006 החכם בתוספתא\u0005]:\u0006 \u0003הרחב מעשר ימעט, ר' יהודה אומר: אינו צריך למעט\u0004. ונתעוררה השאלה: \u0003ועד כמה\u0004 התיר ר' יהודה ברוחב פתח המבוי?","\u0003סבר רב אחי קמיה\u0004 \u0005[לפני]\u0006 \u0003רב יוסף למימר\u0004 \u0005[לומר]:\u0006 \u0003עד שלש עשרה אמה ושליש\u0004. וכיצד למד שיעור זה? מ\u0003קל וחומר מפסי ביראות\u0004, שמבואר להלן שלשיטת ר' יהודה אפשר לעשות מסביב לבארות (ביראות) פסים רחוקים זה מזה שלש עשרה אמה ושליש ועל ידי הפסים מחשיבים את השטח שמסביב לבאר כרשות היחיד.","וכך הוא דן: \u0003ומה פסי ביראות שהתרתה בהן\u0004 את הטלטול אף שהם יוצרים מחיצה שבה ה\u0003פרוץ מרובה על העומד\u0004 ובכל זאת — \u0003לא התרתה בהן יותר משלש עשרה אמה ושליש, מבוי שלא התרתה בו פרוץ מרובה על העומד — אינו דין שלא תתיר בו יותר משלש עשרה אמה ושליש?\u0004","ואולם אפשר לדחות, \u0003והיא הנותנת\u0004, מאותו טעם עצמו אפשר להסיק מסקנה הפוכה: — \u0003פסי ביראות שהתרתה בהן פרוץ מרובה על העומד — לא\u0004 תוסיף ו\u0003תתיר בהן יותר משלש עשרה אמה ושליש,\u0004 ואילו \u0003מבוי שלא התרתה בו פרוץ מרובה על העומד\u0004 — והחמרת עליו מצד זה, אם כן כשרובו עומד \u0003תתיר בו\u0004 אף \u0003יותר משלש עשרה אמות ושליש!\u0004","\u0003אי נמי לאידך גיסא\u0004 \u0005[או גם כן לצד אחר]\u0006 אפשר לטעון, שיש להחמיר במבוי, שכן \u0003פסי ביראות דאקילת בהו חד קולא\u0004 \u0005[שהקלת בהם הקלה אחת] —\u0006 \u0003אקיל בהו קולא אחרינא\u0004 \u0005[הקל בהם הקלה אחרת]\u0006 שעד שלש עשרה אמה ושליש נחשב עדיין כפתח, \u0003מבוי — כלל כלל לא\u0004 תקל, ואין איפוא לדעת עד כמה מתיר ר' יהודה ברוחב פתח מבוי.","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003לוי\u0004 בדיני מיעוט מבוי כדי להכשירו: \u0003מבוי שהוא רחב עשרים אמה, נועץ קנה באמצעיתו.\u0004 ועל ידי כך מחלקו לשני מבואות שיש ברוחב כל אחד מהם רק עשר אמות, \u0003ודיו\u0004 בתיקון זה. \u0003הוא תני לה\u0004 \u0005[שנה אותה,\u0006 את הברייתא הזאת\u0005]\u0006 \u0003והוא אמר לה\u0004: ש\u0003אין הלכה כאותה משנה\u0004, ואין די בכך. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים],\u0006 \u0003אמר שמואל משמיה\u0004 \u0005[משמו]\u0006 של \u0003לוי: אין הלכה כאותה משנה\u0004.","ושואלים: \u0003אלא היכי עביד\u0004 \u0005[כיצד עושה]\u0006 כדי להכשירו? \u0003אמר שמואל\u0004 בשם \u0003לוי\u0004:"],["\u0003עושה פס גבוה עשרה\u0004 טפחים באמצעיתו \u0003במשך\u0004 (באורך) \u0003ארבע אמות, ומעמידו לארכו של מבוי.\u0004 ועל ידי כך נוצרים בראש המבוי כעין שני מבואות קטנים שאין רוחב של אחד מהם יותר מעשר אמות.","ו\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 יעשה כדברי \u0003ר' יהודה\u0004 ש\u0003אמר רב יהודה: מבוי שהוא רחב חמש עשרה אמה\u0004 כיצד ממעטו? — \u0003מרחיק שתי אמות\u0004 מהכותל \u0003ועושה פס\u0004 שרוחבו \u0003שלש אמות\u0004. ונמצא שהמקום שנותר הוא עשר אמות בלבד.","ושואלים: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 צריך לתיקון זה דווקא? \u0003יעשה פס אמה ומחצה, וירחיק שתי אמות, ויעשה פס\u0004 נוסף של \u0003אמה ומחצה\u0004 ואף אז ישאר רוחב המבוי עשר אמות. \u0003שמע מינה\u0004 \u0005[\u0006האם לא \u0005נלמד מכאן]\u0006 ממה שלא אמר רב יהודה לעשות בדרך זו כי \u0003עומד מרובה על הפרוץ משתי רוחות — לא הוי עומד!\u0004 כלומר אף על פי שהעומד (שהוא יחד שלש אמות של פסים) מרובה כאן על הפרוץ (שתי אמות באמצע) כיון שהוא מצטרף משני לוחות, ובכל צד שיעורו של העומד פחות משיעורו של המקום הפרוץ ואין זה מועיל להחשב כעומד מרובה.","ודוחים: \u0003לעולם אימא\u0004 \u0005[לעולם\u0006 ברגיל כעין זה \u0005אומר]\u0006 \u0003לך הוי\u0004 \u0005[הריהו\u0006 חשוב\u0005]\u0006 כ\u0003עומד\u0004 מרובה, \u0003ושאני הכא, דאתי אוירא דהאי גיסא ואוירא דהאי גיסא, ומבטל ליה\u0004 \u0005[ושונה כאן, שבא אויר,\u0006 החלל \u0005שמצד זה והאויר של\u0006 הפתח הגדול \u0005שמצד זה, ומבטל אותו]\u0006 שהפס הבודד שלאחר החלל אינו מועיל משום שיש משני צידיו חלל פנוי.","ושואלים: \u0003ויעשה פס אמה וירחיק אמה, ויעשה פס אמה וירחיק אמה, ויעשה\u0004 שוב \u0003פס אמה,\u0004 ואז אין החלל מרובה על העומד מכל צד של הפס. וכיון שלא נתן עצה זו, \u0003שמע מינה\u0004 \u0005[\u0006האם לא \u0005נלמד מכאן]\u0006 כי אם היה ה\u0003עומד כפרוץ\u0004 ולא יתר מכן — \u0003אסור!\u0004","ודוחים: \u0003לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 — \u0003מותר, ושאני הכא דאתא אוירא דהאי גיסא ודהאי גיסא\u0004 \u0005[ושונה כאן שבא האויר שמצד זה ומצד זה]\u0006 \u0003ומבטל ליה\u0004 \u0005[אותו].\u0006","ומציעים: \u0003וירחיק אמה\u0004 מן הכותל \u0003ויעשה פס אמה ומחצה, וירחיק\u0004 עוד \u0003אמה ויעשה\u0004 עוד \u0003פס אמה ומחצה\u0004, ועל ידי כך ימעט את רוחב המבוי עד לעשר אמות.","ועונים: \u0003אין הכי נמי, וכולי האי לא אטרחוה רבנן\u0004 \u0005[כן, כך הוא גם כן, וכל כך לא הטריחוהו חכמים]\u0006 לעשות שני פסים כאשר יכול הוא לעשות פס אחד בלבד.","ושואלים: \u0003וליחוש דלמא שביק פיתחא רבה, ועייל בפתחא זוטא\u0004 \u0005[ויחשוש שמא יניח את הפתח הגדול\u0006 שרוחבו עשר אמות \u0005ויכנס בפתח הקטן]\u0006 שרוחבו שתי אמות! \u0003אמר רב אדא בר מתנה: חזקה\u0004 היא \u0003אין אדם מניח פתח גדול ונכנס בפתח קטן\u0004.","ומקשים: \u0003ומאי שנא\u0004 \u0005[במה שונה\u0006 הדבר\u0005]\u0006 מהלכה זו \u0003דר' אמי ודר' אסי\u0004 בענין מבוי שנפרץ מראשו, שאם הפירצה גדולה כדי שאפשר יהיה להיכנס בה — פוסלת היא את המבוי, הרי גם שם אפשר לומר שפירצה זו לא תיחשב, כיון שאין אנשים מניחים פתח גדול ונכנסים בפתח קטן!","ועונים: \u0003התם קא ממעט בהילוכא\u0004 \u0005[שם הוא ממעט בהילוך].\u0006 שאם בא מצידו של המבוי ולא מראשו, יקצר את דרכו, ולשם כך נכנס אף בפתח קטן. אבל \u0003הכא — לא קא ממעט בהילוכא\u0004 \u0005[כאן הוא אינו ממעט בהילוך]\u0006 לפי ששני הפתחים מצויים באותו צד.","\u0003תנן התם\u0004 \u0005[שנינו שם]:\u0006 \u0003עור העסלא וחלל\u0004 הנקב \u0003שלו — מצטרפין\u0004 יחד לכדי שיעור \u0003טפח\u0004 לענין אוהל המת. שאם האהילה העסלא עם החלל שבה על כזית מן המת, כל מה שמצוי מתחת לה נטמא.","בתחילה שואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"עור העסלא\"? אמר רבה בר בר חנה אמר ר' יוחנן: עור כיסוי של בית הכסא\u0004.","ועתה שואלים: \u0003וכמה\u0004, מהו השיעור של החלל הסגור שבשלו יחשב כל העור על החלל שבו כסתום? \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר\u0004 שהשיעור הוא \u0003אצבעיים מכאן ואצבעיים מכאן, ואצבעיים ריוח\u0004 של החלל \u0003באמצע\u0004. ואילו \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין אמר: אצבע ומחצה מכאן, ואצבע ומחצה מכאן, ואצבע ריוח באמצע\u0004.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אביי לרב דימי: מי פליגיתו?\u0004 \u0005[האם חלוקים אתם\u0006 אתה ורבין בעקרון\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא\u0004, אלא \u0003הא\u0004 \u0005[זה]\u0006 שאמר הוא — \u0003ברברבתא\u0004 \u0005[ב\u0006אצבעות \u0005גדולות],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרתי — \u0003בזוטרתא\u0004 \u0005[ב\u0006אצבעות \u0005קטנות],\u0006 \u0003ולא פליגין\u0004 \u0005[ואיננו חולקים].\u0006 ושנינו מתכוונים לעסלא שרוחבה טפח, ואין בינינו אלא הבדל קביעת השיעור באצבעות אם קטנות או גדולות.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003לאיי\u0004 \u0005[לא כן],\u0006 אלא \u0003פליגיתו\u0004 \u0005[חלוקים אתם],\u0006 \u0003וב\u0004דין \u0003עומד מרובה על הפרוץ משתי רוחות פליגיתו\u0004 \u0005[חלוקים אתם];\u0006 \u0003לדידך\u0004 \u0005[לשיטתך]\u0006 \u0003הוי\u0004 \u0005[הריהו]\u0006 נחשב \u0003עומד\u0004 אף אם הוא מצטרף \u0003משתי רוחות,\u0004 ו\u0003לרבין\u0004 אם העומד מרובה \u0003מרוח אחת\u0004 — \u0003הוי\u0004 \u0005[הריהו]\u0006 נחשב \u0003עומד, משתי רוחות\u0004 — \u0003לא הוי\u0004 \u0005[אינו]\u0006 נחשב \u0003עומד.\u0004","\u0003דאי סלקא דעתך לא פליגיתו\u0004 \u0005[שאם עולה על דעתך\u0006 לומר ש\u0005אין אתם חלוקים]\u0006 אלא רק קוראים לאותו שיעור שמות שונים, \u0003לרבין הכי איבעי ליה למימר\u0004: \u0005[כך היה הוא צריך לומר]:\u0006 \u0003אצבע ושליש מכאן, ואצבע ושליש מכאן ואצבע ושליש ריוח באמצע\u0004 ואם הקטין את שיעור החלל מן היחס הקבוע הזה משמע שהוא חולק על דברי רב דימי חילוק יסודי.","אמר לו רב דימי: \u0003ואלא מאי\u0004 \u0005[מה]\u0006 רוצה אתה לומר— \u0003פליגינן\u0004 \u0005[חולקים אנו]\u0006 אם כן\u0003, לדידי\u0004 \u0005[לי]\u0006 לשיטתי שאתה מייחס לי \u0003הכי איבעי לי למימר\u0004 \u0005[כך הייתי צריך לומר]:\u0006 \u0003אצבע ושני שלישים מכאן, ואצבע ושני שלישים מכאן, ואצבעיים ושני שלישים ריוח באמצע\u0004 כדי להביא דוגמה מודגשת יותר שאף על פי שהפרוץ מרובה בהרבה על העומד שמצד אחד, אולם כיון שמצטרפים שני הצדדים יחד הרי נעשה העומד מרובה על הפרוץ ונחשב כסתום.","\u0003אלא אי איכא למימר דפלגינן\u0004 \u0005[אם יש\u0006 מקום \u0005לומר שאנו חולקים] —\u0006 הרי אנו חולקים בפרט אחר, \u0003בפרוץ כעומד פלגינן\u0004 \u0005[חולקים אנו],\u0006 שהיה הפרוץ בדיוק כשיעור העומד, ובזה נחלקו שרבין אומר שדינו כפרוץ, ורב דימי אומר שדינו כעומד.","במשנה שנינו ש\u0003אם יש לו צורת הפתח, אף על פי שרחב מעשר\u0004 אמות \u0003אינו צריך למעט.\u0004 ומעירים: \u0003אשכחן\u0004 \u0005[מוצאים אנו]\u0006 ב\u0003צורת הפתח דמהניא\u0004 \u0005[ש\u0006היא \u0005מועילה]\u0006 להיתרו של המבוי \u0003ברחבו, ואמלתרא דמהניא\u0004 \u0005[ש\u0006היא \u0005מועילה]\u0006 \u0003בגבהו.\u0004 שעל ידי תיקונים אלה נעשה המבוי ראוי לטלטל בו, אף שהוא גדול מן השיעור שקבעו לו חכמים."],["\u0003איפכא מאי\u0004 \u0005[ההיפך מהו]?\u0006 כלומר, האם מועילה צורת הפתח להתיר אף מבוי גבוה מעשרים אמה?","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא ושמע\u0006 תשובה\u0005]\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו]\u0006 בברייתא: \u0003מבוי שהוא גבוה מעשרים אמה — ימעט\u0004 גובהו, \u0003ואם יש לו צורת הפתח — אינו צריך למעט\u0004.","ושואלים: \u0003אמלתרא ברחבו מאי\u0004 \u0005[מה],\u0006 האם מועילה היא? ורוצים לפתור את הבעיה, \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 תשובה, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מבוי שהוא גבוה מעשרים אמה — ימעט, והרחב מעשר — ימעט, ואם יש לו צורת הפתח — אינו צריך למעט, ואם יש לו אמלתרא — אינו צריך למעט.\u0004","\u0003מאי לאו אסיפא\u0004 \u0005[האם לא על הסוף]\u0006 כלומר, מה שנאמר בדבר אמלתרא מתייחס לענין מבוי הרחב מעשר. והרי ראיה שאמלתרא מועילה לתיקון רוחב המבוי ודוחים: \u0003לא, ארישא\u0004 \u0005[על ראש\u0006 הברייתא\u0005]\u0006 שאמלתרא מועילה למבוי הגבוה מעשרים, אבל על הרחב מעשר לא שמענו.","באותו ענין \u0003מתני ליה\u0004 \u0005[היה משנן לו\u0006 מלמדו\u0005]\u0006 \u0003רב יהודה לחייא בר רב קמיה\u0004 \u0005[לפני]\u0006 \u0003רב:\u0004 פתח הרחב מעשרה שעשה לו צורת הפתח \u0003אינו צריך למעט\u0004. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אתנייה\u0004 \u0005[השנה לו]:\u0006 \u0003צריך למעט\u0004 וזו היא הגירסה בהלכה.","\u0003אמר רב יוסף: מדברי רבינו\u0004, רב, שאמר שאף בצורת הפתח צריך למעט, \u0003נלמד: חצר שרובה\u0004 כלומר רוב מחיצותיה \u0003פתחים וחלונות — אינה ניתרת בצורת הפתח.\u0004 שאף שיש לפתחים שבה צורת פתח, אין היא מועילה להחשיב מקום שרובו פרוץ כאילו היה סגור.","\u0003מאי טעמא\u0004 \u0005[מה טעם] —\u0006 \u0003הואיל ויותר מעשר אוסר במבוי, ו\u0004כן גם \u0003פרוץ מרובה על העומד אוסר בחצר. מה\u0004 (כשם) ש\u0003יותר מעשר\u0004 אמות \u0003האוסר במבוי — אינו ניתר בצורת הפתח\u0004 לדעת רב; \u0003אף פרוץ מרובה על העומד, האוסר בחצר — אינו ניתר בצורת הפתח.\u0004","את ההוכחה הזו מפריכים בטענה שאין מקום להשוואה, כי, \u0003מה ליותר מעשר האוסר במבוי — שכן\u0004 פירצה בגודל כזה \u0003לא התרת בו\u0004 אף \u0003אצל פסי ביראות ל\u0004שיטת \u0003ר' מאיר\u0004 (להלן עירובין יז, ב), \u0003תאמר בפרוץ מרובה על העומד\u0004 שאף שהוא \u0003אוסר בחצר\u0004 אינו חמור כל כך, \u0003שכן התרת אצל פסי ביראות לדברי הכל\u0004 בפרוץ מרובה על העומד, ואם כן אין להשוות יותר מעשר לפרוץ מרובה.","ומציעים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 ש\u0003מסייע ליה\u0004 \u0005[לו]\u0006 לשיטה זו שצורת הפתח אינה מועילה בפרוץ מרובה על העומד ממה ששנינו: \u0003דפנות הללו שרובן פתחים וחלונות — מותר, ובלבד שיהא עומד מרובה על הפרוץ\u0004.","ומתחילה תוהים על לשון הברייתא: \u0003ש'רובן' סלקא דעתך\u0004 \u0005[עולה על דעתך]?\u0006 הרי אם רובן פתחים וחלונות — ממילא אין העומד מרובה על הפרוץ! \u0003אלא אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]:\u0006 \u0003שריבה בהם פתחים וחלונות, ובלבד שיהא עומד מרובה על הפרוץ\u0004. נמצא שפרוץ מרובה על העומד אינו ניתר אף על ידי צורת הפתח.","\u0003אמר רב כהנא\u0004: אין זו ראיה גמורה, \u0003כי תניא ההיא\u0004 \u0005[כאשר שנינו זאת] —\u0006 \u0003בפיתחי שימאי\u0004 \u0005[בפתחים בלתי מתוקנים\u0006 שאין בהם צורת פתח\u0005].\u0006","ושואלים: \u0003מאי פתחי שימאי\u0004 \u0005[מה הם פתחים בלתי מתוקנים\u0006 אלה\u0005]?\u0006 \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה רב רחומי ורב יוסף; חד\u0004 \u0005[אחד]\u0006 \u0003אמר: דלית להו שקפי\u0004 \u0005[שאין להם מזוזות],\u0006 \u0003וחד\u0004 \u0005[ואחד]\u0006 \u0003אמר דלית להו\u0004 \u0005[שאין להם]\u0006 \u0003תיקרה\u0004 מעל הפתח.","ומעירים: \u0003ואף ר' יוחנן סבר לה להא\u0004 \u0005[\u0006להלכה \u0005זו]\u0006 של \u0003רב\u0004 שצורת הפתח אינה מתירה ברחב יותר מעשר אמות. ש\u0003אמר רבין בר רב אדא אמר ר' יצחק: מעשה באדם אחד מבקעת בית חורתן שנעץ ארבעה קונדיסין\u0004 (מוטות) \u0003בארבע פינות השדה, ומתח זמורה עליהן\u0004 ונוצרו איפוא ארבע צורות פתח, ורצה אותו אדם שייחשב המקום הזה כמקום סגור וגדור, ויהא מותר לו לנטוע כרם בסמוך להם ולא יעבור משום כלאי הכרם. \u0003ובא מעשה לפני חכמים, והתירו לו לענין כלאים,\u0004","\u0003ואמר ריש לקיש: כדרך שהתירו לו לענין כלאים — כך התירו לו לענין שבת\u0004 שמקום המוקף מחיצה מעין זו נחשב כסגור, ומותר בטלטול. \u0003ר' יוחנן אמר: לכלאים — התירו לו, לענין שבת — לא התירו לו\u0004.","ובאים מעתה לברר: \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהניח את הזמורות על גבי הקונדסים \u0003מן הצד,\u0004 ולא על ראשיהם, ויש לפקפק בצורת פתח זו, \u0003והאמר\u0004 \u0005[והרי\u0006 כבר \u0005אמר]\u0006 \u0003רב חסדא\u0004 לענין שבת: \u0003צורת הפתח שעשאה מן הצד — לא עשה ולא כלום.\u0004","\u0003אלא\u0004 ודאי שם את הזמורות \u0003על גבן\u0004 של הכלונסאות. \u0003ובמאי\u0004 \u0005[ובמה,\u0006 באיזה מקרה\u0005]\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003בעשר\u0004 אמות מרחק בין מוט למוט — \u0003בהא לימא\u0004 \u0005[בזו יאמר]\u0006 \u0003ר' יוחנן בשבת לא?!\u0004 והלא הכל מודים שמועילה צורת הפתח בפתח הרחב עשר אמות.","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן \u0005—\u0006 \u0003ביתר מעשר,\u0004 והרי זה כשיטת רב שביותר מעשר אין צורת הפתח מועילה.","ודוחים: אין זו הוכחה גמורה. \u0003לא, לעולם\u0004 תאמר שהיה זה \u0003בעשר\u0004 אמות \u0003ו\u0004את הזמורות הוא שם \u0003מן הצד,\u0004 ומה שאמרנו בשם רב חסדא שצורת הפתח מן הצד ודאי אינה ראויה, אינו מוסכם על הכל. \u0003וב\u0004שיטת \u0003רב חסדא קא מיפלגי\u0004 \u0005[נחלקו],\u0006 שלדעת ריש לקיש אף צורת הפתח מן הצד מועילה, ור' יוחנן סבור כרב חסדא שאינה מועילה.","ומעירים: \u0003ורמי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 מדברי \u0003ר' יוחנן\u0004 על דברי \u0003ר' יוחנן, ורמי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 מדברי \u0003ריש לקיש\u0004 על דברי \u0003ריש לקיש,\u0004 שכן \u0003אמר ריש לקיש משום ר' יהודה בר' חנינא\u0004:"],["\u0003פיאה\u0004 כלומר גידור הכרם על ידי זמורות הקלועות ומונחות על כלונסאות \u0003מותרת\u0004, ונחשבת כמחיצה \u0003לענין כלאים, אבל לא ל\u0004ענין \u0003שבת. ור' יוחנן אמר: כמחיצות לשבת —\u0004 ש\u0003לא,\u0004 שאין פאה זו מתרת בהן, \u0003כך מחיצות לכלאים —\u0004 ש\u0003לא\u0004. ונמצא שאין דבריהם כאן מתאימים לדבריהם האחרים באותו נושא,","ואומרים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 משיטת \u0003ריש לקיש\u0004 על שיטת \u0003ריש לקיש לא קשיא\u0004 \u0005[אינו קשה]\u0006 כי אפשר לתרץ: \u0003הא\u0004 \u0005[זו]\u0006 שאמר שמועילה אף בשבת — \u0003דידיה\u0004 \u0005[\u0006דעתו \u0005שלו],\u0006 \u0003הא\u0004 \u0005[זו]\u0006 שמועילה רק לכלאים — \u0003דרביה\u0004 \u0005[\u0006דעתו \u0005של רבו],\u0006 ר' יהודה בר' חנינא. \u0003אלא\u0004 מדברי \u0003ר' יוחנן\u0004 על דברי \u0003ר' יוחנן קשיא\u0004 \u0005[קשה]!\u0006","\u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 כשהתיר גם בשבת וגם בכלאים, היה זה כשהיו הזמורות \u0005—\u0006 \u0003על גבן\u0004 של הקנים. \u0003הכא\u0004 \u0005[כאן] —\u0006 \u0003מן הצד,\u0004 וכשהוא מן הצד אינו מתיר אותו בכלאים, \u0003שפיר\u0004 \u0005[יפה]\u0006 ואפשר ליישב כך את הסתירה. \u0003אלא אי אמרת אידי ואידי מן הצד, מאי איכא למימר?\u0004 \u0005[אומר אתה זה וזה מן הצד, מה יש לומר]?\u0006","ומשיבים: \u0003לעולם, אידי ואידי\u0004 \u0005[זה וזה]\u0006 \u0003מן הצד\u0004. וכך יש להסביר: \u0003התם\u0004 \u0005[שם]\u0006 שהתיר — \u0003בשה\u0004 יו הכלונסאות רחוקים זה מזה \u0003עשר\u0004 אמות בלבד, \u0003הכא\u0004 \u0005[כאן]\u0006 שאסר — \u0003ביותר מעשר\u0004 אמות.","\u0003ומנא תימרא דשני לן\u0004 \u0005[ומניין תאמר —\u0006 \u0005ששונה לנו\u0006 להלכה\u0005]\u0006 \u0003בין עשר ליותר מעשר\u0004 — ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן לריש לקיש:\u0004 וכי \u0003לא כך היה המעשה שהלך ר' יהושע אצל ר' יוחנן בן נורי ללמוד תורה, אף על פי שבקי\u0004 היה ר' יהושע \u0003בהלכות כלאים, ומצאו שיושב בין האילנות ומתח זמורה מאילן לאילן\u0004 לאורכו. \u0003ואמר לו: רבי, אי גפנים כאן\u0004 בשטח שבין הזמורות \u0003מהו לזרוע כאן? אמר לו: בעשר — מותר, ביותר מעשר — אסור\u0004.","ומבררים: \u0003במאי עסקינן\u0004 \u0005[במה עוסקים אנו]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003על גבן יותר מעשר אסור\u0004 — \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 לענין כלאים: \u0003היו שם קנין הדוקרנין\u0004 (קנים העשויים כדקר הנעוץ באדמה)\u0003, ועשה להן פיאה מלמעלה, אפילו ביותר מעשר — מותר!\u0004 שלענין כלאים צורת הפתח העשויה כראוי ודאי שהיא מועילה.","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 הכוונה היא שעשאה \u0003מן הצד, וקאמר ליה\u0004 \u0005[ואמר לו]\u0006 שבמקרה זה \u0003בעשר — מותר, ביותר מעשר — אסור\u0004. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 כפי שמיושבים הדברים שהועלו הן לגבי עיקר ההלכה, והן לגבי הבנת דברי ר' יוחנן.","\u0003גופא\u0004 \u0005[לגופו\u0006 של ענין\u0005]\u0006 שהזכרנו מקודם \u0003אמר רב חסדא\u0004 כמה הלכות בצורת הפתח: \u0003צורת הפתח שעשאה מן הצד,\u0004 ולא שם קנה עליון מעל לקנים האחרים — \u0003לא עשה ולא כלום\u0004.","\u0003ו\u0004עוד \u0003אמר רב חסדא: צורת הפתח שאמרו — צריכה שתהא בריאה\u0004 (חזקה) \u0003כדי\u0004 שאפשר יהיה \u0003להעמיד בה דלת\u0004 ואף על פי כן דלת זו אינה חייבת להיות דלת רגילה, אלא \u0003אפילו\u0004 מחזיקה צורת הפתח \u0003דלת של קש\u0004 די בכך.","\u0003אמר ריש לקיש משום ר' ינאי: צורת הפתח צריכה היכר ציר\u0004. ושאלו: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003היכר ציר? אמר רב אויא: אבקתא\u0004 (חורים שציר הדלת מונח בהם) כדי שתהא ראויה לדלת.","מסופר: \u0003אשכחינהו\u0004 \u0005[מצא אותם]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אויא לתלמידי דרב אשי, אמר להו\u0004 \u0005[להם]:\u0006 \u0003אמר מר\u0004 \u0005[חכם\u0006 רב אשי\u0005]\u0006 \u0003מידי\u0004 \u0005[דבר]\u0006 \u0003בצורת הפתח? אמרו\u0004 ליה \u0005[לו]:\u0006 \u0003לא אמר ולא כלום,\u0004 ומשמע שהוא סבור שאין צורך בהיכר זה.","\u0003תנא\u0004 \u0005[שנינו]:\u0006 \u0003צורת הפתח שאמרו\u0004 עיקרה \u0003קנה מכאן וקנה מכאן וקנה על גביהן\u0004, אולם שאלו: האם \u0003צריכין\u0004 הקנים התחתונים \u0003ליגע\u0004 בקנה העליון? \u0003או אין צריכין ליגע? רב נחמן אמר: אין צריכין ליגע. ורב ששת אמר: צריכין ליגע\u0004.","מסופר: \u0003אזל\u0004 \u0005[הלך]\u0006 \u0003רב נחמן ועבד עובדא בי ריש גלותא כשמעתיה\u0004 \u0005[ועשה מעשה בבית ראש הגולה כשיטתו]\u0006 שהכשיר בצורת הפתח שאין הקנה העליון צמוד לקנים התחתונים. \u0003אמר\u0004 ליה \u0005[לו]\u0006 \u0003רב ששת לשמעיה\u0004 \u0005[לשמשו]\u0006 \u0003רב גדא: זיל\u0004 \u0005[לך],\u0006 \u0003שלוף\u0004 הוצא את הקנים ו\u0003שדינהו\u0004 \u0005[זרוק אותם].\u0006 \u0003אזל\u0004 \u0005[הלך],\u0006 \u0003שלף\u0004 את הקנים, ו\u0003שדינהו\u0004 \u0005[זרק אותם].\u0006 \u0003אשכחוהו דבי ריש גלותא\u0004 \u0005[מצאוהו בני בית ראש הגולה],\u0006 \u0003חבשוהו\u0004 (אסרוהו) על שקלקל את היתר העירובין שלהם. \u0003אזל\u0004 \u0005[הלך]\u0006 \u0003רב ששת, קם אבבא\u0004 \u0005[עמד על פתח\u0006 ראש הגולה\u0005],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003גדא, פוק תא\u0004 \u0005[צא\u0006 ו\u0005בוא]!\u0006 והניחוהו אנשי ראש הגולה. \u0003נפק ואתא\u0004 \u0005[יצא ובא].\u0006","מסופר: \u0003אשכחיה\u0004 \u0005[מצאו]\u0006 \u0003רב ששת לרבה בר שמואל אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תני מר מידי\u0004 \u0005[האם שנה אדוני דבר]\u0006 \u0003ב\u0004הלכות \u0003צורת הפתח? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 \u0003תנינא\u0004 \u0005[שנינו]\u0006 שנחלקו חכמים בדומה לזה בדין \u0003כיפה,\u0004 כלומר שער שתקרתו עשויה בעיגול ככיפה. \u0003ר' מאיר מחייב\u0004 שער זה \u0003במזוזה, וחכמים פוטרין\u0004. \u0003ושוין, שאם יש ברגליה\u0004 (בחלקים הניצבים של כיפה זו לפני העיגול) \u0003עשרה\u0004 טפחים \u0003שהיא חייבת.\u0004","\u0003אמר אביי\u0004 לפרש מחלוקתם: \u0003הכל מודים אם גבוהה\u0004 כל כיפה זו \u0003עשרה\u0004 טפחים \u0003ואין ברגליה\u0004 בצדה הזקוף \u0003שלשה\u0004 טפחים, \u0003אי נמי\u0004 \u0005[או גם כן]:\u0006 אם \u0003יש ברגליה שלשה\u0004 טפחים, אבל \u0003אין גבוהה עשרה\u0004 טפחים — \u0003ולא כלום,\u0004 אינה צריכה מזוזה כלל, שפתח הפחות מעשרה בצורה זו, ודאי אינו חייב במזוזה.","\u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 היה זה \u0003ב\u0004מקרה ש\u0003יש ברגליה שלשה\u0004 טפחים \u0003וגבוהה עשרה\u0004 טפחים, אבל בחלקה הקעור של הקשת \u0003אין רחבה ארבעה\u0004 טפחים, \u0003ויש בה\u0004 בכיפה חלק בנוי גדול למדי עד שאפשר למצוא מקום \u0003לחוק להשלימה לארבעה\u0004, שיהא בחלל הכיפה רוחב ארבעה טפחים בגובה עשרה.","ובכך נחלקו; \u0003ר' מאיר סבר: חוקקין להשלים\u0004 כלומר חושבים כאילו נעשתה כבר חקיקה זו, והושלם הפתח לצורתו הראויה. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים:]\u0006 \u0003אין חוקקין להשלים\u0004, וכיון שכעת אין ברוחב הכיפה ארבעה טפחים, אין לקבוע בו מזוזה. ולעניננו למדים אנו שלכל השיטות אין צורך שיגע המשקוף במזוזות הפתח, שהרי אם היו הרגלים גבוהות עשרה טפחים ויש ברוחבה ארבעה טפחים, דינה כמשקוף, אף על פי שאין קצה הכיפה נוגע ברגליה. ואפשר ללמוד מכאן שאף לגבי צורת הפתח אין הקנה העליון צריך לנגוע בקנים התחתונים, ושלא כשיטת רב ששת.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב ששת לרבה בר שמואל: \u0003אי משכחת להו\u0004 \u0005[אם תמצא אותם] —\u0006 \u0003לא תימא להו לבי ריש גלותא ולא מידי מהא מתניתא דכיפה\u0004 \u0005[אל תאמר להם לבית ראש הגולה דבר מברייתא זו של כיפה]\u0006 שמוכיחה שלא כדברי רב ששת, וימצאו חיזוק לטענתם עליו.","נחלקו חכמים מחלוקת עקרונית בדין \u0003הכשר מבוי,\u0004 לאמור: כיצד מכשירים את המבוי שיהא ראוי לטלטל בו. \u0003בית שמאי אומרים\u0004: יש צורך גם ב\u0003לחי\u0004 בצידו וגם ב\u0003קורה\u0004 מעליו. \u0003ובית הלל אומרים: או לחי או קורה. ר' אליעזר אומר: לחיין\u0004, כלומר אינו כשר אלא בשני לחיין, אחד מכל צד.","\u0003משום ר' ישמעאל אמר תלמיד אחד לפני ר' עקיבא: לא נחלקו בית שמאי ובית הלל על מבוי שהוא פחות\u0004 ברוחבו \u0003מארבע אמות, ש\u0004לדעת כולם \u0003הוא ניתר או בלחי או בקורה. על מה נחלקו — על\u0004 מבוי ה\u0003רחב מארבע אמות ועד עשר, שבית שמאי אומרים\u0004: אינו ניתר אלא ב\u0003לחי וקורה, ובית הלל אומרים: או\u0004 ב\u0003לחי או\u0004 ב\u0003קורה. אמר\u0004 לו \u0003ר' עקיבא\u0004: לא כן הוא, אלא \u0003על זה ועל זה נחלקו\u0004.","ומבררים: \u0003כמאן\u0004 \u0005[כמי\u0006 היא משנה זו\u0005]?\u0006 \u0003לא כ\u0004שיטת \u0003חנניה ולא כ\u0004שיטת \u0003תנא קמא.\u0004 שנחלקו חנניה וחכמים (לעיל עירובין דף ו, א) במבוי מפולש אם כדי להתירו די בצורת הפתח מצד אחד ובלחי וקורה מהצד האחר, או שצריך דלתות ממש לפחות בצד אחד. על כל פנים, לחי וקורה בלבד לדעת כולם, אינם מועילים. וכיון שאנו מבינים לפי שעה כי המחלוקת במשנתנו בין בית שמאי ובית הלל היתה בכל מבוי בין סתום בין מפולש הרי שכאן מצויה שיטה שונה לגמרי.","\u0003אמר ר' יהודה: הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך יש להבין\u0005]\u0006 שלא בכל מבוי דנו אלא \u0003הכשר מבוי סתום כיצד? בית שמאי אומרים\u0004: ב\u0003לחי וקורה, ובית הלל אומרים: או לחי או קורה\u0004 ומעתה באים לדון ביסודן העקרוני של השיטות.","\u0003בית שמאי אומרים: לחי וקורה, למימרא דקא סברי\u0004 \u0005[האם לומר\u0006 ש\u0005סברו]\u0006 \u0003בית שמאי: ארבע מחיצות דאורייתא\u0004 \u0005[מן התורה],\u0006 כלומר אין מקום נעשה רשות היחיד, אלא אם כן היו לו ארבע מחיצות מסביב, שהרי הלחי נחשב כמחיצה. ואם אינם מתירים מבוי בלא לחי, נמצא שהם סבורים שיש צורך לרשות היחיד בארבע מחיצות.","ודוחים: \u0003לא\u0004 אין זו הוכחה. מדין תורה, כגון לענין \u0003לזרוק\u0004 מרשות הרבים לתוכה \u0003מ\u0004חצר בת \u0003שלש\u0004 מחיצות \u0003הוא דמחייב\u0004 \u0005[שמתחייב].\u0006 ואולם להתיר \u0003לטלטל\u0004 גזרו איסור מדברי סופרים \u0003עד דאיכא\u0004 \u0005[שיש]\u0006 \u0003ארבע\u0004 מחיצות.","אף רוצים להסיק מדברי \u0003בית הלל\u0004 ה\u0003אומרים או\u0004 ב\u0003לחי או\u0004 ב\u0003קורה לימא קא סברי\u0004 \u0005[האם לומר\u0006 ש\u0005סברו]\u0006 \u0003בית הלל: שלש מחיצות\u0004 לפחות \u0003דאורייתא\u0004 \u0005[מן התורה\u0006 הן\u0005]\u0006 שבפחות מכאן אין זו רשות לעצמה?","ודוחים: \u0003לא,\u0004 אין להוכיח מכאן, שמא \u0003לזרוק — משתים הוא דמחייב\u0004 \u0005[שנתחייב]\u0006 מן התורה, ואולם להתיר \u0003לטלטל — עד דאיכא\u0004 \u0005[שיש]\u0006 \u0003שלש\u0004 מחיצות. וקורה או לחי לא לשם מחיצה נעשו אלא להיכר, שלא יבוא לטלטל מחוץ למבוי.","עוד שנינו במשנה: \u0003ר' אליעזר אומר לחיין. איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדים\u0005]\u0006 האם \u0003ר' אליעזר לחיין וקורה קאמר\u0004 \u0005[אמר,\u0006 התכוון\u0005],\u0006 וכשאמר לחיים, בא להוסיף על דברי בית שמאי שלא די בקורה אחת ובלחי אחד אלא בקורה ושני לחיים. \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003לחיין אפילו בלא קורה קאמר\u0004 \u0005[אמר,\u0006 התכוון\u0005]?\u0006","\u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ראיה מן המסופר בתוספתא: \u0003מעשה בר' אליעזר שהלך אצל ר' יוסי בן פרידא תלמידו\u0004"],["\u0003לעיירה אובלין ומצאו שיושב במבוי שאין לו אלא לחי אחד; אמר לו: בני, עשה לחי אחר. אמר לו: וכי לסותמו אני צריך!? אמר לו: יסתם, ומה בכך\u0004.","באותה תוספתא שנינו \u0003אמר רבן שמעון בן גמליאל: לא נחלקו בית שמאי ובית הלל על מבוי שהוא פחות מארבע אמות — שאינו צריך כלום, על מה נחלקו — על רחב מארבע אמות ועד עשר. שבית שמאי אומרים: לחי וקורה, ובית הלל אומרים: או לחי או קורה.\u0004","\u0003קתני מיהת\u0004 \u0005[שנינו מכל מקום]\u0006 \u0003\"וכי לסותמו אני צריך\", אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 שהצריך ר' אליעזר \u0003לחיין וקורה — משום הכי\u0004 \u0005[כך]\u0006 \u0003אמר\u0004 התלמיד: \u0003\"וכי לסותמו אני צריך\", אלא אי אמרת\u0004 \u0005[אם אמרת]\u0006 \u0003לחיין בלא קורה — מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003לסותמו?\u0004 הלא מלמעלה פתוח הוא!","ודוחים: אין מכאן ראייה, שמא \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003וכי לסותמו בלחיין אני צריך?\u0004 ומכל מקום אין להסיק מסקנה גמורה מענין זה.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 \u0003אמר\u0004 על דברי \u0003רבן שמעון בן גמליאל\u0004 שהוזכרו קודם ש\u0003לא נחלקו בית שמאי ובית הלל על מבוי שפחות מארבע אמות שאינו צריך כלום. והא אנן תנן\u0004: \u0005[והרי אנו שנינו]\u0006 \u0003משום ר' ישמעאל אמר תלמיד אחד לפני עקיבא: לא נחלקו בית שמאי ובית הלל על מבוי שהוא פחות מארבע אמות שהוא ניתר או בלחי או בקורה!\u0004 וכיצד אומר רבן שמעון בן גמליאל בדעתם שאף תיקון זה אינו נחוץ?","\u0003אמר רב אשי; הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אינו צריך\u0004 תיקון נוסף ב\u0003לחי וקורה כ\u0004שיטת \u0003בית שמאי, ולא לחיין כ\u0004שיטת \u0003ר' אליעזר, אלא: או לחי או קורה, כ\u0004שיטת \u0003בית הלל\u0004 במבוי גדול. ו\"כלום\" שאמר, כלומר, יותר ממה שמחייבים בית הלל.","ושאלו: \u0003וכמה\u0004 יהא רחבו של מבוי שלכל הדעות אינו צריך כל תיקון אף בלחי? \u0003אמר רב אחלי: ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003רב יחיאל: עד ארבעה\u0004 טפחים.","\u0003אמר רב ששת אמר רב ירמיה בר אבא אמר רב: מודים חכמים לר' אליעזר בפסי חצר\u0004 כלומר מחלוקתם בדבר מספר הלחיים היתה רק במבוי, אבל חצר שנפרצה אין לה תקנה להחשיבה כסתומה אלא על ידי פסים, כעין לחי, משני צדדים. \u0003ו\u0004אילו \u0003רב נחמן אמר\u0004 בשינוי: \u0003הלכה כר' אליעזר בפסי חצר.\u0004","\u0003אמר רב נחמן בר יצחק: מאן\u0004 \u0005[מי]\u0006 אלה שאמר רב ירמיה עליהם ש\u0003מודים\u0004 לר' אליעזר? — הכוונה ל\u0003רבי\u0004. כיון שאמר רב נחמן \u0003הלכה\u0004 כר' אליעזר \u0003מכלל דפליגי\u0004 \u0005[מכאן שנחלקו]\u0006 אף בדבר זה, \u0003מאן פליג עליה\u0004 \u0005[מי נחלק עליו] —\u0006 \u0003רבנן [חכמים].\u0004 וזה הוא \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003חצר ניתרת\u0004, אם היתה בה פירצה פחותה מעשר אמות, על ידי הנחת \u0003פס אחד\u0004 בצידה. \u0003רבי אומר: בשני פסין.\u0004","\u0003אמר ר' אסי אמר ר' יוחנן: חצר צריכה שני פסין\u0004 כדברי רבי. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לר' אסי: מי\u0004 \u0005[האם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]?\u0006 \u0003והא את הוא דאמרת משמיה דר' יוחנן\u0004 \u0005[והרי אתה הוא שאמרת משמו של ר' יוחנן]:\u0006 \u0003פסי חצר צריכין שיהא בהן ארבעה\u0004 טפחים; \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שהצריך ר' יוחנן \u0003ארבעה מכאן וארבעה מכאן —\u0004","\u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003רב אדא בר אבימי קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' חנינא, ואמרי לה קמיה\u0004 \u0005[ויש אומרים לפני]\u0006 \u0003ר' חנינא בר פפי\u0004, שמה שאמרו בדין חצר קטנה שנפרצה בכל אורכה לחצר גדולה שדיירי הגדולה משתמשים בחצרם אפילו היתה ה\u0003קטנה — בעשר\u0004 אמות, \u0003וגדולה — באחת עשרה!\u0004 ואם ההפרש בין אורך הקטנה לגדולה הוא רק אמה אחת (ששה טפחים), לא יתכן שיהיו פסים בני ארבעה טפחים מכל צד, שהרי יחד הם יותר מהפרש אמה.","מספרים: \u0003כי סליק\u0004 \u0005[כאשר בא]\u0006 \u0003ר' זירא מימי\u0004 \u0005[מ\u0006מסעותיו \u0005הימיים]\u0006 \u0003פרשה\u0004 הסביר סתירה זו שבדברי ר' יוחנן כך: אם היה הפס \u0003ברוח אחת\u0004 בלבד צריך שיהא רחב \u0003ארבעה,\u0004 אבל אם היו שני פסים \u0003משתי רוחות\u0004 — דיו \u0003משהו לכאן ומשהו לכאן\u0004.","\u0003והדתני\u0004 \u0005[ומה ששנה]\u0006 \u0003אדא בר אבימי\u0004 בענין ההבדל בין החצרות. שלפי שיטת ר' זירא אפילו היתה חצר אחת גדולה רק בארבעה טפחים די בכך, אין דברי רב אדא בר אבימי מקובלים על הכל אלא — שיטת \u0003רבי היא\u0004 המצריך שני פסים בחצר. ועוד, ש\u0003סבר לה רבי כר' יוסי\u0004, שאמר שרוחב הלחי שלשה טפחים, ואם מצרפים שלשה טפחים מכאן ושלשה מכאן הרי זו אמה. ומשום כך ההפרש הקטן ביותר בין חצר קטנה לגדולה הוא לפחות אמה אחת.","\u0003אמר רב יוסף אמר רב יהודה אמר שמואל: חצר ניתרת בפס אחד. אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: מי\u0004 \u0005[האם]\u0006 \u0003אמר שמואל הכי\u0004 \u0005[כך]?\u0006 \u0003והא\u0004 \u0005[והלא]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל לרב חנניה בר שילא: את לא תעביד עובדא\u0004 \u0005[אתה לא תעשה מעשה]\u0006 להתיר פירצת חצר \u0003אלא או ברוב דופן\u0004 שנשארה שלמה \u0003או בשני פסין! —\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ואנא לא ידענא, דעובדא הוה בדורא דרעותא\u0004 \u0005[ואני איני יודע\u0006 לתרץ לך את הסתירה, אלא \u0005שמעשה היה בכפר של רועים],\u0006 \u0003לשון ים הנכנס לחצר הוה\u0004 \u0005[היתה]\u0006 שפרצה את מחיצת החצר מצד אחד, ורצו בני החצר להשתמש במימיה בשבת. \u0003ואתא לקמיה\u0004 \u0005[ובא\u0006 הדבר \u0005לפני]\u0006 \u0003רב יהודה, ולא אצרכיה\u0004 \u0005[ולא הצריך אותו]\u0006 \u0003אלא פס אחד\u0004 מצד אחד של לשון הים.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לשון ים קאמרת\u0004 \u0005[אמרת],\u0006 שונה היא לשון ים ואין ללמוד ממנה, כי \u0003קל\u0004 (הקלה) \u0003הוא שהקלו חכמים במים\u0004. שיודעים אנו שהקלו חכמים שבמקום שיש מים לא הצריכו לעשות מחיצה גמורה כדינה, והסתפקו במחיצה קלושה שהרי המים מצויים שם.","ומסופר \u0003כ\u0004עין זה \u0003דבעא מיניה\u0004 \u0005[ששאל ממנו]\u0006 \u0003ר' טבלא מרב: מחיצה תלויה, מהו שתתיר בחורבה?\u0004 שייחשבו אותם חלקי הכתלים שנשארו תלויים בחורבה כמחיצות היורדות וסותמות עד למטה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין מחיצה תלויה\u0004 בצורה זו \u0003מתרת אלא\u0004 על גבי \u0003מים\u0004, כי \u0003קל הוא שהקלו חכמים במים\u0004,","ושואלים: ו\u0003מכל מקום קשיא\u0004 \u0005[קשה]\u0006 שעדיין נשארה בלא תירוץ הסתירה בדברי שמואל לפי המסורות השונות.","\u0003כי אתו\u0004 \u0005[כאשר באו]\u0006 \u0003רב פפא ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע מבי רב\u0004 \u0005[מבית רבם]\u0006 \u0003פירשוה\u0004: אם היה הפס \u0003מרוח אחת\u0004 — הרי צריך להיות \u0003בארבעה\u0004 טפחים, \u0003משתי רוחות — משהו לכאן ומשהו לכאן.\u0004","\u0003אמר רב פפא: אי קשיא\u0004 \u0005[אם קשה]\u0006 \u0003לי\u0004 משהו בדבר \u0005—\u0006 \u0003הא קשיא\u0004 \u0005[זה קשה]\u0006 \u0003לי,\u0004 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל לרב חנניה בר שילא: את לא תעביד עובדא\u0004 \u0005[אתה לא תעשה מעשה]\u0006 \u0003אלא או ברוב דופן או בשני פסין,\u0004","\u0003למה לי רוב דופן? בפס ארבעה\u0004 טפחים \u0003סגי\u0004 \u0005[די]!\u0006 \u0003וכי תימא מאי\u0004 \u0005[ואם תאמר מהו]\u0006 \u0003ברוב דופן\u0004 שנאמר כאן שהוא רק \u0003ב\u0004מקרה מיוחד שהיה אורך \u0003דופן שבעה\u0004 טפחים, ולכן \u0003בארבעה\u0004 טפחים \u0003הוה ליה\u0004 \u0005[הרי הוא]\u0006 \u0003רוב דופן?\u0004 ואולם כאשר אורך המחיצה הוא שבעה טפחים \u0003למה לי ארבעה\u0004 טפחים לסתימה? \u0003בשלשה\u0004 טפחים \u0003ומשהו סגי\u0004 \u0005[די]!\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003אמר רב אחלי ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003רב יחיאל\u0004 שכל מה שהצריכו בתיקון מבוי אינו אלא \u0003עד ארבעה\u0004 טפחים, אבל מבוי הצר מארבעה טפחים אינו צריך כל תיקון, ואף כאן לאחר סתימת יותר משלשה נשאר חלל פחות מארבעה!","ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003כאן\u0004 בדברי שמואל מדובר — \u0003בחצר,\u0004 שאף פירצה פחותה מארבעה צריכה תיקון, \u0003כאן\u0004 בדברי רב אחלי מדובר — \u0003במבוי, ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 זו שאמר \u0003רב אחלי גופיה תנאי היא\u0004 \u0005[היא עצמה\u0006 מחלוקת \u0005תנאים]\u0006 ואין הכל מודים לו בכך.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003לשון ים הנכנס לחצר\u0004 שאחת ממחיצותיה פרוצה חלקית — \u0003אין ממלאין הימנו בשבת\u0004 מים, שההים דינו ככרמלית ואסור לטלטל ממנו לרשות היחיד, \u0003אלא אם כן יש לו\u0004 ללשון זו על גביו \u0003מחיצה גבוה עשרה טפחים\u0004 ומשום מחיצה זו נעשתה אף לשון הים כחלק מן החצר. \u0003במה דברים אמורים — שפירצתו\u0004 שנכנסת בה לשון ים \u0003ביותר מעשרה\u0004 אמות, \u0003אבל עשרה — אין צריך כלום,\u0004","ושואלים: \u0003ממלא הוא דלא ממלאינן, הא טלטולי מטלטלינן\u0004 \u0005[למלא הוא שאין אנו ממלאים\u0006 ממנו\u0005, ואולם לטלטל\u0006 בחצר עצמה \u0005אנו מטלטלים],\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003נפרצה חצר במלואה\u0004 כלומר במלוא אורך דופנה ביותר מעשר אמות \u0003למקום האסור לה!\u0004 שכן לשון הים אסורה לה בטלטול ובהולכה, ולכן לא רק שאסור לטלטל ממנה אלא צריך אף לאסור את החצר עצמה בטלטול."],["\u0003הכא במאי עסקינן דאית ליה גידודי\u0004 \u0005[כאן במה אנו עוסקים שיש לה\u0006 לחצר \u0005שרידי\u0006 פסים\u0005]\u0006 מכאן ומכאן ולא נפרצה במלואה. (ר\"ח, רי\"ף).","\u0003אמר רב יהודה: מבוי שלא נשתתפו בו\u0004 אנשי המבוי בעירוב ואסור להם לטלטל בו בשבת, בכל זאת, אם \u0003הכשירו\u0004 (תיקנו) \u0003בלחי\u0004 שהניח בפתחו, \u0003הזורק לתוכו\u0004 מרשות הרבים — \u0003חייב,\u0004 שכן דינו כמחיצה ודין החצר כרשות היחיד גמורה, ואם \u0003הכשירו\u0004 (תיקנו) \u0003בקורה — הזורק לתוכו פטור,\u0004 שאין הקורה אלא משום היכר, ואינה יכולה להיחשב כמחיצה העושה את המבוי רשות היחיד.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רב ששת: טעמא\u0004 \u0005[הטעם]\u0006 דוקא ש\u0003לא נשתתפו בו, הא\u0004 \u0005[הרי\u0006 אם\u0005]\u0006 \u0003נשתתפו בו — אפילו הכשירו בקורה נמי\u0004 \u0005[גם כן]\u0006 \u0003חייב?!\u0004 אולם דבר זה אינו מתקבל על הדעת, שהרי אפשר לשאול: \u0003וכי ככר זו\u0004 שבה נשתתפו השכנים כשעשו את שיתוף המבוי בלא שינוי במחיצותיו \u0003עשה אותו רשות היחיד או רשות הרבים?\u0004","\u0003והתניא\u0004 \u0005[והרי\u0006 במפורש \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חצירות של רבים ומבואות שאינן מפולשין, בין עירבו ובין\u0004 ש\u0003לא עירבו — הזורק לתוכן\u0004 מתוך בתי החצר \u0003חייב\u0004, היפך דברי רב יהודה!","\u0003אלא אי איתמר הכי איתמר\u0004 \u0005[אם נאמר כך נאמר\u0006 הדבר\u0005]\u0006 \u0003אמר רב יהודה: מבוי שאינו ראוי לשיתוף\u0004 כלומר מבוי מפולש, אם \u0003הכשירו בלחי הזורק לתוכו חייב\u0004 שהלחי נחשב כמחיצה שלישית, וכיון שהמבוי סגור משלשה צדדים הריהו כרשות היחיד. אם \u0003הכשירו בקורה — הזורק לתוכו פטור.\u0004","\u0003אלמא קסבר\u0004 \u0005[מכאן שסבר]\u0006: \u0003לחי משום מחיצה וקורה משום היכר\u0004, אבל אינה חשובה כמחיצה. \u0003וכן אמר רבה: לחי משום מחיצה וקורה משום היכר. ורבא אמר: אחד זה ואחד זה משום היכר.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יעקב בר אבא לרבא\u0004 ממה ששנינו: \u0003הזורק\u0004 מרשות הרבים \u0003למבוי, יש לו לחי — חייב, אין לו לחי — פטור\u0004, נמצא שהלחי נחשב מחיצה גמורה!","ענה לו: \u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 התכוון\u0005]\u0006 אם המבוי היה סתום כך ש\u0003אינו צריך אלא לחי\u0004 להתירו כיון שיש לו כבר שלש מחיצות, ומדין התורה הרי הוא רשות היחיד גמורה, לכן \u0003הזורק לתוכו\u0004 מרשות הרבים — \u0003חייב\u0004, אולם אם היה צריך תיקון ב\u0003לחי ודבר אחר\u0004 שהיו בו רק שתי מחיצות — \u0003הזורק לתוכו פטור,\u0004 שאינו נחשב כרשות היחיד.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003יתר על כן אמר ר' יהודה: מי שיש לו שני בתים בשני צידי רשות הרבים\u0004. \u0003עושה\u0004 לו \u0003לחי מכאן ולחי מכאן, או קורה מכאן וקורה מכאן ונושא ונותן באמצע\u0004. שעל ידי הלחיים נחשב כאילו עשה מחיצות ברשות הרבים ומעתה יש לו בין שני הבתים תחום של רשות היחיד.","\u0003אמרו לו\u0004 חכמים: \u0003אין מערבין רשות הרבים בכך!\u0004 ומדברי ר' יהודה אפשר איפוא ללמוד שלחי דינו כמחיצה גמורה!","ומשיבים: לא זה הוא הטעם, אלא \u0003התם קסבר\u0004 \u0005[שם\u0006 משום \u0005שסבר]\u0006 \u0003ר' יהודה: שתי מחיצות\u0004 עושות מ\u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 שהשטח המצוי ביניהן נחשב כרשות היחיד, ולא הוצרך ר' יהודה ללחיים אלא לשם היכר וסימון בלבד. ואם כן אין להביא ראיה גמורה אף ממקור זה.","\u0003אמר רב יהודה אמר רב: מבוי שארכו כרחבו אינו ניתר בלחי משהו\u0004 כשאר מבוי, אלא בפס הרחב ארבעה טפחים, משום שלא זה המבוי שדברו בו חכמים. \u0003אמר רב חייא בר אשי אמר רב: מבוי שארכו כרחבו אינו ניתר בקורה טפח.\u0004","\u0003אמר ר' זירא: כמה מכוונן שמעתא דסבי\u0004 \u0005[כמה מכוונות הלכותיהם של הזקנים,\u0006 זקני החכמים\u0005]\u0006 ומסביר: \u0003כיון\u0004 שמבוי זה \u0003ארכו כרחבו — הוה ליה\u0004 \u0005[הרי הוא]\u0006 כ\u0003חצר, וחצר אינה ניתרת בלחי וקורה אלא בפס ארבעה.\u0004","\u0003אמר ר' זירא\u0004: אף על פי כן \u0003אי קשיא לי — הא קשיא לי\u0004 \u0005[אם קשה לי, הרי זה קשה לי]\u0006: \u0003ליהוי האי\u0004 \u0005[שיהיה זה]\u0006 ה\u0003לחי כפס משהו ונשתרי\u0004 \u0005[ויתיר]\u0006 את המבוי, כפי שניתרת פירצת החצר על ידי פס!","ומעירים ומסבירים שאין הדבר כן, כי \u0003אשתמיטתיה הא דאמר\u0004 \u0005[נשמט,\u0006 נעלם \u0005ממנו זה שאמר]\u0006 \u0003ר' אסי אמר\u0004 בשם \u0003ר' יוחנן: פסי חצר צריכין שיהא בהן ארבעה\u0004 טפחים ואילו לחי דיו במשהו.","\u0003אמר רב נחמן: נקטינן\u0004 \u0005[מחזיקים אנו\u0006 בכלל זה\u0005],\u0006 \u0003איזהו מבוי שניתר בלחי וקורה — כל שארכו יתר על רחבו, ובתים וחצרות פתוחים לתוכו, ואיזו היא חצר שאינה ניתרת בלחי וקורה אלא בפס ארבעה — כל ש\u0004היא \u0003מרובעת\u0004.","ותוהים: \u0003מרובעת — אין\u0004 \u0005[כן]\u0006 \u0003עגולה — לא\u0004 אינה נחשבת כחצר?! ומתקנים: \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006: \u0003אי\u0004 \u0005[אם]\u0006 \u0003ארכה יתר על רחבה — הוה ליה\u0004 \u0005[הרי היא]\u0006 כ\u0003מבוי, ומבוי בלחי וקורה סגיא\u0004 \u0005[דיה]\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא — הוה לה\u0004 \u0005[הרי היא]\u0006 \u0003חצר\u0004.","ושואלים: \u0003וכמה\u0004 צריך אורכה להיות יתר על רחבה כדי שיקרא מבוי? \u0003סבר שמואל למימר\u0004 \u0005[לומר]\u0006 \u0003עד דאיכא\u0004 \u0005[שיש]\u0006 באורכה \u0003פי שנים\u0004 מ\u0003רחבה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב: הכי\u0004 \u0005[כך]\u0006 \u0003אמר חביבי\u0004 (דודי, ר' חייא): \u0003אפילו\u0004 אורכה יתר על רוחבה ב\u0003משהו\u0004 חלים עליה דיני מבוי.","מסופר במשנה שתלמיד אחד מסר הלכה לפני ר' עקיבא, ולא קיבל ר' עקיבא את דבריו."],["ש\u0003ר' עקיבא אומר: על זה ועל זה נחלקו כו'.\u0004","ומתחילה שואלים לעיקרה של השיטה: הלא \u0003ר' עקיבא היינו\u0004 \u0005[זהו]\u0006 \u0003תנא קמא\u0004 שהרי אף הוא מסכים שאין הבדל במחלוקת בית שמאי ובית הלל מה רוחב המבוי. ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005]\u0006 הקשור בהלכה שאמר \u0003רב אחלי, ואיתימא\u0004 \u0005[ואם תאמר\u0006 שאמר זאת\u0005]\u0006 \u0003רב יחיאל\u0004, במבוי הצר מארבעה טפחים, שאחד מהם אומר שאינו צריך תיקון כלשהו. \u0003ולא מסיימי\u0004 \u0005[ואינם מוגדרים]\u0006 כלומר, לא ברור לנו מי הוא החכם המקבל שיטת רב אחלי ומי הוא הדוחה אותה אבל זו היא הנקודה שבה נבדלת שיטת ר' עקיבא מדברי התנא קמא.","\u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' עקיבא: לא אמר ר' ישמעאל דבר זה\u0004, שאין נראה שחכם כר' ישמעאל יטעה בכך, \u0003אלא אותו תלמיד אמר דבר זה\u0004 מדעתו\u0003, והלכה כאותו תלמיד.\u0004","על כך מקשים: \u0003הא גופה קשיא\u0004 \u0005[זו עצמה קשה]\u0006: \u0003אמרת \"לא אמר ר' ישמעאל דבר זה\" — אלמא לית הלכתא כוותיה\u0004 \u0005[מכאן שאין הלכה כמותו]\u0006 \u0003והדר אמרת\u0004 \u0005[וחזרת ואמרת]\u0006: \u0003\"הלכה כאותו תלמיד\"!\u0004","\u0003אמר רב יהודה אמר שמואל: לא אמרה ר' עקיבא אלא לחדד בה התלמידים\u0004 שרצה לעודד את תלמידיו שאף הם יחדשו דברי הלכה. ולכן שבח אותו תלמיד בפניהם, ולא נתכוון לפסוק כמותו.","\u0003ורב נחמן בר יצחק אמר\u0004 הסבר אחר לסתירה זו: \u0003נראין איתמר\u0004 \u0005[נאמר],\u0006 שאמנם לא אמר ר' ישמעאל כך, אבל נראים דברי התלמיד.","\u0003אמר ר' יהושע בן לוי: כל מקום שאתה מוצא \"משום ר' ישמעאל אמר תלמיד אחד לפני ר' עקיבא\" — אינו אלא ר' מאיר\u0004 שהוא התלמיד \u0003ששימש את ר' ישמעאל ואת ר' עקיבא.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' מאיר: כשהייתי אצל ר' ישמעאל הייתי מטיל קנקנתום\u0004 (גפרת נחושת) \u0003לתוך הדיו\u0004 שבה כתבתי ספרי קודש, \u0003ולא אמר לי דבר, כשבאתי אצל\u0004 (לפני) \u0003ר' עקיבא אסרה עלי\u0004.","ומקשים: \u0003איני\u0004 \u0005[וכי כן הוא]?!\u0006 והרי \u0003אמר רב יהודה אמר שמואל משום ר' מאיר: כשהייתי לומד אצל ר' עקיבא הייתי מטיל קנקנתום לתוך הדיו ולא אמר לי דבר. וכשבאתי אצל ר' ישמעאל אמר לי: בני, מה מלאכתך? אמרתי לו: לבלר אני\u0004 הכותב ספרי קודש. \u0003אמר לי: בני, הוי זהיר במלאכתך שמלאכתך מלאכת שמים היא\u0004 וזהירות נחוצה בה \u0003שמא אתה מחסר אות אחת או מייתר אות אחת\u0004 שלא במקום — \u0003נמצאת מחריב את כל העולם כולו\u0004 שייתור או חיסור אות עלול לעתים לשנות או להפוך את משמעות הענין לדברים שמשמעותם חורבן.","\u0003אמרתי לו: דבר אחד יש לי וקנקנתום שמו, שאני מטיל לתוך הדיו\u0004 ואיני חושש. \u0003אמר לי: וכי מטילים קנקנתום לתוך דיו? והלא אמרה תורה\u0004 בדין הסוטה: \u0003\"וכתב\u0004 את האלות האלה הכהן בספר \u0003ומחה\u0004 אל מי המרים\" (במדבר ה, כג), ומשמעו \u0003\"כתב\" שיכול להמחות\u0004.","ומתחילה שואלים: \u0003מאי קאמר ליה ומאי קא מהדר ליה\u0004 \u0005[מה אמר לו ומה השיב לו],\u0006 שהרי לכאורה נראה שתשובת ר' מאיר בענין קנקנתום אינה עונה להערתו של ר' ישמעאל בענין חסירות ויתירות.","ומסבירים: \u0003הכי קאמר ליה\u0004 \u0005[כך אמר לו],\u0006 \u0003לא מבעיא\u0004 \u0005[איני צריך\u0006 לאמר\u0005]\u0006 \u0003בחסירות וביתרות דלא טעינא, דבקי אנא\u0004\u0005 [שאיני טועה, שבקי אני],\u0006 \u0003אלא אפילו מיחש\u0004 \u0005[לחשוש]\u0006 \u0003לזבוב נמי, דילמא אתי ויתיב אתגיה דדל\"ת, ומחיק ליה, ומשוי ליה\u0004 \u0005[גם כן, שמא יבוא וישב על תגו של דל\"ת וימחוק אותו ויעשה אותו]\u0006 \u0003רי\"ש,\u0004 ותשתנה המשמעות — איני חושש לכך. כי \u0003דבר אחד יש לי וקנקנתום שמו שאני מטיל לתוך הדיו\u0004 ומשום כך אין הדיו נמחקת.","ומכל מקום \u0003קשיא\u0004 \u0005[קשה]\u0006 \u0003שימוש\u0004 על \u0003שימוש, קשיא\u0004 \u0005[קשה]\u0006 \u0003אסרה\u0004 על \u0003אסרה.\u0004 שבמקור אחד נאמר ששימש תחילה את ר' עקיבא, ובמקור אחר נאמר ששימש תחילה את ר' ישמעאל. וכן שממקור אחד נראה שר' עקיבא הוא שאסר עליו שימוש בקנקנתום, ובמקור אחר נראה שר' ישמעאל הוא שאסר.","ומעירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 מ\u0003שימוש\u0004 על \u0003שימוש לא קשיא\u0004 \u0005[לא קשה],\u0006 שאפשר להסביר זאת כך: \u0003מעיקרא אתא לקמיה\u0004 \u0005[מתחילה בא\u0006 ר' מאיר \u0005לפני]\u0006 \u0003ר' עקיבא, ומדלא מצי למיקם אליביה\u0004 \u0005[ומכיון שלא היה יכול לעמוד על שיטתו]\u0006 \u0003— אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' ישמעאל, וגמר גמרא, והדר אתא לקמיה\u0004 \u0005[ולמד מסורת, וחזר ובא לפני]\u0006 \u0003ר' עקיבא, וסבר סברא\u0004 \u0005[וסבר סברות].\u0006 שלאחר שלמד עיקרי שיטת הלימוד אצל ר' ישמעאל יכול היה כבר להבין את דבריו.","\u0003אלא אסרה\u0004 על \u0003אסרה\u0004 ממה שנאמר במקור אחד שאסר ר' עקיבא ובמקום אחר שר' ישמעאל הוא שאסר \u0003קשיא\u0004 \u0005[קשה]!\u0006 ומעירים: אכן, \u0003קשיא\u0004 \u0005[קשה],\u0006 ולא נמצאה תשובה.","\u0003תניא\u0004 \u0005[שנויה\u0006 בברייתא\u0005]\u0006 \u0003ר' יהודה אומר, ר' מאיר היה אומר: לכל\u0004 לצורך כתיבת כל ספרי קודש \u0003מטילין קנקנתום לתוך הדיו, חוץ מ\u0004לכתיבת \u0003פרשת סוטה\u0004, כי פרשת סוטה צריכה להיות ראויה להימחק לצורך הסוטה. \u0003ור' יעקב אומר משמו: חוץ מ\u0004לכתיבת \u0003פרשת סוטה שבמקדש\u0004 העשויה לצורך הסוטה להימחק.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם,\u0006 לאמר: מה שורש המחלוקת ביניהם\u0005]?\u0006 ומשיבים: \u0003אמר רב ירמיה: למחוק לה מן התורה איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 כלומר, שנחלקו אם אפשר למחוק לצורך הסוטה מפרשתה הכתובה בתורה. או שיש לכתוב פרשה זו במיוחד לצורך הסוטה.","\u0003והני תנאי כי הני תנאי\u0004 \u0005[ותנאים אלה\u0006 נחלקו \u0005כתנאים אחרים]\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין מגילתה\u0004 של סוטה זו שנכתבה עבורה ולא נמחקה \u0003כשירה להשקות בה סוטה אחרת\u0004. ואילו \u0003ר' אחי בר יאשיה אמר: מגילתה כשירה להשקות בה סוטה אחרת.\u0004 וכמו כן בספר תורה שהרי אינו נכתב לשם סוטה.","\u0003אמר רב פפא: דילמא\u0004 \u0005[שמא]\u0006 \u0003לא היא,\u0004 ואין הדברים זהים. כי \u0003עד כאן לא קאמר תנא קמא התם\u0004 \u0005[לא אמר התנא הראשון שם]\u0006 שאין מגילתה כשירה — \u0003אלא כיון דאינתיק לשום\u0004 \u0005[שנותקה\u0006 ויועדה \u0005לשמה של]\u0006 \u0003רחל, תו לא הדרא מינתקא לשום\u0004 \u0005[שוב אינה חוזרת ומנותקת,\u0006 ומיועדת \u0005לשמה של\u0006 אחרת\u0005]\u0006 \u0003לאה, אבל גבי\u0004 \u0005[אצל]\u0006 \u0003תורה דסתמא מיכתבא, הכי נמי דמחקינן\u0004 \u0005[ש\u0006כתובה \u0005סתם, כך גם כן שאנו מוחקים]\u0006 ואין אנו אומרים שאין מוחקים כיון שנכתבה שלא לשמה.","ועוד \u0003אמר רב נחמן בר יצחק\u0004 ליישב את הדברים בדרך אחרת: \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003לא היא,\u0004 שיש הבדל אחר בין המקרים, והוא: \u0003עד כאן לא קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' אחי בר יאשיה\u0004 שם שאפשר להשתמש במגילתה של סוטה אחרת — \u0003אלא דאיכתיב מיהת\u0004 \u0005[שנכתב בכל אופן]\u0006 \u0003לשום סוטה בעולם,\u0004 שהרי נועדה המגילה עבור סוטה כלשהי, \u0003אבל גבי\u0004 \u0005[אצל]\u0006 \u0003תורה,\u0004 ש\u0003להתלמד כתיבא\u0004 \u0005[כתובה] —\u0006 \u0003הכי נמי דלא מחקינן\u0004 \u0005[כך גם כן\u0006 נאמר \u0005שאיננו מוחקים]\u0006","ושואלים: \u0003ולית ליה\u0004 \u0005[וכי אין לו,\u0006 אין הוא סבור\u0005]\u0006 \u0003לר' אחי בר יאשיה הא דתנן\u0004 \u0005[זו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003כתב גט לגרש את אשתו\u0004"],["\u0003ונמלך\u0004 והתחרט ולא גרש \u0003ומצאו בן עירו ואמר: שמך כשמי ושם אשתך כשם אשתי\u0004 וכיון שאנו אף מאותה עיר תן לי את הגט ואגרש אני בו את אשתי \u0003— פסול\u0004 גט זה \u0003לגרש בו!\u0004 נמצא שאין אדם יכול לגרש אשה בגט שנכתב לאחרת, ואף לגבי סוטה כן.","ודוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]?\u0006 \u0003התם\u0004 \u0005[שם,\u0006 בגט\u0005]\u0006 \u0003\"וכתב לה\"\u0004 נאמר (דברים כד, א), ולכן \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003כתיבה לשמה\u0004 של אותה אשה, \u0003הכא\u0004 \u0005[כאן]\u0006 בסוטה \u0003\"ועשה לה\u0004 נאמר ולכן \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003עשיה לשמה, ועשייה דידה\u0004 \u0005[שלה,\u0006 של הסוטה\u0005]\u0006 \u0003מחיקה היא,\u0004 אבל הכתיבה אינה צריכה שתהא לשמה.","כיון שדובר קודם על ר' מאיר ולימודו מביאים מאמר אחר בנושא זה. \u0003אמר ר' אחא בר חנינא: גלוי וידוע לפני מי שאמר והיה העולם שאין בדורו של ר' מאיר\u0004 חכם גדול \u0003כמותו, ומפני מה לא קבעו הלכה כמותו —\u0004 משום \u0003שלא יכלו חביריו לעמוד על סוף דעתו,\u0004 שכן היה חריף עד כדי כך שהיה יכול לתת טעמים טובים לכל דבר, אף שאינו כהלכה. \u0003שהוא\u0004 היה \u0003אומר על טמא טהור ומראה לו פנים,\u0004 כלומר צדדים — להוכיח שכן הוא. וכן \u0003על טהור טמא ומראה לו פנים\u0004. ולא ידעו חכמים באלו דברים יש לסמוך על נימוקיו, ובאלו יש לדחותם.","\u0003תנא\u0004 \u0005[שנוי]\u0006: \u0003לא ר' מאיר שמו\u0004 האמיתי \u0003אלא ר' נהוראי שמו, ולמה נקרא שמו ר' מאיר?\u0004 כינוי הוא זה, ללמד \u0003שהוא מאיר עיני חכמים בהלכה, ולא נהוראי שמו\u0004 של התנא ר' נהוראי \u0003אלא ר' נחמיה שמו\u0004 האמיתי. \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003ר' אלעזר בן ערך שמו, ולמה נקרא שמו נהוראי\u0004 — \u0003שמנהיר\u0004 \u0005[מאיר]\u0006 \u0003עיני חכמים בהלכה\u0004.","ועוד בשבחו של ר' מאיר \u0003אמר רבי: האי דמחדדנא מחבראי — דחזיתיה לר' מאיר מאחוריה,\u0004 \u0005[זה שמחודד אני\u0006 וחריף יותר \u0003מחברי —\u0004 משום \u0005שראיתי את ר' מאיר מאחוריו]\u0006 כלומר ישבתי מאחוריו בזמן שהיינו לומדים. \u0003ואילו חזיתיה מקמיה — הוה מחדדנא טפי\u0004 \u0005[הייתי רואה אותו מלפניו —\u0006 \u0005הייתי מחודד יותר]\u0006, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"והיו עיניך ראות את מוריך\"\u0004 (ישעיה ל, כ), וראיית פני רב מועילה להבנה ולחידוד.","ועוד אמרו, \u0003אמר ר' אבהו אמר ר' יוחנן: תלמיד היה לו לר' מאיר וסומכוס שמו, שהיה אומר על כל דבר ודבר של טומאה ארבעים ושמונה טעמי טומאה, ועל כל דבר ודבר של טהרה ארבעים ושמונה טעמי טהרה\u0004.","ובדומה לזה \u0003תנא\u0004 \u0005[שנינו]:\u0006 \u0003תלמיד ותיק היה ביבנה\u0004 שבכוח חריפותו \u0003היה מטהר את השרץ\u0004 — שכתוב בתורה במפורש שהוא טמא — \u0003במאה וחמשים טעמים.\u0004","\u0003אמר רבינא: אני אדון ואטהרנו\u0004 על ידי שאמצא טעם לטהרו. ובאופן זה: \u0003ומה נחש שממית\u0004 אדם ובהמה \u0003ומרבה טומאה\u0004, שהרי מת מטמא אחרים במגע ובמשא ובאוהל — \u0003טהור\u0004 מלטמא, שהרי אינו ממנין שמונה שרצים המטמאים הכתובים בתורה. \u0003שרץ שאין ממית ו\u0004כן אינו \u0003מרבה טומאה — לא כל שכן\u0004 שהוא טהור!","ודוחים: \u0003ולא היא\u0004 — אין זה קל וחומר של ממש, כי אפשר לפרוך אותו בטענה שהנחש \u0003מעשה קוץ בעלמא קעביד\u0004 \u0005[בלבד הוא שעושה].\u0006 וקוץ, אם כי נזוקים בו, ואף אפשר למות על ידו, בכל זאת אינו טמא. ואף הנחש כן. ולכן נדחה קל וחומר זה.","\u0003אמר ר' אבא אמר שמואל: שלש שנים נחלקו בית שמאי ובית הלל, הללו אומרים: הלכה כמותנו והללו אומרים: הלכה כמותנו\u0004. לבסוף \u0003יצאה בת קול ואמרה: אלו ואלו דברי אלהים חיים הן, והלכה כבית הלל\u0004.","ושואלים: \u0003וכי מאחר שאלו ואלו דברי אלהים חיים\u0004 הם \u0003מפני מה זכו בית הלל לקבוע הלכה כמותן — מפני שנוחין\u0004 לבריות, \u0003ועלובין\u0004 (מניחים עצמם להיפגע, וסובלים עלבונם) \u0003היו,\u0004 וכשהיו שונין במשנה היו \u0003שונין דבריהן ודברי בית שמאי, ולא עוד אלא שמקדימין\u0004 בניסוח הדברים בדרך כבוד את \u0003דברי בית שמאי לדבריהן.\u0004","\u0003כאותה\u0004 משנה \u0003ששנינו: מי שהיה ראשו ורובו בסוכה ושלחנו בתוך הבית\u0004, נחלקו בכך חכמים: \u0003בית שמאי פוסלין\u0004 סוכה זו \u0003ובית הלל מכשירין. אמרו בית הלל לבית שמאי: לא כך היה מעשה, שהלכו זקני בית שמאי וזקני בית הלל לבקר את ר' יוחנן בן החורנית ומצאוהו יושב ראשו ורובו בסוכה ושלחנו בתוך הבית. אמרו להן בית שמאי: משם ראיה? אף הן\u0004 אותם המבקרים \u0003אמרו לו: אם כך היית נוהג, לא קיימת מצות סוכה מימיך\u0004. ומכל מקום, מכלל סגנון המשנה למדים אנו שחכמי בית הלל ספרו שהלכו \"זקני בית שמאי ובית הלל\" והקדימו בסיפור את זקני בית שמאי לזקניהם.","\u0003ללמדך שכל המשפיל עצמו — הקדוש ברוך הוא מגביהו, וכל המגביה עצמו — הקדוש ברוך הוא משפילו. כל המחזר על הגדולה — גדולה בורחת ממנו\u0004, \u0003ו\u0004להיפך: \u0003כל הבורח מן הגדולה — גדולה מחזרת אחריו. וכל הדוחק את השעה, שמתייגע לעשות דבר ולהצליח בו בדיוק בזמן שהוא חפץ בכך — שעה דוחקתו,\u0004 ואינו מצליח. \u0003ו\u0004להיפך, \u0003כל הנדחה מפני שעה\u0004 ואינו נדחק — סופו ש\u0003שעה עומדת לו\u0004 ומצליח לבסוף.","ועוד הביאו בענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שתי שנים ומחצה נחלקו בית שמאי ובית הלל: הללו אומרים: נוח לו לאדם שלא נברא יותר משנברא, והללו אומרים: נוח לו לאדם שנברא יותר משלא נברא\u0004. ואולם לבסוף \u0003נמנו וגמרו: נוח לו לאדם שלא נברא יותר משנברא, עכשיו ש\u0004כבר \u0003נברא — יפשפש במעשיו\u0004 וישתדל לתקנם. \u0003ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 \u0003ימשמש במעשיו\u0004 כלומר, יבדוק במעשים הבאים לידו אם ואיך לעשותם, כדי שלא יכשל בהם.","\u0003הקורה שאמרו\u0004 חכמים בתיקון מבוי צריך שתהא \u0003רחבה כדי לקבל אריח\u0004 (מין לבנה לבנין). \u0003ואריח\u0004 זה שאמרו, שיעורו \u0003חצי לבנה של שלשה טפחים\u0004 כלומר טפח ומחצה. ו\u0003דייה לקורה שתהא רחבה טפח\u0004 ולא טפח ומחצה \u0003כדי לקבל אריח לרחבו\u0004.","וצריכה הקורה להיות \u0003רחבה כדי לקבל אריח\u0004 וגם \u0003בריאה\u0004 (חזקה) \u0003כדי לקבל אריח\u0004 שאפשר יהא להניחו עליה ולא תתמוטט. \u0003ר' יהודה אומר: רחבה אף על פי שאין בריאה\u0004 כדי לקבל עליה אריח ממש, ולכן גם אם \u0003היתה של קש ושל קנים — רואין אותה כאילו היא של מתכת.\u0004","היתה הקורה \u0003עקומה\u0004 ואין אריח יכול להיות מונח עליה — \u0003רואין אותה כאילו היא פשוטה\u0004 (ישרה), היתה \u0003עגולה — רואין אותה כאילו היא מרובעת\u0004 וכלל אמרו לגבי רוחבה של קורה עגולה: \u0003כל שיש בהיקפו שלשה טפחים יש בו רוחב טפח\u0004."]]};
